window.DOSIK=window.DOSIK||{};DOSIK["ip_2"]={"1":[{"t":"def","term":"특허제도","text":"발명을 보호·장려함으로써 국가산업의 발전을 도모하기 위한 제도로, 이를 위해 기술공개의 대가로 특허권을 부여한다","ex":["특허제도의 역사와 산업발전의 관계, 특허의 필요성과 중요성, 한국 특허제도의 기본 원칙을 설명할 수 있어야 한다","발명이 보호받지 못해 공개되어 누구나 이용할 수 있다면 중복 연구 손실과 투자 곤란으로 산업 발전이 저해되므로, 특허제도는 기술공개의 대가로 특허권을 주어 발명을 보호·장려한다"]},{"t":"table","title":"특허제도의 연혁","head":["시기","내용"],"rows":[["1474년 베니스 공화국","특허법은 보호받을 발명은 새로워야 하고, 독점권의 지역과 기간이 제한되며, 침해에 대한 구제 방법이 제공된다는 3가지 핵심 개념을 제시하였다 · 근대적 의미의 최초 특허제도에서 특허권을 받은 사람에게 10년간 독점권이 주어졌다"],["1624년 영국","전매조례는 최초의 성문화된 특허법으로 현재 특허제도의 기초가 되었으며, 최초의 진실한 발명자에게 주어지는 14년간의 특허 이외에는 독점을 금지하였다 · 특허를 뜻하는 patent는 공개된 것을 뜻하는 라틴어 patere에서 유래했고 전매조례에서는 공개장이라는 뜻으로 letter of patent가 사용되었다"],["18세기 미국","특허제도에서 처음으로 특허를 재산권의 개념으로 인식하기 시작했다"]]},{"t":"flow","title":"우리나라 특허제도의 연혁","steps":["1882년 지석영 선생이 상소문에서 특허제도의 필요성을 제기했지만 제도화되지 못했다","1908년 한국 특허령이 공포되었다","1946년 특허원이 창립되고 처음으로 특허법이 제정되었다","1961년 특허법이 산업재산권 4법으로 분리되었다","1977년 특허청이 개청되었다","1979년 세계지식재산권기구(WIPO), 1980년 파리협약, 1984년 특허협력조약(PCT)에 가입하였다"]}],"2":[{"t":"vs","title":"권리주의와 은혜주의","cols":[{"name":"권리주의","items":["현대 특허제도에서 특허법에 의해 특허권이 부여되는 원칙","절차적·실체적 요건을 갖추면 발명자가 특허를 받을 권리를 가지고 국가는 이를 확인하여 등록한다"]},{"name":"은혜주의","items":["특허제도의 초기에 국왕 등 통치권자의 판단에 따라 특허권을 허여하는 방식"]}]},{"t":"table","title":"도달주의","head":["구분","내용"],"rows":[["원칙","특허출원 관련 서류는 특허청에 도착한 날을 제출일로 보는 도달주의가 원칙이며, 등기우편은 통신일부인이 분명하면 그 표시된 날, 불분명하면 우체국 제출일을 수령증으로 증명한 날에 도달한 것으로 본다"],["예외 없는 경우","특허권 및 특허에 관한 권리의 등록신청서류나 국제출원서류는 등기우편으로 보내더라도 예외 없이 도달주의를 적용한다"]]}],"3":[{"t":"table","title":"심사·선출원·설정등록주의","head":["원칙","내용"],"rows":[["심사주의","우리나라는 성립성·신규성·진보성·산업상 이용가능성 등 특허요건을 전부 심사해 특허 부여 여부를 결정하는 심사주의를 채택하되, 심사청구제도로 청구된 출원만 실체 심사하여 단점을 보완한다"],["선출원주의","동일 발명에 대해 둘 이상의 출원이 경합하면 먼저 출원한 자에게만 특허를 부여하는 것이며, 먼저 발명한 사람에게 권리를 주는 선발명주의와 구별된다 · 선발명주의는 출원이 늦어지고 선발명자 결정 과정에서 심사가 지연되는 문제가 있어 대부분의 국가가 권리 안정성을 위해 선출원주의를 채택한다"],["설정등록주의","특허권은 설정등록에 의하여 발생하며, 행정청의 등록이 효력 발생 요건인 등록주의를 우리나라도 채택하고 있어 이를 설정주의라 한다"],["보호대상","특허제도의 보호대상 절에서는 특허법상 발명의 성립 요건과 보호 발명이 되는 발명의 종류를 구분할 수 있어야 한다"]]}],"4":[{"t":"def","term":"발명","text":"특허법은 발명을 자연법칙을 이용한 기술적 사상의 창작으로서 고도한 것이라고 정의한다"},{"t":"table","title":"발명의 성립요건","head":["요건","내용"],"rows":[["자연법칙의 이용","자연법칙에는 열역학 법칙 같은 자연과학상 법칙뿐 아니라 경험으로 터득한 원인과 결과의 경험칙도 포함되지만, 자연법칙 그 자체는 발명이 아니고 이를 이용해야 한다"],["기술","일정한 목적 달성을 위해 실제로 이용할 수 있는 구체적이고 합리적인 실시수단으로, 제3자가 같은 방법으로 쓰면 같은 결과를 얻어야 하므로 연주·무용·체육 같은 기능은 발명이 될 수 없다 · 발명은 반드시 현실적 구체성을 띨 필요 없이 장차 기술로서 실현가능성이 있는 기술적 사상이면 충분하다"],["창작","발명은 새로 만들어 낸 것이어야 하므로 이미 존재하던 것을 찾아낸 발견과 구별되지만, 물질의 신규한 용도를 발견한 경우에는 용도발명으로 성립성이 인정될 수 있다"],["고도성","발명은 창작수준이 고도한 것이어야 하며, 물건에 대한 기술적 사상의 창작이지만 고도하지 않은 것은 실용신안의 대상인 고안이 될 수 있다"],["반복재현성","발명은 반복 실시하여 동일한 효과를 얻을 수 있어야 하며, 반복재현성은 반드시 100% 확률을 뜻하지 않고 100%보다 낮아도 효과를 얻을 수 있음이 확실하면 인정된다"],["완성된 발명","통상의 지식을 가진 자가 반복 실시하여 목적하는 기술적 효과 달성 가능성을 예상할 수 있을 정도로 구체적·객관적으로 구성된 발명이며, 과제 해결 수단이 빠졌거나 해결이 명백히 불가능하면 발명에 해당하지 않는다"],["거절이유","발명의 성립성을 정한 특허법 제2조는 제62조의 거절이유에 포함되지 않으나, 발명에 해당하지 않는 출원은 산업상 이용가능성이 없다는 이유로 거절이유가 통지된다"]]}],"5":[{"t":"table","title":"발명 제외 대상","head":["유형","내용"],"rows":[["자연법칙 그 자체","열역학 제2법칙 같은 자연법칙 그 자체는 발명이 아니며, 청구항 일부라도 자연법칙에 위배되면 발명이 아니다(영구운동 기계장치 등)"],["자연법칙 이외의 법칙 등","경제법칙·수학공식·논리학적 법칙·작도법 같은 자연법칙 이외의 법칙, 게임 규칙 같은 인위적 약속, 영업계획·금융방법 같은 정신 활동은 발명에 해당하지 않는다"],["개인의 숙련 기능","악기 연주방법이나 공 던지는 방법처럼 개인의 숙련으로 달성되는 기능은 지식으로 제3자에게 전달될 객관성이 없어 발명에 해당하지 않는다"],["정보의 제시","정보의 제시를 주된 목적으로 하고 제시되는 정보 내용에만 특징이 있는 것은 발명에 해당하지 않는다(녹음된 음악에만 특징이 있는 CD 등)"],["미적 창작물","회화·조각 같은 미적 효과 자체는 시각적이고 평가가 주관적이므로 발명에 해당하지 않는다"]]}],"6":[{"t":"vs","title":"컴퓨터 발명","cols":[{"name":"발명에 해당","items":["컴퓨터프로그램 자체는 발명이 될 수 없지만, 소프트웨어에 의한 정보처리가 하드웨어로 구체적으로 구현되면 그 정보처리장치·동작방법·기록매체는 발명에 해당한다"]},{"name":"BM발명으로 특허의 대상이 되지 않는 것","items":["순수한 영업방법, 인위적 결정·인간의 정신 활동·오프라인상의 인간 행위를 포함하는 경우","프로그램 리스트 같은 정보의 단순한 제시, 프로그램 자체, 수학공식·경제법칙·게임규칙 그 자체"]}]},{"t":"table","title":"컴퓨터 관련 발명","head":["구분","내용"],"rows":[["컴퓨터 관련 발명","컴퓨터·소프트웨어를 실시에 필요로 하는 발명으로 컴퓨터프로그램 관련 발명과 영업방법 발명을 포함하며, 클라우드컴퓨팅·빅데이터·데이터베이스·모바일 앱 관련 발명이 대표적이다"],["방법발명","컴퓨터를 사용한 발명이 시계열적으로 연결된 일련의 처리나 조작, 곧 단계로 표현될 수 있을 때 그 단계로 특정된 방법이 컴퓨터 관련 방법발명이다"],["물건발명","컴퓨터 관련 물건발명에는 복수의 기능 요소로 특정된 물건과 프로그램을 기록한 컴퓨터로 읽을 수 있는 매체, 구조를 가진 데이터를 기록한 기록 매체, 하드웨어와 결합된 매체 저장 컴퓨터프로그램이 있다"],["기재 요건","컴퓨터·소프트웨어 분야의 통상의 기술자가 출원 시 기술상식과 명세서·도면에 기재된 사항에 근거해 발명을 쉽게 실시할 수 있도록 명확하고 상세히 기재해야 한다"],["영업방법(BM) 발명","사업 아이디어를 컴퓨터·인터넷 등 정보통신기술로 구현한 새로운 비즈니스 시스템이나 방법으로, 영업방법 자체만으로는 특허를 받을 수 없고 소프트웨어 정보처리가 하드웨어로 구체적으로 실현되어야 한다"]]}],"7":[{"t":"vs","title":"물건발명과 방법발명","cols":[{"name":"물건발명","items":["발명의 내용이 물건(물질)으로 구체화되는 경우이다","협의의 물건발명: 기계·기구·장치","물질발명: 화학물질·조성물·음식물·의약품","물건발명 중 협의의 물건발명만","실용신안 보호대상에 해당한다"]},{"name":"방법발명","items":["일정한 목적을 위해 시계열적으로 관련된 행위로 구체화되는 경우이다.","시간적 요소가 필수 구성요건이면 방법발명이다","제법발명: 물건을 생산하는 방법발명","단순한 방법발명: 통신방법·측정방법·제어방법처럼","물건 생산을 수반하지 않는다"]}]}],"8":[{"t":"def","term":"용도발명","text":"물질의 특정 성질을 발견하여 그 성질을 특정 용도로 이용하는 발명으로, 속성 자체는 발견이지만 이를 새로운 용도로 연결하는 과정은 기술적 사상의 창작으로 인정되어 특허로 보호된다","ex":["DDT에 살충효과가 있다는 속성을 발견해 DDT를 유효성분으로 하는 살충제나 DDT를 벌레에 뿌려 살충하는 방법으로 특허출원하는 것이 용도발명의 예이다"]},{"t":"table","title":"의약발명","head":["구분","내용"],"rows":[["의약발명","의약으로서의 용도가 기재된 발명으로 용도발명의 일종이며, 명세서에는 약리효과·유효량·투여방법과 약리효과를 증명할 실험예 등이 기재되어야 한다"],["새로운 의약물질","제법발명과 함께 물건발명으로 특허를 받을 수 있다"],["이미 존재하는 물질","이미 존재하는 물질을 의약품으로 제조하는 방법에 기술적 특징이 있으면 제법발명으로만 특허를 받을 수 있다"]]}],"9":[{"t":"table","title":"미생물 발명","head":["구분","내용"],"rows":[["미생물발명","미생물 자체, 미생물을 생산하는 방법, 미생물을 이용하는 발명을 아우르며, 유전공학의 발달로 단순한 발견이 아니고 반복생산가능성 문제도 해결되어 특허로 보호한다"],["기탁","미생물을 쉽게 입수할 수 없는 경우에는 기탁기관에 기탁하고 출원서에 취지를 적어 증명서류를 첨부하며 수탁번호를 명세서에 기재해야 한다"],["표시","새로운 미생물을 기재할 때에는 미생물의 명명법에 따른 종명 또는 종명을 붙인 균주명으로 표시하고 균학적 성질을 함께 기재해야 한다"]]},{"t":"table","title":"동물·식물 발명","head":["구분","내용"],"rows":[["동물특허","동물 자체, 동물의 일부, 동물을 만드는 방법, 동물 이용에 관한 발명을 가리키며, 1988년 미국에서 하버드 마우스에 특허가 부여된 이래 다른 특허요건을 충족하면 동물이라는 이유만으로 배제하지 않는 것이 일반적 추세이다"],["동물발명의 기재","쉽게 입수 가능한 동물을 이용하는 방법 외의 동물발명은 동물의 특성과 제조방법을 기재하고 수정란 등을 공인된 기탁기관에 기탁하여 제3자가 쉽게 실시할 수 있음을 객관적으로 증명해야 한다"],["식물발명","과거 특허법 제31조는 무성번식 가능한 변종식물만 보호했으나 유성번식식물도 유전공학적 방법으로 반복생식할 수 있어 제31조를 삭제하였으며, 식물발명은 유무성 상관없이 특허법으로 보호한다"]]}],"10":[{"t":"table","title":"특허 주체","head":["구분","내용"],"rows":[["특허권","특허법은 발명의 보호와 이용을 도모해 산업발전에 이바지하는 것을 목적으로 하므로 일정한 요건을 갖춘 발명에만 독점배타권인 특허권을 부여한다 · 특허를 받으려면 특허법에서 정한 주체적·객관적·절차적 요건을 모두 갖추어야 하며, 심사관은 실체 심사에서 특허요건 충족 여부를 심사한다"],["권리능력","권리·의무의 주체가 될 수 있는 법률상 지위나 자격으로, 자연인과 국가·회사·학교·재단법인 같은 법인에 인정되며 특허법의 권리능력은 민법의 규정에 따른다 · 국가의 행정청 같은 국가 행정기관은 권리능력이 없어 국가기관이 출원하는 경우 출원인은 대한민국이 된다"],["재내자·재외자 외국인","국내에 주소 또는 영업소가 있는 재내자인 외국인은 권리능력이 인정되지만, 국내에 주소·영업소가 없는 재외자인 외국인은 원칙적으로 권리능력이 인정되지 않는다"],["재외 외국인의 예외","상호주의(자국이 우리 국민에 같은 조건으로 권리를 인정하는 경우), 우리나라가 인정하는 경우에 상대국도 같은 조건으로 인정하는 경우, 조약에 따라 권리가 인정되는 경우에 한해 예외적으로 권리능력이 인정된다"],["조약에 따라 권리가 인정되는 경우","조약 당사국 국민과, 당사국 국민은 아니지만 당사국에 주소·영업소가 있는 준당사국 국민(무국적자 포함)을 뜻하며 파리조약의 내외국인 평등 원칙을 반영한 것이다"]]},{"t":"tree","title":"발명자","root":"발명은 법률행위가 아닌 사실행위이므로 자연인만 발명자가 될 수 있다","branches":[["법인","법인은 권리능력이 있어도 발명능력이 없어 승계에 의해서만 특허받을 권리나 특허권의 권리자가 될 수 있다"],["인공지능","인공지능이 생성한 결과물에 대해 발명의 성립성이 인정되더라도 인공지능은 자연인이 아니므로 발명자가 될 수 없고, 법원도 현행법상 사람만이 발명자로 인정된다고 판단하였다"],["공동발명","2인 이상이 공동으로 발명하면 특허를 받을 수 있는 권리는 공유이며, 공유자 전원이 함께 특허출원을 하여야 한다 · 2인 이상이 실질적으로 협력하여 완성한 발명으로, 착상 단계에서 구체화 단계에 이르기까지 실질적으로 관여해야 하며, 공동발명자 여부는 이해관계인의 합의로 바꿀 수 없다"],["발명자 기재","특허출원서에 발명자로 기재되었다고 실제 발명자로 추정되는 것은 아니며, 발명자라는 점에 대한 증명책임은 이를 주장하는 사람에게 있다"]]}],"11":[{"t":"table","title":"특허받을 권리의 승계","head":["구분","내용"],"rows":[["발생·귀속","특허를 받을 수 있는 권리는 발명의 완성에 의해 발생하여 발명자에게 원시적으로 귀속되며, 특허권이 발생하거나 거절결정이 확정될 때까지 보호된다"],["이전","재산권의 일종으로 전부뿐 아니라 지분의 일부도 이전할 수 있으며, 출원 전에도 이전이 가능하다"],["출원 전 승계","특허출원 전에 특허를 받을 수 있는 권리를 승계한 경우에는 승계인이 특허출원을 하지 않으면 제3자에게 대항할 수 없다"],["출원 후 승계","특허출원 후에는 상속·일반승계를 제외하고 특허출원인변경신고를 해야 승계의 효력이 발생하며, 상속이나 일반승계는 지체 없이 그 취지를 특허청장에게 신고해야 한다"],["질권","특허를 받을 수 있는 권리는 특허등록 전까지는 불확실한 권리이므로 질권의 설정이 제한된다"],["승계인","당사자 간 약정이나 상속, 일반승계로 발명자로부터 적법하게 특허받을 권리를 이전받은 자이며 자연인뿐 아니라 법인도 될 수 있고, 출원 전·후를 불문하고 권리의 전부 또는 일부를 승계할 수 있다"],["무권리자의 출원","특허를 받을 수 있는 권리를 양도한 자가 자기 명의로 특허를 출원해 등록받은 경우 이는 무권리자에 의한 출원으로 특허무효사유에 해당한다"]]},{"t":"def","term":"특허청 직원의 특허 제한","text":"특허청 직원 및 특허심판원 직원은 상속 또는 유증의 경우를 제외하고는 재직 중 특허를 받을 수 없다","ex":["특허청·심판원 직원은 특허관계 업무를 다루며 타인의 출원 내용을 도용할 가능성이 있고, 심사관이 자기 출원에 특허를 줄 폐해를 막기 위해 특허를 받을 수 없도록 한다","특허청 및 특허심판원 직원은 상속 또는 유증으로 취득하는 경우를 빼고는 재직 중 특허를 받을 수 없다"]}],"12":[{"t":"table","title":"산업상 이용가능성","head":["구분","내용"],"rows":[["이용가능성","산업상 이용가능성이 없는 발명은 특허를 받을 수 없으며, 이용가능성은 동일결과를 반복 실시할 수 있는 가능성으로 출원 시 해당 분야에서 이용되지 않더라도 장래에 실시할 수 있으면 인정된다 · 이용가능성이란 동일한 결과를 반복해 실시할 수 있는 가능성으로, 출원 당시 이용되지 않더라도 장래 실시 가능하면 인정된다"],["개인적·실험적 이용","개인적·실험적·학술적으로만 이용 가능하고 업으로 이용될 가능성이 없는 발명은 산업상 이용가능성이 없지만, 시판 또는 영업의 가능성이 있다면 인정된다"],["현실적으로 불가능","이론적으로는 실시할 수 있어도 현실적으로 전혀 불가능함이 명백한 발명(지구표면 전체를 자외선 흡수 플라스틱으로 둘러싸는 방법 등)은 산업상 이용가능성이 없다"]]},{"t":"vs","title":"의료 관련 발명","cols":[{"name":"산업상 이용가능성이 없는 것","items":["인간을 수술·치료·진단하는 방법의 발명은 산업상 이용가능성이 없다고 보아 특허를 받을 수 없으며, 청구항에 의료행위를 불가분의 구성요소로 포함하는 방법발명도 마찬가지이다","사람을 수술·치료·진단하는 방법의 발명은 산업상 이용할 수 있는 발명에 해당하지 않는 것으로 취급한다","의료인이 하지 않더라도 질병의 치료·예방·건강증진을 위한 처치방법의 발명은 산업상 이용가능성이 없는 것으로 본다"]},{"name":"산업상 이용할 수 있는 것","items":["인간의 수술·치료·진단에 사용하는 의료기기 그 자체나 의약품 그 자체는 산업상 이용할 수 있는 발명에 해당한다 · 의료기기 자체나 의약품 자체의 발명도 마찬가지이다","인체로부터 배출·채취된 것(소변·혈액·세포 등)을 처리하는 방법이 의료행위와 분리 가능한 별개 단계이거나 단순한 데이터 수집 방법이면 산업상 이용가능한 것으로 취급한다","수술·치료·진단 방법의 발명이 인간 이외의 동물에만 한정된다고 청구범위에 명시되어 있으면 산업상 이용할 수 있는 발명으로 취급한다","치료와 비치료 효과를 함께 가진 인체 처치 방법이라도 청구항이 미용 같은 비치료적 용도로만 한정되고 분리할 수 있으며 건강증진 효과가 부수적이면 산업상 이용할 수 있는 발명으로 취급한다"]}]}],"13":[{"t":"table","title":"신규성","head":["구분","내용"],"rows":[["신규성","특허출원 전에 국내외 공지기술과 동일하지 않은 것을 말하며, 신규한 발명을 공개한 자에게만 공개의 대가로 특허권을 부여하기 위한 요건이다"],["공지","불특정 다수인이 알 수 있는 상태에 놓인 것으로, 비밀유지 의무가 있는 회사 동료가 아는 것은 공지가 아니다"],["공연실시","비밀이 해제된 상태에서 발명을 실시한 것을 말하며 공용이라고도 한다"],["간행물","간행물 게재가 신규성 상실사유가 되려면 통상의 기술자가 쉽게 실시할 수 있을 정도로 게재되어야 하며, 언어의 종류는 묻지 않는다"],["전기통신회선","전기통신회선을 통해 공중이 이용할 수 있게 된 발명에는 인터넷뿐 아니라 이메일 그룹, 공중게시판 등에 올린 것도 포함된다"],["판단시점·지역","신규성 판단시점은 출원 시이며 출원의 시각까지 포함하고, 지역 기준은 국제주의여서 외국의 공지도 국내와 동일하게 본다 · 우선권주장 출원이나 분할출원 같은 특수한 출원은 신규성 판단시점이 원출원 시점까지 소급된다"]]},{"t":"flow","title":"공지예외 규정","steps":["신규성을 상실한 발명이더라도 일정 요건을 갖추면 신규성·진보성 판단 시 선행기술로 삼지 않도록 하는 제도다","공지기술이 된 날부터 12개월 이내에 특허출원을 해야 한다","본인 의사에 의한 공지는 출원서에 그 취지를 적고 출원일부터 30일 이내에 증명서류를 제출하며, 보완수수료를 내면 추후 제출도 가능하다","신규성 상실의 예외 규정은 해외 출원에서 소급되지 않으며, 국가마다 인정기간과 사유가 다르다"]}],"14":[{"t":"table","title":"진보성","head":["구분","내용"],"rows":[["진보성","통상의 기술자가 공지기술로부터 쉽게 발명할 수 없을 정도의 창작 난도가 있는 것을 말한다 · 공지기술과 동일하지 않아 신규성이 있어도 창작수준이 낮으면 진보성이 없어 특허를 받을 수 없다"],["종합 판단","진보성은 구성의 곤란성을 중심으로 목적의 특이성과 효과의 현저성을 참작하여 종합적으로 판단한다"],["구성의 곤란성","공지기술과 차이 있는 구성을 도출한 뒤 공지기술로부터 동기가 유발되는지, 통상의 창작능력 발휘로 이를 수 있는지를 살핀다"],["효과의 현저성","공지기술과 이질적인 효과이거나 동질이더라도 현저히 우수하여 통상의 기술자가 예측할 수 없던 효과인지로 판단한다"],["상업적 성공","상업적 성공에 의한 모방품 발생 등은 진보성 긍정 자료로 참고할 수 있으나 그것만으로 진보성 유무를 판단해서는 안 된다"]]}],"15":[{"t":"table","title":"선출원과 확대된 선출원","head":["구분","내용"],"rows":[["선출원주의","동일한 기술사상에 대해 출원일을 기준으로 먼저 출원한 자에게만 특허를 부여하는 제도다 · 서로 다른 날 동일 발명이 둘 이상 출원되면 먼저 출원한 자만 특허를 받고, 같은 날 출원되어 협의가 안 되면 모두 거절된다"],["선출원의 지위가 없는 경우","선출원이 무효·포기·거절결정 확정·취하되었거나 선출원인이 무권리자이면 선출원의 지위가 없어 후출원이 특허를 받을 수 있다"],["확대된 선출원","선출원 후 공개·공고된 출원의 최초 명세서·도면에 있는 발명과 동일한 후출원 발명은 특허받지 못하게 하는 제도다 · 후출원과 선출원의 발명자가 동일하거나, 후출원 시점의 출원인이 선출원 출원인과 동일하면 적용되지 않는다"],["비교 대상","선출원주의는 선후출원의 청구범위를 비교하지만 확대된 선출원은 선출원의 최초 명세서·도면과 후출원의 청구범위를 비교한다"],["공개 여부","확대된 선출원의 지위는 다른 출원이 출원공개·등록공고된 경우에만 인정되지만 선출원주의는 공개 여부와 관계없이 적용된다 · 무권리자의 출원이 공개·공고되면 제3자에 대해서는 확대된 선출원의 지위가 인정되나, 정당한 권리자에 대해서는 인정되지 않는다"]]}],"16":[{"t":"tree","title":"불특허사유","root":"공공의 질서 또는 선량한 풍속에 어긋나거나 공중의 위생을 해칠 우려가 있는 발명은 특허를 받을 수 없다","branches":[["판단 기준 시점","공서양속의 개념은 시대에 따라 변하므로 불특허사유 여부는 특허여부결정 시를 기준으로 판단한다"],["방법발명","방법발명 자체는 공서양속에 반하지 않아도 그 방법으로 제조된 물건이 사회질서를 해칠 우려가 있으면 불특허사유에 해당할 수 있다"],["인체","인체를 구성요소로 하여 실행 시 필연적으로 신체를 손상하거나 신체의 자유를 비인도적으로 구속하는 발명은 불특허사유에 해당한다"]]}],"17":[{"t":"table","title":"출원서류","head":["구분","내용"],"rows":[["출원","발명자가 특허권을 받으려면 특허법이 정한 절차와 방식에 따라 출원해야 한다 · 특허를 받을 권리를 가진 자가 발명의 공개를 전제로 특허청에 특허 등록을 받겠다는 의사를 표시하는 행위다 · 특허에 관한 절차는 서면주의를 취하여 발명 내용의 특정, 권리 내용의 명확화, 발명의 공개를 도모한다"],["특허출원서","특허출원서에는 발명의 설명과 청구범위를 적은 명세서, 필요한 도면, 요약서를 첨부하여 특허청에 제출해야 한다 · 발명자와 출원인의 인적 사항, 출원에 필요한 기초사항, 특허법상 제도의 적용을 받기 위한 각종 취지를 적은 서면이다"],["명세서","기능적으로 발명의 기술 내용을 설명하는 발명의 설명과 보호받고자 하는 사항을 적는 청구범위로 구분된다 · 청구범위는 등록 전에는 권리요구서, 등록 후에는 권리서의 역할을 하고, 발명의 설명은 이를 뒷받침하는 권리해설서 역할을 한다 · 일반 공중에게 발명의 설명은 기술문헌 역할을 하고 청구범위는 자유기술영역과 독점배타영역의 경계를 특정한다"]]},{"t":"flow","title":"출원 후 절차","steps":["특허출원이 이루어지면 특허청은 발명을 공개하고 특허요건 충족 여부를 심사한다","방식심사를 거쳐 출원 후 1년 6개월에 공개되고, 심사청구가 있어야 실체심사로 진행되며 심사청구가 없으면 취하간주된다","특허결정이 되면 등록을 거쳐 특허권이 발생한다"]},{"t":"table","title":"고객번호와 도달주의","head":["구분","내용"],"rows":[["특허고객번호","특허절차를 밟으려는 개인·법인은 특허고객번호를 미리 부여받아야 하며, 출원서에 이를 적으면 주소를 따로 적지 않아도 된다"],["도달주의","특허청에 제출하는 서류는 도달한 날부터 효력이 발생하는 도달주의가 원칙이나, 우편 제출은 통신일부인에 표시된 날에 도달한 것으로 본다"]]}],"18":[{"t":"table","title":"명세서·청구범위 기재요건","head":["요건","내용"],"rows":[["발명의 설명","통상의 기술자가 쉽게 실시할 수 있도록 명확·상세하게 적고 발명의 배경이 되는 기술을 적어야 한다"],["청구범위","청구항이 하나 이상 있어야 하며, 각 청구항은 발명의 설명에 의해 뒷받침되고 발명이 명확·간결하게 적혀야 한다"],["뒷받침 요건 위반","청구항에 구체적 수치한정이 있는데 발명의 설명에는 그 수치가 전혀 적혀 있지 않다면 청구항이 발명의 설명에 의해 뒷받침되지 않는 경우다 · 청구항이 특정 기능을 수행하는 수단이나 공정으로 적혀 있는데 대응하는 구체적 내용이 발명의 설명에 없으면 뒷받침 요건 위반이다 · 발명의 설명의 실시예를 통상의 지식으로도 청구된 발명의 전 범위로 확장·일반화할 수 없다면 청구항이 뒷받침되지 않는 것이다"],["명확성 요건 위반","발명을 이루는 구성요소가 나열만 되어 있고 그 결합관계가 적혀 있지 않아 발명이 불명확하면 명확성 요건을 위반한 것이다 · 「소망에 따라」「필요에 따라」「및/또는」 같은 자구와 함께 임의 부가사항이나 선택사항을 적은 표현은 원칙적으로 구성을 불명확하게 한다 · 「주로」「적당한」「대략」「약」처럼 비교 기준이나 정도가 불명확한 표현은 청구항의 명확성을 해칠 수 있다 · 하나의 청구항 안에서 「120~200℃, 바람직하게는 150~180℃」처럼 이중으로 수치한정을 하면 불명확한 기재가 된다"],["간결성","청구항에 상업상의 이점이나 판매 지역·판매처처럼 발명의 기술적 구성과 무관한 사항을 적으면 발명이 명확·간결하지 않게 된다"],["도면 대용","합금 성분 간의 특정한 관계처럼 수치나 문장만으로 표현하기 어려운 경우에는 청구항에서 도면의 기재를 대용할 수 있다"],["필수 구성요소","청구항에는 발명을 특정하는 데 필요한 구조·방법·기능·물질 또는 이들의 결합관계 등을 적어야 하고 필수 구성요소를 포함해야 한다"]]}],"19":[{"t":"table","title":"출원공개","head":["구분","내용"],"rows":[["출원공개제도","심사청구 여부와 관계없이 출원일부터 1년 6개월이 지난 후 특허공보에 게재하여 사회 일반에 공표하는 제도다 · 출원인의 조기공개신청이 있으면 출원일부터 1년 6개월이 지나기 전이라도 출원공개를 할 수 있다"],["취지","심사 지연으로 인한 중복 투자·중복 연구를 줄이고 공개된 기술을 제3자가 이용하게 하려는 취지로 도입되었다"],["후출원 방지","출원공개 전 출원에는 확대된 선출원의 지위로, 출원공개 후 출원에는 공지기술의 지위로 후출원의 등록을 막을 수 있다"]]},{"t":"table","title":"보상금청구권","head":["구분","내용"],"rows":[["보상금청구권","출원공개 후 경고를 받거나 공개 사실을 알고 업으로 실시한 자에게 그때부터 설정등록 시까지의 실시에 대한 합리적 보상금을 청구하는 권리다"],["행사 기간","해당 특허출원에 대한 특허권의 설정등록이 있은 후 3년 이내에 행사해야 한다"],["특허권과의 관계","보상금청구권 행사는 특허권 행사에 영향을 주지 않으며, 설정등록 후의 실시에 대해서는 특허권에 기한 민형사상 조치를 할 수 있다"],["소멸","출원공개 후 특허출원이 포기·무효·취하되거나 특허거절결정이 확정되면 보상금청구권은 처음부터 발생하지 않은 것으로 본다"]]}],"20":[{"t":"table","title":"심사청구","head":["구분","내용"],"rows":[["심사청구제도","출원일로부터 3년 이내에 심사청구가 있는 출원에 한하여 심사청구의 순서에 따라 심사하는 제도다 · 심사청구기간은 2016년 개정으로 5년에서 3년으로 단축되었다"],["청구인","심사청구는 출원인뿐 아니라 누구든지 할 수 있으나, 청구범위 제출 유예를 이용해 청구범위를 적지 않았거나 외국어출원의 번역문을 내지 않은 경우에는 할 수 없다"],["대상","심사청구 시 출원발명이 적법하게 출원계속 중이어야 하므로 취하·포기 또는 무효된 출원은 심사청구의 대상이 될 수 없다"],["청구 기간","특허출원일부터 3년 이내에 할 수 있고, 그 기간에 심사청구가 없으면 출원은 취하한 것으로 본다"],["동시 청구","출원 시 심사청구를 동시에 하면 특허결정 시 청구범위가 확정되어 보정기회를 잃고 비용도 빨리 늘므로 사업계획에 맞춰 시기를 정한다"],["심사청구료","독립항·종속항을 불문하고 청구항 수별로 납부하며, 일정한 경우 감면 또는 면제될 수 있다 · 출원인이 아닌 자가 심사청구한 뒤 출원인이 보정으로 청구항을 늘리면 그 증가분의 심사청구료는 출원인이 납부해야 한다"],["공보 게재·통지","특허청장은 출원공개 전에 심사청구가 있으면 출원공개 시에, 출원공개 후 심사청구가 있으면 지체 없이 그 취지를 특허공보에 게재한다 · 출원인이 아닌 자가 심사청구를 하면 특허청장은 그 취지를 출원인에게 통지하여 심사절차 준비기간을 준다"],["심사 순서","심사청구가 있으면 청구 순서에 따라 실체심사가 이루어지며, 한번 한 출원심사의 청구는 취하할 수 없다 · 심사청구된 출원을 분할·분리출원하거나 심사청구된 실용신안을 특허출원으로 변경출원하여 심사청구한 경우에는 원출원의 심사청구 순서에 따른다"]]}],"21":[{"t":"table","title":"실체심사와 거절이유","head":["구분","내용"],"rows":[["실체심사","산업상 이용가능성·신규성·진보성 등 특허요건을 판단하는 심사로, 일반인이 쉽게 실시할 수 있게 기재했는지(기재요건)도 함께 심사한다"],["거절이유 통지","심사관이 거절이유를 발견하면 거절이유를 통지하고, 출원인은 보정하거나 의견서를 제출해 대응할 수 있으며 거절이유가 없으면 특허결정을 해야 한다"],["주체적 특허요건 위반","외국인으로서 특허권을 향유할 수 없는 자의 출원이나 무권리자의 출원은 주체적 특허요건 위반으로 거절이유가 된다"],["실체적 특허요건 위반","선출원주의 위반과 공서양속에 반하는 발명은 실체적 특허요건 위반으로 거절이유가 된다"],["절차적 특허요건 위반","명세서 기재요건 위반과 하나의 특허출원 범위 위반은 절차적 특허요건 위반으로 거절이유가 된다"],["보정 관련","보정이 신규사항을 추가한 경우나 분할·분리·변경출원의 범위를 벗어난 경우도 거절이유에 해당한다"],["항별 검토","심사관은 청구항별로 거절이유를 검토하되 일부 항의 거절이유가 극복되지 않으면 출원발명 전체에 대해 거절결정을 한다"]]},{"t":"table","title":"거절이유통지","head":["구분","내용"],"rows":[["의견서 제출기간","의견서 제출기간은 2개월이며 최대 4개월까지 자동 연장할 수 있다"],["최초거절이유통지","거절이유통지를 처음 받거나 최후거절이유통지가 아닌 거절이유통지를 말한다"],["최후거절이유통지","최초거절이유통지에 대한 보정으로 발생한 새로운 거절이유에 대해 하는 통지다"],["자진 보정","출원인은 특허결정 등본을 송달받기 전이면서 최초거절이유를 송달받기 전에는 자진하여 보정할 수 있다"],["재심사","최초거절이유통지 후 보정이 있으면 보정 내용을 반영한 명세서로 재심사하고, 거절이유가 해소되지 않으면 거절결정을 한다"]]}],"22":[{"t":"table","title":"보정","head":["구분","내용"],"rows":[["보정","명세서나 도면의 불명확·미비한 점을 치유하기 위해 출원인이 하는 보충·정정으로, 출원인의 권리 보호와 심사 촉진을 위해 인정된다"],["보정 시기","거절이유통지를 받은 뒤의 보정은 해당 통지에 따른 의견서 제출기간에만 할 수 있고, 재심사를 청구할 때에도 보정할 수 있다"],["최후거절이유통지에 대한 보정","신규사항 추가금지뿐 아니라 청구범위 보정범위의 제한도 지켜야 하며, 보정으로 새로운 거절이유가 생기면 안 된다 · 청구범위 보정은 청구항을 한정·삭제하거나 부가하여 청구범위를 감축하는 경우, 잘못 기재된 사항을 정정하는 경우, 불분명한 사항을 명확하게 하는 경우 등으로 제한된다"],["보정의 효과","적법한 보정이 있으면 그 출원은 보정된 내용에 따라 소급하여 출원된 것으로 취급한다"],["보정범위 위반","보정범위를 위반한 보정에 대해 심사관은 보정각하결정을 하고 보정 전 명세서로 심사하며, 출원인은 보정각하결정에 별도로 불복할 수 없다"]]},{"t":"table","title":"분할출원과 분리출원","head":["구분","내용"],"rows":[["분할출원","둘 이상의 발명이 포함된 원출원의 일부를 별개의 특허출원으로 나누는 것이며, 원출원을 한 때에 출원한 것으로 본다"],["분할출원 시기","자진 보정 가능 기간, 거절결정등본 송달일부터 3개월 이내, 또는 특허결정 등본 송달일부터 3개월 이내(설정등록일이 더 빠르면 그날까지)에 할 수 있다"],["활용","일부 청구항에 대해서만 거절이유통지를 받았다면 거절이유 없는 청구항을 분할출원하여 먼저 등록받고 나머지는 거절이유를 별도로 다툴 수 있다"],["분리출원","거절결정불복심판청구가 기각된 경우 심결등본 송달일부터 30일 이내에 출원의 일부를 새로운 특허출원으로 분리하는 것이다 · 2022년 개정으로 심결취소의 소 제기 전까지 특허 가능한 청구항을 새로운 출원으로 분리해 추가 권리를 얻을 수 있게 되었다"],["분리출원의 범위","분리출원의 명세서 또는 도면에 기재된 발명은 원출원의 출원서에 최초로 첨부한 명세서 또는 도면에 기재된 사항의 범위 안에 있어야 한다"]]}],"23":[{"t":"table","title":"설정등록과 공고","head":["구분","내용"],"rows":[["설정등록","특허권의 설정등록을 받으려면 설정등록일부터 3년분의 특허료를 내야 하며, 특허결정등본 송달일부터 3개월 내에 이를 내면 특허청장이 직권으로 등록한다"],["특허권의 발생","특허권은 설정등록에 의하여 발생하며 설정등록이 있으면 출원인은 특허권자가 되고 출원발명은 특허발명이 된다"],["등록공고","심사를 거쳐 특허가 확정된 발명의 내용을 일반에 알려 침해를 예방하려는 절차로, 출원발명의 조기 공표를 위한 출원공개와는 취지가 다르다"],["정보제공제도","특허출원이 있을 때 누구든지 그 출원이 거절이유에 해당해 특허될 수 없다는 정보를 증거와 함께 특허청장에게 제공할 수 있는 제도다 · 특허청에 계속 중인 출원에 대해 가능하며, 배경기술 기재·다항제 기재방법·하나의 특허출원 범위 위반을 제외한 거절이유에 관한 정보를 낼 수 있다"]]},{"t":"table","title":"재심사","head":["구분","내용"],"rows":[["직권 취소","특허결정 이후에도 설정등록 전까지 심사관이 명백한 거절이유를 발견하면 직권으로 특허결정을 취소하고 재심사할 수 있다"],["재심사청구","특허결정등본 송달일부터 설정등록 전까지, 또는 특허거절결정등본 송달일부터 3개월 이내에 명세서·도면을 보정하면서 할 수 있다"],["청구할 수 없는 경우","재심사를 청구할 때 이미 재심사에 따른 결정이 있었거나, 거절결정불복심판청구가 있는 경우, 또는 분리출원인 경우에는 재심사를 청구할 수 없다"],["효과","재심사청구가 있으면 종전의 특허결정 또는 거절결정은 취소된 것으로 보며, 재심사의 청구는 취하할 수 없다"]]},{"t":"table","title":"특허취소신청","head":["구분","내용"],"rows":[["신청 기간","누구든지 특허권의 설정등록일부터 등록공고일 후 6개월이 되는 날까지 특허취소를 신청할 수 있다"],["대상","신규성·진보성·선출원 위반의 하자가 있는 특허에 대해 특허심판원에 청구항별로 할 수 있다"],["취소결정","특허취소결정이 확정되면 특허권은 소급하여 소멸하며, 취소결정에 앞서 취소이유에 대한 의견제출기회를 반드시 주어야 한다"]]}],"24":[{"t":"table","title":"특허권의 존속기간","head":["구분","내용"],"rows":[["특허권","발명의 공개를 대가로 발명자에게 부여되는 독점배타권이므로 특허권자는 특허발명을 업으로 실시할 권리를 갖는다"],["존속기간","설정등록한 날부터 특허출원일 후 20년이 되는 날까지다"],["허가·등록 지연 연장","허가·등록을 위한 시험으로 장기간 실시하지 못한 대통령령 지정 발명은 실시하지 못한 기간에 대해 5년까지 존속기간을 한 차례만 연장할 수 있다"],["등록 지연 연장","출원일부터 4년과 심사청구일부터 3년 중 늦은 날보다 설정등록이 지연되면 그 지연된 기간만큼 존속기간을 연장할 수 있다"]]},{"t":"vs","title":"특허권의 효력","cols":[{"name":"적극적 효력","items":["독점성에 기인한 효력으로, 특허권자만이 특허발명을 업으로 실시할 수 있는 전용권을 갖는 것이다"]},{"name":"소극적 효력","items":["배타성에 기인한 효력으로, 정당한 권원 없는 제3자의 실시를 침해라 하여 금지청구와 손해배상청구 등으로 배제할 수 있는 권리다"]}]},{"t":"table","title":"효력의 범위","head":["구분","내용"],"rows":[["속지주의","특허권의 효력은 속지주의에 따라 우리나라 영토 안에서만 미치며, 국내에 있는 자에 대해서는 내·외국인을 불문하고 효력이 미친다"],["업으로서의 실시","실시의 빈도·규모·영리 여부가 문제 되지 않으며, 단순한 개인적·가정적 실시는 제외한다는 것이 다수설이다"],["예","세탁업자가 특허발명품인 전기세탁기를 1회 사용한 것은 업으로서의 실시지만, 가정주부가 가정에서 장기간 사용한 것은 업으로서의 실시가 아니다"]]}],"25":[{"t":"table","title":"실시","head":["구분","내용"],"rows":[["실시","특허법상 실시란 발명 또는 특허발명을 그 발명의 내용에 따라 사용하는 것이며, 특허법이 실시행위의 개념을 법적으로 정의하고 있다"],["물건발명의 실시","그 물건을 생산·사용·양도·대여·수입하거나 양도·대여의 청약(전시 포함)을 하는 행위다"],["방법발명의 실시","그 방법을 사용하는 행위이며, 2020년 개정으로 방법의 사용을 청약하는 행위도 실시에 포함되었다"],["물건을 생산하는 방법발명의 실시","그 방법의 사용·청약 외에 그 방법으로 생산한 물건을 사용·양도·대여·수입하거나 양도·대여를 청약하는 행위도 포함된다"],["독립성","각각의 실시행위는 특허권의 효력상 서로 독립적이어서, 한 단계의 실시행위가 적법하더라도 다른 단계의 행위까지 적법해지는 것은 아니다 · 침해자로부터 선의로 적법하게 특허발명품을 구입한 자가 이를 업으로 사용·판매하면 별개의 독립적 실시행위로서 또 다른 특허권 침해가 된다"],["소지·구입·보관","특허품의 단순한 소지·구입·보관은 법문상 실시에 해당하지 않지만, 양도·대여 목적으로 소지하면 침해 개연성이 있어 특허권자가 침해 예방 조치를 취할 수 있다"]]},{"t":"table","title":"권리소진과 병행수입","head":["구분","내용"],"rows":[["권리소진","특허권자 또는 적법한 제조·판매권을 가진 자가 판매한 특허제품을 적법하게 구입했다면, 구입자가 그것을 사용하거나 전매해도 특허권 침해가 아닌데 이를 권리소진이라 한다"],["필요한 이유","권리소진은 양수인·전득자의 보호, 유통 과정의 보호, 권리자의 이중 이득 금지라는 이유에서 필요하다"],["병행수입","상품을 국내에 수입할 정당한 권원을 가진 자 이외의 제3자가 다른 유통경로로 진정상품을 국내 독점수입권자의 허락 없이 수입하는 것이다"],["진정상품","외국에서 적법하게 발명을 실시할 수 있는 자(외국 특허권자·전용실시권자·통상실시권자)에 의해 생산·유통된 상품을 말한다"],["침해 여부","수출국과 수입국의 특허권자가 동일인이 아니면 속지주의에 따라 병행수입이 수입국 특허권 침해가 되지만, 동일인이면 침해가 되지 않는다고 보는 것이 세계적 경향이다"]]}],"26":[{"t":"table","title":"특허권 효력의 제한","head":["제한","내용"],"rows":[["연구 또는 시험","연구 또는 시험을 위한 특허발명의 실시에는 특허권의 효력이 미치지 않으며, 그 시험이 업으로 행해지는 경우에도 마찬가지다"],["단순 통과","단순히 국내를 통과하는 데 불과한 선박·항공기·차량 또는 이에 사용되는 기계·기구에는 특허권의 효력이 미치지 않는다"],["출원 시 현존 물건","특허출원을 한 때부터 국내에 있는 물건에는 특허권의 효력이 미치지 않으며, 이는 출원 시에 현존하던 물품을 보호하는 규정이다"],["조제행위","둘 이상의 의약을 혼합해 제조하는 의약의 발명이나 그 제조방법의 발명에 대한 특허권은 약사법에 의한 조제행위와 그 조제에 의한 의약에는 효력이 미치지 않는다"]]}],"27":[{"t":"table","title":"실시권","head":["구분","내용"],"rows":[["실시권","특허권자 이외의 자가 업으로서 특허발명을 실시할 수 있는 권리이며, 특허권에 부수하는 권리이므로 특허권이 소멸하면 함께 소멸한다"],["허락·법정·강제실시권","허락실시권은 당사자의 의사로, 법정실시권은 법률 규정으로, 강제실시권은 법률 규정의 만족과 심판 또는 특허청장의 결정으로 발생한다 · 허락실시권은 전용실시권과 통상실시권이 모두 있으나 법정실시권과 강제실시권은 통상실시권만 존재한다"],["공유","특허권이 공유인 경우 각 공유자는 계약으로 달리 정하지 않는 한 다른 공유자의 동의 없이 특허발명을 자신이 실시할 수 있다"]]},{"t":"vs","title":"전용실시권과 통상실시권","cols":[{"name":"전용실시권","items":["특허발명을 독점·배타적으로 실시할 수 있는 물권적 권리이다","계약과 등록으로 발생한다","물권적 성질이어서 타인(특허권자 포함)의 실시를 금지할 수 있다","사업과 함께 이전하거나 상속·일반승계 외에는 특허권자의 동의가 있어야 이전할 수 있다","특허권자의 동의가 있으면 통상실시권을 허락할 수 있다","설정·이전·변경·소멸은 등록이 효력발생요건이다"]},{"name":"통상실시권","items":["독점·배타성 없이 실시할 수 있는 채권적 권리다","허락에 의한 통상실시권은 계약만으로 발생한다","타인의 실시를 금지할 수 없고 중복 설정이 가능하다","통상실시권자는 다른 사람에게 실시권을 허락할 수 없다","변동은 등록이 대항요건이며 법정실시권은 등록 없이도 대항할 수 있다"]}]},{"t":"table","title":"질권과 포기","head":["구분","내용"],"rows":[["질권","전용실시권에 질권을 설정하려면 특허권자의 동의가 필요하고, 재정실시권과 통상실시권허락심판에 의한 실시권에는 질권을 설정할 수 없다"],["특허권 포기","특허권자가 특허권을 포기할 때 전용실시권자와 허락에 의한 통상실시권자의 동의가 필요하지만, 강제실시권에 대해서는 동의권이 없다"]]}],"28":[{"t":"vs","title":"특허권의 소멸","cols":[{"name":"장래를 향해 소멸","items":["존속기간 만료, 특허료 불납, 상속인 없음, 특허권 포기","특허권이 장래를 향해 소멸한 경우에도","소멸 전까지는 특허권이 유효하므로","그 기간의 제3자 실시는 침해가 될 수 있다"]},{"name":"소급하여 소멸","items":["특허무효심판의 인용심결 확정이나","특허취소신청에 의한 취소결정 확정으로","특허권이 소멸하면 처음부터 없었던 것으로 보아","제3자의 실시는 침해가 되지 않는다"]}]},{"t":"def","term":"특허권의 소멸","text":"유효하게 발생한 특허권이 법정사유로 장래를 향해 효력을 잃거나 · 소급하여 처음부터 없었던 것으로 보는 것이다"}],"29":[{"t":"table","title":"출원국 선택 기준","head":["기준","내용"],"rows":[["속지주의","특허권은 속지주의에 따라 특허를 부여한 국가의 영역 안에서만 독립적으로 효력이 발생하므로, 해외에서 보호받으려면 해당 국가에서 특허권을 얻어야 한다"],["시장","시장을 기준으로 출원국을 정할 때에는 그 국가가 특허가 적용될 제품의 현재 및 미래 시장인지 확인해야 하며, 시장 규모가 크다는 이유만으로 선택해서는 안 된다"],["생산","국경 조치는 침해품의 유입만 막을 뿐 생산 자체는 막지 못하므로, 침해품 생산을 금지하려면 생산이 이루어지는 국가에 출원해 특허권을 확보해야 한다"],["경쟁사 견제","경쟁사의 견제를 피하려는 목적의 해외출원이라면 시장과 생산을 함께 고려하되 시장에 비중을 두어야 한다"],["비용","해외출원 시에는 특허권 획득으로 예측되는 수익이 출원뿐 아니라 사건 대응·설정등록·권리 행사까지 포함한 비용을 상회하는지 고려해야 한다"],["제품 수명","국가마다 등록까지 걸리는 시간이 다르므로 제품의 라이프 사이클이 특허권 획득에 소요되는 기간보다 충분히 긴지 고려해야 한다"],["권리 행사","해당 국가에서 등록된 특허권을 행사하기 쉬운지, 즉 법원이 외국인에게 불리하지 않은지와 가처분 같은 신속한 구제제도가 있는지도 출원국 선택의 요소다"]]}],"30":[{"t":"table","title":"외국 직접출원과 유럽출원","head":["구분","내용"],"rows":[["직접 출원","외국 특허청에 직접 출원하는 방법은 출원할 국가가 1~2개국이거나 신속한 심사 결과를 원하는 경우에 적합하다"],["유럽 특허청 출원","한 번의 등록결정 후 개별국에 등록료만 납부해 개별국에서 유효한 특허권을 확보할 수 있다 · 유럽에서 3~4개국 이상 특허권을 확보하려는 경우 직접 출원보다 비용이 저렴하지만 심사기간이 오래 걸리는 단점이 있다"],["런던협정","2008년 발효된 런던협정에 따라 개별국에서 등록할 때 번역문 제출 의무가 없어졌으나, 특허권을 행사할 때에는 번역문 제출이 필요하다"],["유럽 단일 특허제도","2023년 6월부터 시행된 제도에서는 유럽 특허청에서 등록결정을 받은 뒤 단일특허 발효를 신청하면 모든 비준 국가에서 동일한 효력의 특허를 취득할 수 있다"]]}],"31":[{"t":"table","title":"PCT 국제출원","head":["구분","내용"],"rows":[["PCT 출원","특허협력조약에 따라 하나의 방식과 언어로 PCT 동맹국에서 동시에 특허출원하는 것과 같은 효과를 얻는 방법이다 · PCT 방식으로 하나의 국제출원을 하면 지정한 여러 나라에 동시에 출원한 것과 같은 효과가 생긴다"],["국제단계","국제조사, 국제공개, 국제예비심사의 3개 절차로 세분된다 · 국제공개는 국제출원서류 일체(국제조사보고서와 견해서 포함)를 전자적 형태로 공개하는 절차다"],["일정","국내출원 후 12개월 이내에 국제출원을 하고, 국제공개는 18개월경이며, 번역문 제출로 국내단계 진입은 우선일로부터 30개월 이내(일부 31개월)에 한다"],["우선권주장 수반 PCT 출원","국내출원 후 1년 이내에 PCT 출원을 하고 국내출원일부터 30/31개월에 지정국 국내 단계에 진입하며, 이 방식이 가장 많이 이용된다 · 우리나라 최초 출원일부터 1년 이내에 외국에 출원하면 해당 국가의 실체심사에서 우리나라 최초 출원일을 기준으로 심사하므로, 해외출원을 급하게 서두르지 않아도 된다"]]},{"t":"vs","title":"PCT 출원의 장단점","cols":[{"name":"장점","items":["한 번의 출원으로 각 지정국에 직접 출원한 것과 같은 효과를 누리고, 등록 가능성이 낮으면 국내 단계에 진입하지 않고 비용을 절약할 수 있다","국내 단계 진입기간이 30개월 또는 31개월까지 확보되어 해외 진출 결정을 늦출 수 있다","국내 단계 진입 시기를 달리해 비용을 분산할 수 있다","국제조사보고서 등을 보고 등록 가능성이 낮으면 국내 단계 진입을 포기해 불필요한 비용을 아낄 수 있다"]},{"name":"단점","items":["별도 비용이 들고 지정국 국내 단계에 진입하면 개별 출원과 같은 비용이 추가로 들어 비용 부담이 가중되며 조기 권리 확보가 어려울 수 있다","국제출원료와 국제조사료가 추가로 든다"]}]}],"32":[{"t":"table","title":"국가별 공지예외","head":["국가","내용"],"rows":[["공지예외","출원 전에 공지된 발명도 공지예외 적용을 주장하면 그 공지가 없었던 것으로 보아 특허를 받을 수 있다"],["한국과 일본","최선의 공지일로부터 12개월 이내에 출원해야 공지예외 적용을 주장할 수 있다"],["유럽특허청(EPO)과 중국","공지예외 적용을 주장할 수 있는 기간이 공지일로부터 6개월이다 · EPO는 의사에 반한 공지에 대해서만 공지예외를 인정하되 그 요건을 엄격하게 본다"],["남아프리카공화국","공지예외 적용을 주장할 수 있는 기간에 제한이 없는 나라로 분류된다"],["미국","공지예외가 인정되는 사유를 열거하지 않고 넓게 허용하며 공지일로부터 1년 이내에 출원하면 된다"],["논문 발표","출원 전에 논문을 발표한 경우 한국·일본·미국에서는 공지예외를 주장할 수 있지만 중국과 EPO에서는 주장할 수 없다"]]}],"33":[{"t":"table","title":"병합출원","head":["구분","내용"],"rows":[["병합출원","여러 국내출원을 기초로 우선권을 주장하면서 해외출원을 할 때 하나로 병합해 출원할 수 있다"],["요건","여러 국내출원을 병합해 해외출원하려면 기술적 특징이 공유되어 발명의 단일성을 만족해야 한다"],["가산료","병합출원에서 청구항 수가 미국은 20개, 유럽은 15개를 초과하면 가산료가 붙으므로 이를 고려해야 한다"]]},{"t":"table","title":"특허심사 하이웨이","head":["구분","내용"],"rows":[["의미","상대국 특허청이 이미 심사한 결과를 참고해 심사부담을 줄이고 신속한 권리 취득을 돕는 제도이다"],["제1청·제2청","먼저 심사해 특허 가능 판단을 내린 쪽을 제1청, 그 결과를 참고해 조기심사하는 쪽을 제2청이라 한다"],["장단점","외국 심사기간을 줄일 수 있지만 번역료 등 비용은 늘어날 수 있다"],["신청 서류","제1청 심사 관련 서류와 등록 가능한 청구항의 대응 관계를 제출해야 한다"],["대응출원 관계","제2청 출원이 제1청 출원을 기초로 우선권을 주장한 대응출원 관계에 있어야 한다"]]}],"34":[{"t":"table","title":"실용신안 보호대상","head":["구분","내용"],"rows":[["실용신안제도","고도의 발명에 가려 사장되기 쉬운 실용적 기술사상인 고안을 보호하기 위해 마련된 제도이다"],["보호대상","물품의 형상·구조·조합에 관한 고안으로 물품성이 있어야 한다 · 특허는 물건발명과 방법발명이 모두 가능하지만 실용신안은 물품성 있는 물건에 관한 고안에 한정된다"],["등록받을 수 없는 것","제조방법이나 조성물, 합금, 화합물 같은 물질에 관한 고안은 일정한 형상·구조가 없어 실용신안등록을 받을 수 없다 · 토양, 점토, 모래, 액체, 분체 등은 일정한 형상이나 구조를 갖는 것으로 인정되지 않아 실용신안등록을 받을 수 없다"],["게임·기능","게임이나 기능 자체는 보호대상이 아니며 '게임기'처럼 고안의 대상이 물품임을 분명히 해야 등록을 받을 수 있다"],["도면","실용신안등록출원에서는 도면 제출이 필수이며 도면을 첨부하지 않으면 출원이 수리되지 않는다"]]}],"35":[{"t":"vs","title":"특허와 실용신안","cols":[{"name":"특허","items":["허가 등에 따른 존속기간 연장이 가능하다","국기 또는 훈장과 동일하거나 유사한 고안은 특허의 부등록사유에는 해당하지 않는다","간접침해 규정은 특허에서는 물건발명과 방법발명 모두에 적용된다","특허권의 효력범위 제한 규정은 의약과 의약제법 발명에 적용될 수 있다"]},{"name":"실용신안","items":["진보성은 그 기술분야의 통상의 지식을 가진 사람이 선행기술로부터 극히 쉽게 고안할 수 없을 것을 기준으로 판단한다","실용신안권의 존속기간은 설정등록한 날부터 실용신안등록출원일 후 10년이 되는 날까지이다","실용신안권은 연장이 불가능하다","심사청구기간은 특허출원과 같이 출원일로부터 3년이다","국기 또는 훈장과 동일하거나 유사한 고안은 실용신안의 부등록사유이다","간접침해 규정은 방법발명이나 물질발명에는 적용되지 않는다","특허권의 효력범위 제한 규정은 적용되지 않는다"]}]}],"36":[{"t":"table","title":"R&D 단계 특허정보 활용","head":["구분","내용"],"rows":[["기획 단계","연구개발 기획 단계에서는 특허분석으로 기술의 발전방향을 예측하며 연구개발 방향을 정할 수 있도록 지식재산 창출 계획을 세운다"],["특허정보 분석","미래 유망 기술을 발굴하고 중복 투자를 막는 데 효과적인 도구가 된다"],["선행기술 조사","출원하려는 발명과 동일·유사한 종래 기술이 있는지 조사·분석해 특허성 여부를 판단하는 것이다"],["특허맵","특허정보를 이용목적에 맞게 수집·분석해 그림, 그래프, 표 등으로 시각화한 것으로 공백기술 영역을 찾는 데 쓸 수 있다 · 연구기관의 출원율·등록율·기술이전 현황 등을 분석하면 우수 및 취약 연구분야를 파악해 창출 전략을 세울 수 있다"],["특허문헌","특정 기술을 상세히 설명한 기술문헌인 동시에 특허권자의 준물권적 권리 범위를 정한 권리서로서 기능한다 · 연구개발 시작 단계에서 특허문헌을 참고하면 과제 내용을 구체화하고 연구 전략을 세우며 기술적 과제의 해결방안을 찾는 데 도움이 된다"],["특허 마이크로맵","연구개발 과제의 계획과 특허 획득 전략, 원천특허 대응 방안을 세우는 기초 자료로 활용된다"],["진행 단계","연구개발 진행 단계에서는 연구실 단위의 특허관리 매뉴얼을 만들고 특허담당자를 지정해 연구원에게 주기적으로 교육해야 한다"]]}],"37":[{"t":"cause","title":"연구 성과의 비밀유지","causes":["연구 성과를 특허출원 전에 공개한다"],"result":"신규성을 잃어 특허를 받지 못하고, 영업비밀로도 보호받지 못해 경제적 가치를 잃을 수 있다","effects":["비밀유지계약을 체결하면 상대방의 기밀 누설에 대해 법원에 금지명령을 구하고 계약 위반에 따른 손해배상을 청구할 수 있다","비밀유지계약에는 기밀정보가 무엇인지 명확히 규정되어야 하며, 계약을 체결했더라도 연구자 스스로 기밀 유지를 위한 합리적 노력을 해야 한다"]},{"t":"table","title":"연구노트","head":["구분","내용"],"rows":[["연구노트의 역할","진정한 발명자를 증명하고 영업비밀을 보호하며 선사용권 주장을 뒷받침하는 도구로 쓰이므로 충실히 작성·관리해야 한다"],["전자파일 등록","문서의 비밀을 계속 유지하려는 경우 연구노트를 전자파일 형태로 특허청에 등록해 두면 분쟁이나 라이선스 계약 때 활용할 수 있다"],["연구개발 과정의 지식","연구개발이 완료되지 않아도 과정에서 얻은 각 단계의 지식은 연구개발 결과와 별개로 특허 보호를 받을 수 있다"]]}],"38":[{"t":"vs","title":"특허와 영업비밀","cols":[{"name":"특허","items":["출원일로부터 1년 1개월 후에 공개된다","출원일 후 20년이 되는 날까지만 존속한다","보호범위는 청구범위에 기재된 발명이다","원칙적으로 모든 내용이 공개되어 제3자의 모방이나 개량발명이 가능하고, 존속기간이 끝나면 누구나 쓰는 자유 기술이 된다","침해는 특허법상 민형사 조치로 구제한다"]},{"name":"영업비밀","items":["공개하지 않는다","비밀로 관리되는 한 보호기간에 제한이 없다","보호범위는 영업비밀로 관리되는 범위이다","성립하려면 비공지성, 경제적 유용성, 비밀관리성을 갖춰야 한다","공정이나 소프트웨어처럼 공개되면 모방이 쉽고 침해 사실의 입증이 어려운 기술은 특허보다 영업비밀로 보호하는 것이 유리하다","침해는 부정경쟁방지 및 영업비밀보호에 관한 법률상 민형사 조치로 구제한다"]}]},{"t":"table","title":"출원 여부 결정","head":["구분","내용"],"rows":[["종합 고려","특허출원 여부를 정할 때에는 발명의 기술적 평가와 사업적 평가, 타인의 실시 가능성과 라이선싱 가능성을 종합적으로 고려한다"],["학술논문","학술논문의 발간일이 특허출원 시점보다 앞서지 않도록 해야 하며 인터넷판 논문이나 학위논문 등재도 신규성 상실로 볼 수 있다"],["먼저 검토","특허는 출원 후 명세서가 공개되므로 보호대상의 특성에 따라 영업비밀로 유지할지 특허로 독점권을 확보할지 먼저 검토한다"]]}],"39":[{"t":"table","title":"출원 시기 전략","head":["제도","내용"],"rows":[["빠른 출원","동일한 발명에 대해 둘 이상의 특허출원이 있으면 가장 먼저 출원한 자에게 특허를 주므로 발명이 완성되면 되도록 빨리 출원한다"],["청구범위 유예제도","출원 시 명세서에 청구범위를 적지 않아도 되고 출원일 후 1년 6개월 안에 보완해 제출하면 된다 · 명세서를 영어로 적어 출원할 수 있고, 최우선일로부터 1년 2개월 안에 명세서와 도면의 국문번역문을 내야 한다"],["국내우선권주장","먼저 출원일을 확보한 뒤 1년 안에 개량·구체화한 내용을 보완해 완전한 권리를 취득할 수 있다"],["출원 후 개량발명","출원 후 완성한 개량발명을 보정으로 추가하면 최초 명세서의 범위를 넘는 부적법한 보정이 되고, 별개 출원을 하면 선출원주의에 따라 중복 출원으로 거절될 수 있다"]]}],"40":[{"t":"table","title":"심사청구와 일괄심사","head":["구분","내용"],"rows":[["심사청구","특허출원일로부터 3년 이내에 할 수 있어 필요한 출원만 적절한 시기에 심사청구하면 권리 취득·유지 비용을 줄일 수 있다"],["우선심사","사업화나 분쟁 방지 등으로 특허권을 일찍 얻어야 할 때에는 우선심사제도를 활용해 발명의 조기 권리화를 꾀할 수 있다"],["일괄심사제도","하나의 제품군 또는 동일한 사업에 관련된 둘 이상의 특허·실용신안·상표·디자인 출원을 출원인이 원하는 시기에 맞춰 일괄 심사한다"],["일괄심사 요건","심사착수 전인 출원이어야 하며, 요건에 맞으면 복수 출원의 출원인이 각각 다르더라도 신청할 수 있다 · 창업 후 3년 이내인 중소기업의 출원이나 규제 샌드박스 신청을 한 출원도 일괄심사 대상이 될 수 있다"],["일괄심사 효과","제품 출시 시기에 맞춰 지식재산권을 한꺼번에 빠르게 확보해 등록 지연에 따른 손실을 줄일 수 있다"]]},{"t":"def","term":"특허 포트폴리오","text":"핵심특허를 중심으로 제품 생산과 사업에 필요한 특허를 다양하게 확보해 제3자의 회피 기술 개발을 막고 침해를 예방하는 것이다","ex":["특허 포트폴리오를 확보한다는 것은 개발된 기술에 다양한 특허를 분산시켜 장벽을 구축하는 것으로, 어떤 요소를 언제 어느 나라에 출원할지 정하는 일이다"]}],"41":[{"t":"table","title":"디자인의 정의와 목적","head":["구분","내용"],"rows":[["보호 범위","디자인보호법은 일상에서 쓰이는 넓은 의미의 디자인 전체를 보호하지 않고 · 물품의 미적 외관만을 보호한다"],["디자인","디자인보호법상 디자인은 물품의 형상·모양·색채 또는 이들을 결합한 것으로서 · 시각을 통해 미감을 일으키게 하는 것이다"],["물품","디자인보호법상 물품에는 물품의 부분, 글자체, 화상도 포함된다"],["미적 외관의 요건","독립적으로 거래대상이 될 수 있는 유체동산인 물품에 구현된 미적 외관이어야 한다"],["목적","디자인의 보호와 이용을 도모해 디자인의 창작을 장려함으로써 · 산업발전에 이바지하는 것을 목적으로 한다"],["독점과 이용의 조화","창작자에게 디자인권이라는 독점배타권을 주면서 · 제3자에게도 그 디자인을 적절한 범위에서 실시할 수 있게 하여 둘의 조화를 꾀한다"]]}],"42":[{"t":"table","title":"디자인 특유 제도","head":["제도","내용"],"rows":[["비밀디자인제도","등록된 디자인을 등록 후 3년 이내의 기간 동안 비밀로 유지할 수 있게 하여 모방을 막는 제도이다"],["관련디자인제도","기본디자인과 유사한 디자인을 미리 등록받을 수 있게 하는 제도이다 · 기본디자인과만 유사한 디자인도 따로 등록받을 수 있어 기본디자인 중심으로 권리범위를 넓힐 수 있다"],["출원공개의 신청제도","제3자에게 잠재적 침해 경고를 해 사전에 모방 의지를 꺾기 위한 제도이다"],["일부심사등록제도","등록요건의 일부만 신속히 심사하는 제도로 의류나 식품처럼 유행성이 강하고 수명이 짧은 물품에 쓸모가 있다 · 로카르노 협정상 식품류, 의류 및 패션잡화용품류, 포장용기류, 문방구류 등에 속하는 물품은 일부심사등록출원으로 신속히 등록될 수 있다"],["우선심사","디자인은 우선심사를 신청하면 출원일부터 대략 2개월 이내에 등록 여부를 확인할 수 있다"]]},{"t":"def","term":"유사범위","text":"디자인보호법은 등록디자인의 보호범위가 유사한 영역까지 미칠 수 있게 하여, 사소한 외관 변형만으로 회피설계하는 것을 막는다","ex":["등록디자인의 유사 영역이란 전체적 외관이 동일하지 않아도 일반 수요자가 동일한 심미감을 느낄 정도의 디자인 영역을 뜻한다"]}],"43":[{"t":"table","title":"창작자와 등록받을 권리","head":["구분","내용"],"rows":[["등록받을 수 있는 권리","디자인을 창작한 사람 또는 그 승계인은 디자인보호법에 따라 디자인등록을 받을 수 있는 권리를 가진다"],["창작자","디자인 창작행위는 사실행위이므로 법률행위 능력이 필요 없어 미성년자도 창작자가 될 수 있다 · 단순히 기본 과제나 아이디어만 제공하거나 자금·설비를 대 준 사람은 실질적으로 창작에 기여한 창작자가 아니다"],["이전","디자인등록을 받을 수 있는 권리는 재산권이므로 자유롭게 이전할 수 있고, 권리능력이 있는 사람은 누구나 승계인이 될 수 있다 · 디자인등록출원 후에는 상속이나 일반승계의 경우를 빼고는 출원인 변경신고를 하지 않으면 등록받을 권리의 승계는 효력이 생기지 않는다"],["공동 창작","둘 이상이 공동으로 디자인을 창작한 때에는 등록받을 권리를 공유하며 공유자 전원이 공동으로 디자인등록출원을 해야 한다"],["무권리자의 출원","선출원의 지위를 갖지 못하며, 등록 전에는 거절이유가 되고 등록 후에는 무효사유가 된다 · 거절결정이 확정된 날부터 30일이 지나기 전에 정당권리자가 출원하면 무권리자가 출원한 때에 출원한 것으로 본다"]]}],"44":[{"t":"tree","title":"디자인의 성립요건","root":"디자인보호법은 이미지 자체가 아니라 그 형태가 물품에 구현된 상태를 보호하므로, 디자인이 성립하려면 물품성·형태성·시각성·심미성을 모두 갖춰야 한다","branches":[["물품성","디자인 실무는 물품을 독립성이 있는 구체적인 유체동산으로 해석하므로 현장 시공으로 건축되는 부동산은 물품이 아니다 · 기체·액체·전기·빛·열처럼 일정한 형체가 없는 것과 독립성이 없는 물품의 부분은 물품이 아니어서 디자인으로 보호되지 않는다"],["형태성","물품에 표현된 형상·모양·색채 또는 이들의 결합으로서 공간을 차지하는 윤곽을 말한다"],["시각성","촉각이나 청각 등 시각 이외의 감각으로 파악되는 것이나 확대경으로 키워야 형상이 파악되는 것은 시각성이 없어 디자인이 아니다"],["심미성","기능·작용·효과를 주로 하고 조잡감만 주어 미감을 거의 일으키지 않는 것은 심미성이 없다고 본다 · 정적인 디자인뿐 아니라 형태가 변하는 동적디자인과 디스플레이에 표시되는 화면디자인도 보호된다"]]},{"t":"table","title":"공업상 이용가능성","head":["구분","내용"],"rows":[["양산","디자인보호법은 공업적 생산방법으로 동일한 물품을 양산할 수 있는 디자인에 한해 등록을 허여한다"],["공업적 생산방법","공업적 생산방법에는 수공업적 생산도 포함되지만 상업적·농업적 생산방법에 의한 것은 제외된다"],["이용가능성이 없는 경우","동물박제나 수석 장식품처럼 자연물을 구성 주체로 쓰며 다량 생산할 수 없는 것은 공업상 이용가능성이 없는 것으로 취급된다 · 도면에 등록받으려는 디자인을 전체적으로 명확히 나타내지 않아 일부가 추측 상태로 남으면 공업상 이용가능성이 없는 것으로 본다"]]}],"45":[{"t":"table","title":"디자인의 신규성","head":["구분","내용"],"rows":[["신규성","출원 전에 이미 공개되어 공중이 자유롭게 이용할 수 있는 디자인에 독점권을 주면 제도의 취지에 어긋나므로 신규성이 있는 디자인에만 디자인권을 허여한다"],["신규성이 없는 디자인","출원 전에 국내외에서 공지되었거나 공연히 실시된 디자인, 반포된 간행물이나 전기통신회선으로 공개된 디자인, 이들과 유사한 디자인은 신규성이 없다"],["공지디자인","비밀유지 의무가 없는 일반 공중에 공개되어 온라인 또는 오프라인으로 열람할 수 있는 상태에 놓인 디자인을 말한다 · 국내에서 공지된 디자인은 반드시 불특정 다수인에게 실제로 인식되었어야 하는 것은 아니고 인식할 수 있는 상태에 놓여 있으면 된다"]]},{"t":"flow","title":"신규성 상실의 예외","steps":["개발 후 사업준비 등으로 미처 출원하지 못한 창작자를 구제하기 위해 제3자의 권익을 해치지 않는 범위에서 두는 제도이다","디자인이 최초로 공지된 날부터 12개월 이내에 등록받을 수 있는 자가 출원하면 그 공지디자인을 공지되지 않은 것으로 본다","그 공지디자인은 자기가 출원한 디자인의 신규성과 창작 비용이성을 심사할 때 공지디자인으로 보지 않는다","공개 후 12개월 안에 출원하더라도 그 사이 제3자가 스스로 창작한 디자인이 공지되면 등록이 불가능할 수 있어 공개 전에 먼저 출원하는 것이 바람직하다"]},{"t":"table","title":"용이창작","head":["구분","내용"],"rows":[["용이창작","신규성이 인정되더라도 통상의 지식을 가진 사람이 공지·공용 디자인을 기초로 쉽게 창작할 수 있는 디자인은 등록받을 수 없다"],["판단 기준","용이창작 여부는 일반 수요자가 아니라 해당 분야의 평균적 지식을 가진 당업자를 기준으로 판단한다"],["쉽게 창작할 수 있는 디자인","공지디자인을 거의 그대로 모방하거나 단순한 상업적·기능적 변경에 불과하거나 흔한 창작수법으로 변형한 디자인은 쉽게 창작할 수 있는 디자인이다"]]}],"46":[{"t":"table","title":"선출원과 확대된 선출원","head":["구분","내용"],"rows":[["선출원주의 위반","출원디자인이 이미 출원된 타인 디자인의 전부와 동일·유사하면 선출원주의 위반으로 등록받을 수 없다 · 동일·유사한 디자인에 대해서는 먼저 출원한 자에게 디자인권을 부여하며 먼저 창작한 자에게 부여하는 것이 아니다"],["확대된 선출원주의 위반","출원디자인이 이미 출원된 타인 디자인의 일부와 동일·유사하면 확대된 선출원주의 위반으로 등록받을 수 없다 · 후출원디자인이 선출원디자인의 일부와 같거나 유사해도, 선출원디자인이 후출원 이후 디자인공보에 게재되어 발행되어야 위반이 된다"],["적용 제외","확대된 선출원주의는 선출원과 후출원의 출원인이 동일한 경우에는 적용되지 않는다"]]},{"t":"table","title":"1디자인 1출원","head":["구분","내용"],"rows":[["1디자인 1출원주의","심사의 간편성, 권리 파악과 이전의 명확화, 분류의 용이성 등을 위해 1디자인마다 1디자인등록출원으로 하는 원칙이다"],["1디자인","1물품에 대한 1형태를 말하며, 1물품은 거래 관행상 독립하여 하나로 거래될 수 있는 물품을 뜻한다"],["위반","물품란에 '시계 및 라디오'처럼 둘 이상의 물품명을 병렬로 적으면 1디자인 1디자인등록출원에 위반된다"],["1디자인으로 인정","신사복 상·하나 찻잔과 받침 접시처럼 물리적으로 분리되어 있어도 하나의 물품으로 거래되는 것이 당연하면 1디자인으로 인정된다"],["예외","1디자인 1디자인등록출원의 예외로 출원인의 편의를 위해 복수디자인 등록출원과 한 벌 물품 디자인출원제도를 두고 있다"]]}],"47":[{"t":"table","title":"등록 불가 디자인","head":["유형","내용"],"rows":[["법의 목적에 반하는 디자인","디자인보호법은 등록요건을 갖췄더라도 공공의 이익에 반하거나 경업질서를 해치는 등 법의 목적에 반하는 디자인은 등록받을 수 없도록 규정한다"],["국기·훈장 등","국기, 군기, 훈장 등 공공기관의 표장이나 외국의 국기와 동일·유사한 디자인은 등록받을 수 없으나 존엄을 해할 정도가 아닌 변형은 등록받을 수 있다"],["인륜·사회정의 등","인륜·사회정의·국민감정에 반하는 것, 특정국가나 국민을 모욕하는 것, 저속·혐오·외설스러운 것은 등록받을 수 없는 디자인이다"],["초상","저명한 타인의 초상을 담은 디자인은 등록받을 수 없으나 그 타인의 승낙을 얻은 경우에는 이 규정을 적용하지 않는다"],["혼동 우려","타인의 업무와 관계되는 물품과 혼동을 일으킬 염려가 있는 디자인은 부정경쟁행위를 막고 유통 질서를 확립하려는 취지에서 등록받을 수 없다 · 타인의 주지·저명한 상표나 단체표장을 디자인으로 표현하거나 비영리법인의 표장을 디자인으로 표현한 경우는 혼동 우려로 등록받을 수 없다 · 물품의 규격이나 품질 등에 대한 인증을 나타내는 표지를 디자인의 일부로 포함한 경우에는 출처 표시가 아니라 인증 정보 전달용으로 보아 혼동 규정을 적용하지 않는다"],["기능성 디자인","물품의 기능을 확보하는 데 불가결한 형상만으로 된 디자인은 미적 창작만을 보호하는 법의 목적과 상반되어 등록받을 수 없고 특허법이나 실용신안법으로 보호받는 것이 타당하다 · 기능성 디자인 여부는 기능을 확보할 수 있는 대체적 형상이 존재하는지 등을 고려하여 판단하며, 대체할 수 있는 형상이 다수 있으면 기능성이 없는 것으로 볼 수 있다"],["표준 규격","규격봉투나 USB 규격포트처럼 표준화된 규격으로 정해진 형상만으로 된 디자인은 등록받을 수 없으며 한국산업표준(KS)이나 ISO 규격도 이에 해당한다 · 표준화된 규격에는 공적 표준화 기관이 확정한 규격뿐 아니라 업계 표준으로 인지되어 시장을 사실상 지배하는 '사실상의 표준 규격'도 포함된다"]]}],"48":[{"t":"table","title":"디자인 유사 판단","head":["구분","내용"],"rows":[["물품","디자인의 유사 여부는 동일하거나 유사한 물품 사이에서만 판단하므로 물품이 서로 전혀 다르면 형태가 같아도 비유사 디자인으로 본다 · 동일물품은 용도와 기능이 같은 물품이고, 유사물품은 용도는 같으나 기능이 다른 물품이다 · 비유사물품이라도 핸드폰 케이스와 지갑처럼 용도상 혼용될 수 있는 것은 유사한 물품으로 볼 수 있다"],["판단 주체","일반수요자를 기준으로 물품이 유통과정에서 다른 물품과 혼동될 우려가 있는지를 보고 판단한다"],["전체적 대비","구성 요소를 분리해 개별 대비하지 않고 외관을 전체적으로 대비하여 지배적 특징이 유사하면 세부 차이가 있어도 유사하다고 본다"],["고려하지 않는 요소","물품의 대소 차이는 유사 판단의 요소로 고려하지 않고, 기능·구조·정밀도 등은 외관으로 표현되지 않는 한 요소가 될 수 없다 · 색채는 그 자체가 모양을 구성하지 않는 한 디자인 유사 여부 판단의 요소로 고려하지 않는다"],["유사의 폭","참신한 디자인일수록 유사의 폭을 넓게 보고 같은 종류의 디자인이 많이 나올수록 유사의 폭을 좁게 본다"],["공통 부분","양 디자인의 공통 부분이 그 물품으로서 당연히 있어야 할 부분이거나 기본적 형태이면 중요도를 낮게 평가하므로 그 부분이 유사하다는 사정만으로 디자인이 유사하다고 할 수 없다"]]}],"49":[{"t":"table","title":"출원서","head":["구분","내용"],"rows":[["출원서 제출","디자인등록을 받으려는 자는 일정 사항을 적은 심사등록출원서 또는 일부심사등록출원서를 특허청장에게 제출해야 한다"],["보완·반려","출원서류가 불명확하거나 국어로 적지 않았거나 디자인의 대상 물품이 적혀 있지 않으면 보완을 명하고, 기간 내에 보완하지 않으면 부적법한 출원으로 보아 반려할 수 있다"],["기재 사항","출원인과 창작자의 성명·주소, 디자인의 대상 물품 및 물품류, 단독 또는 관련디자인 여부, 복수디자인 여부 등을 적는다 · 기본디자인의 등록번호나 출원번호는 관련디자인으로 등록받으려는 경우에만, 디자인의 수와 일련번호는 복수디자인등록출원을 하는 경우에만 적는다"]]},{"t":"table","title":"물품류와 물품 명칭","head":["구분","내용"],"rows":[["물품류","우리나라는 2014년 7월 1일부터 국제 디자인등록출원제도가 시행되어 산업디자인 국제분류인 로카르노 분류를 사용하며 출원서에 물품류를 적는다 · 현행 물품류는 출원서 작성의 일관성과 물품 명칭 사용의 통일을 위한 것이며 디자인 물품 상호 간의 유사 범위를 정하는 것은 아니다"],["부적절한 명칭","디자인의 대상 물품을 영어로만 적거나 독립 거래의 대상이 될 수 없는 물품의 부분 명칭을 적으면 물품 명칭이 적절하지 않아 등록되지 않는다"],["고시되지 않은 물품","특허청장이 고시한 물품 명칭에 없는 물품은 용도가 명확히 이해되고 보통 사용되는 명칭으로 적되 일반화된 명칭이 없으면 'OOO용 부재' 같은 명칭도 쓸 수 있다"]]}],"50":[{"t":"table","title":"도면","head":["구분","내용"],"rows":[["도면의 기재","디자인 도면에는 디자인을 명확히 파악할 수 있는 도면이나 사진 이미지를 넣고 물품류, 디자인의 대상이 되는 물품, 디자인의 설명, 창작 내용의 요점을 기재해야 한다"],["도면의 역할","디자인권은 도면이나 사진 이미지에 의해 권리가 특정되므로 도면은 출원 시 필수적으로 제출해야 하고 등록디자인의 보호범위를 판단하는 기준이 된다"],["설명과 요점","디자인의 설명에 의해 표현된 사항은 권리범위를 정하는 중요한 판단요소가 되지만 창작 내용의 요점에 기재된 사항은 원칙적으로 권리범위에 포함되지 않는다 · 디자인의 창작 내용의 요점은 쉽고 간결하게 명확히 적되 공지된 디자인과 비교해 독창적으로 창작한 내용을 중심으로 300자 이내로 작성한다"],["기본 도면·참고 도면","디자인 도면은 권리범위에 포함되는 기본 도면과 권리범위에는 포함되지 않지만 디자인의 이해를 돕는 참고 도면으로 구분된다"]]},{"t":"table","title":"도면 설명이 필요한 경우","head":["경우","내용"],"rows":[["도면별 설명","도면에 대한 설명이 필요한 경우에는 도면별로 설명을 적고, 길이 표시를 생략한 경우에는 생략된 길이를 표시한다"],["색채","도면이나 사진에 색채를 입히면서 흰색·회색·검은색 중 하나를 생략한 경우에는 그에 관한 설명을 적어야 한다"],["형태가 변화","열리고 닫히는 디자인처럼 형태가 변화하는 디자인은 변화 전후의 상태에 대한 설명이 필요하다고 인정되면 그에 관한 설명을 적는다"],["한 쌍의 물품","한 쌍으로 이루어진 물품에서 한 짝의 형태만 도면으로 내고 나머지 한 짝을 생략하는 경우에는 그에 관한 설명이 필요하다"],["보조 물품","의류나 패션잡화용품에서 형태를 완전하게 보여주려고 마네킹 같은 보조 물품을 쓴 경우에는 그 마네킹이 디자인을 구성하지 않는다는 설명을 적는다"]]},{"t":"vs","title":"도면과 사진·견본","cols":[{"name":"사진 또는 견본","items":["디자인출원 시 도면 대신 제출할 수 있으며 이를 이용하면 도면 작성 시간을 줄여 신속한 출원에 도움이 된다","디자인을 명확히 표현할 수 있다"]},{"name":"도면보다 불리한 점","items":["도면보다 권리범위가 협소해지고 실물이 만들어지기 전 아이디어 단계에서는 출원할 수 없다"]}]}],"51":[{"t":"table","title":"출원 후 절차","head":["구분","내용"],"rows":[["출원 방법","디자인등록출원은 서면으로도 가능하고 특허로에서 온라인으로 작성할 수도 있으며 온라인 출원을 하려면 먼저 특허고객번호를 부여받아야 한다"],["심사 순서","디자인출원에는 특허출원과 달리 심사청구제도가 없고 모든 출원이 출원 순서에 따라 심사된다 · 우선심사 대상이면 우선심사를 신청할 수 있고, 일부심사 대상 디자인은 일부 요건만 심사해 1~3개월 정도면 등록될 수 있다"],["방식심사","디자인출원 후 방식심사에서 출원서류의 방식에 하자가 있으면 출원절차가 무효로 될 수 있으나 방식 위반의 하자를 보정으로 치유하면 그러하지 아니하다"],["이의신청","일부심사등록디자인에 대해서는 설정등록된 날부터 공고일 후 3개월 이내에 이의신청을 할 수 있다"],["출원공개","디자인은 원칙적으로 등록 전까지 출원디자인을 공개하지 않지만 출원인이 신청하면 등록 전이라도 출원디자인을 공개한다 · 출원공개된 디자인을 등록 전에 제3자가 무단으로 실시하는 경우 서면 경고 후 등록 뒤에 보상금을 청구할 수 있으며 서면 경고 시 출원공개가 전제되어야 한다"]]},{"t":"table","title":"비밀디자인","head":["구분","내용"],"rows":[["신청 시기","출원 이후부터 최초의 디자인등록료 납부 전까지 신청할 수 있다"],["비밀 기간","설정등록 후 최장 3년 동안 등록디자인의 공개가 유보되며 비밀기간은 나중에 연장하거나 단축할 수도 있다"],["제한","분쟁 시 침해자에 대한 과실 추정이 배제되고 침해금지·예방청구권 행사 시 사전 경고를 반드시 해야 하는 제한이 있다"]]}],"52":[{"t":"table","title":"화상디자인","head":["구분","내용"],"rows":[["화상","디지털 기술 또는 전자적 방식으로 표현되는 도형·기호로서 기기의 조작에 이용되거나 기능이 발휘되는 것에 한정된다"],["물품 의제","화상은 본래 물품성을 갖추지 못했지만 물품으로 의제되어 디스플레이 패널처럼 물품의 부분으로 표현될 필요 없이 독립적으로 물품성을 갖춘 것으로 본다"],["기기의 조작에 이용되는 화상","기기를 제어하기 위해 지시·명령 등을 입력하는 도형·기호이며 조작 대상 기기가 반드시 물품일 필요는 없다"],["기기의 기능이 발휘되는 화상","기기가 발휘하는 기능을 표현하는 도형·기호로 각종 그래프, 상태표시등, 경고등, 인디케이터 등이 대표적이다"]]},{"t":"table","title":"한 벌 물품 디자인","head":["구분","내용"],"rows":[["한 벌 물품 디자인제도","한 벌의 사무용 가구 세트처럼 2개 이상의 물품이 상관습상 한 벌로 판매·사용되고 전체적으로 통일성이 있으면 하나의 출원으로 심사·등록하게 한다"],["한 벌의 물품","2개 이상의 물품이 한 벌로 동시에 사용되어야 하며, 실제 동시 사용뿐 아니라 관념적으로 동시에 사용되는 것도 포함한다"],["통일성","각 구성 물품이 같은 표현 방법으로 표현되거나 서로 집합해 통일된 디자인을 이루거나 관념적으로 관련 있는 인상을 주어 한 벌 전체로서 통일성이 있어야 한다"],["구분","한 벌의 물품의 구분은 디자인보호법 시행규칙 별표에 규정되어 있는 물품이어야 한다"],["디자인권","한 벌 물품 디자인으로 등록받으면 구성 물품마다 디자인권이 생기는 것이 아니라 한 벌 물품 전체에 하나의 디자인권이 발생한다 · 구성 물품의 디자인을 각각 보호받으려면 각각의 물품에 대해 디자인등록출원을 해야 한다"]]}],"53":[{"t":"table","title":"부분디자인","head":["구분","내용"],"rows":[["부분디자인","물품의 일부에 창작적 가치가 있는 디자인으로, 부분은 독립 거래 대상이 아니지만 제3자의 모방을 막기 위해 물품으로 간주하여 보호한다"],["물품의 부분","물품 전체 중 일정한 범위를 차지하는 부분으로서 다른 디자인과 대비 대상이 될 수 있는 부분을 말한다"],["출원서","부분디자인으로 출원할 때에는 출원서의 부분디자인 여부란에 그 취지를 적어야 한다 · 물품란에는 물품 일부의 명칭이 아니라 그 부분이 속한 해당 물품 자체의 명칭을 적어야 한다"],["표현 방법","등록받으려는 부분을 실선으로, 그 외의 부분을 파선(점선)으로 표현하여 권리범위를 특정한다 · 색상으로 부분디자인을 구분할 때에는 등록받으려는 부분 외의 부분을 무채색으로 표현하는 것이 원칙이다"],["디자인의 설명","부분디자인으로 등록받으려는 부분의 위치·크기·범위가 구체적으로 드러나도록 디자인의 설명란에 그 표현 방법을 적는다"]]}],"54":[{"t":"table","title":"관련디자인","head":["구분","내용"],"rows":[["관련디자인","자기의 등록디자인이나 출원디자인(기본디자인)에만 유사한 디자인을 말한다"],["제도의 취지","유사한 디자인을 별도 권리로 등록받게 하여 모방과 침해를 미리 막고 침해에 신속히 대응하게 하려는 제도이다"],["출원 기간","관련디자인은 기본디자인의 출원일로부터 3년 이내에 출원해야 한다"],["요건","관련디자인으로 등록받으려는 디자인은 자기의 기본디자인에만 유사한 디자인이어야 하고, 자기의 관련디자인에만 유사한 디자인은 등록받을 수 없다"],["등록받을 수 없는 경우","기본디자인의 디자인권에 전용실시권이 설정되어 있으면 관련디자인등록출원은 등록받을 수 없다 · 관련디자인의 디자인권을 설정등록할 때 기본디자인의 권리가 취소·포기·무효심결 등으로 소멸해 있으면 관련디자인등록을 받을 수 없다"],["관련디자인 상호 간","기본디자인에만 유사한 둘 이상의 관련디자인등록출원이 있을 때 이들 상호 간에는 신규성 상실과 선출원주의를 적용하지 않는다"],["권리범위","관련디자인권은 기본디자인의 권리범위와 별도로 자기만의 권리범위를 가지므로 하나의 콘셉트에서 나온 디자인의 보호 범위를 넓게 확보할 수 있다"]]},{"t":"table","title":"복수디자인","head":["구분","내용"],"rows":[["복수디자인등록출원","동일한 물품류에 속하는 물품이라면 100개 이내에서 복수디자인등록출원을 할 수 있다"],["원칙","디자인보호법은 하나의 디자인등록절차에서 하나의 디자인권이 발생하는 것을 원칙으로 한다 · 복수디자인등록은 절차와 관리의 편의를 줄 뿐이며 등록 후 각 디자인권의 효력에는 차이가 없다"],["같은 물품류","복수디자인등록출원은 같은 물품류에 속해야 하므로 직물에 관한 여러 디자인은 제2류로 묶어 한 번에 출원할 수 있다"]]}],"55":[{"t":"table","title":"디자인 심사 순서","head":["구분","내용"],"rows":[["심사 순서","디자인출원은 특허와 달리 심사청구제도가 없어 출원 순서대로 심사가 진행된다"],["일부심사등록출원","일부 요건만 심사하므로 심사 기간이 약 1~3개월 정도 소요된다"],["우선심사신청","심사등록출원에 우선심사신청을 하면 심사 기간이 약 1~2개월 정도로 단축될 수 있다"],["우선심사 신청인","우선심사는 누구든지 신청할 수 있으나, 국가나 지방자치단체의 직무에 관한 출원은 그 국가 또는 해당 지방자치단체만 신청할 수 있다"],["우선심사 사유","출원공개 후 출원인이 아닌 자가 업으로서 출원된 디자인을 실시하고 있다고 인정되는 경우는 우선심사 사유에 해당한다"]]}],"56":[{"t":"table","title":"의견제출과 보정","head":["구분","내용"],"rows":[["의견제출통지","심사관은 거절이유를 발견하면 출원인에게 의견제출통지를 하고 기간을 정해 의견서 또는 보정서 제출 기회를 준다"],["지정 기간","디자인 의견서 제출 지정 기간은 2개월 이내가 원칙이며, 필요하면 매회 1개월씩 4회에 한해 연장할 수 있다"],["요지","디자인등록출원의 요지란 출원서 기재와 도면 등으로부터 직접 도출되는 디자인의 구체적인 내용을 말한다"],["보정의 범위","출원의 보정은 요지를 변경하지 않는 범위 안에서만 할 수 있으며, 이는 선출원주의 취지와 제3자 보호 때문이다"]]},{"t":"table","title":"요지변경","head":["구분","내용"],"rows":[["요지변경 판단","최초 출원 디자인과 보정된 디자인 사이에 동일성이 유지되지 않으면 요지변경으로 판단한다"],["요지변경에 해당","도면에 표현된 형상·모양·색채를 더하거나 빼거나 바꾸어 물품의 외관에 영향을 주는 보정은 요지변경에 해당하나 외관에 거의 영향이 없는 경미한 것은 예외이다 · 복수디자인등록출원에서 출원서에 적은 디자인의 수에 맞추어 도면을 추가로 제출하는 보정은 요지변경에 해당한다 · 와이어 프레임 도면을 렌더링이나 선도로 바꾸어 디자인의 구성요소가 변경됨으로써 동일성이 깨지는 보정은 요지변경이다"],["예외","디자인을 구성하는 문자의 삭제 등이 요지변경이어도, 최초 도면 등을 기준으로 단순한 착오나 오기를 정정하는 것으로 인정되면 예외로 한다"]]},{"t":"flow","title":"보정각하결정","steps":["보정이 요지를 변경하는 것일 때 심사관은 디자인보호법 제49조에 따라 보정각하결정을 한다","보정각하결정 등본을 송달한 날부터 30일이 지나기 전까지는 그 출원에 대하여 등록 여부 결정을 해서는 안 된다","출원인이 보정각하결정에 대해 심판을 청구하면 그 심결이 확정될 때까지 출원 심사를 중지해야 한다"]}],"57":[{"t":"table","title":"재심사청구","head":["구분","내용"],"rows":[["재심사청구","디자인거절결정등본을 송달받은 날부터 3개월 이내에 도면 등을 보정하여 할 수 있다"],["불복수단","출원인은 디자인등록거절결정에 대해 심판을 청구하지 않고도 불복수단으로 재심사청구제도를 이용할 수 있다"],["청구할 수 없는 경우","재심사에 따른 거절결정이 이미 있거나 거절결정불복심판 청구가 있는 경우에는 재심사를 청구할 수 없다"],["직권 심사","재심사가 청구된 출원에 대해 심사관은 당초 거절결정의 이유가 아닌 다른 사유에 대해서도 직권으로 심사할 수 있다"]]}],"58":[{"t":"table","title":"일부심사등록","head":["구분","내용"],"rows":[["일부심사 대상","디자인일부심사등록출원은 물품에 따라 정해지며 출원인의 선택으로 결정되지 않는다"],["일부심사 대상 물품","로카르노 협정 물품류 중 제1류(식품), 제2류(의류·패션잡화용품), 제3류, 제5류, 제9류, 제11류, 제19류에 해당하는 물품이다"],["일부심사 등록의 한계","일부심사로 등록된 디자인권도 형식적으로는 유효하지만 일부 요건을 심사하지 않았으므로 무효가 될 가능성이 상대적으로 높다"],["제외되는 등록요건","선행디자인 조사가 필요해 판단이 오래 걸리는 신규성, 창작비용이성, 선출원주의, 확대된 선출원, 관련디자인 요건이다"],["정보제공","일부심사에서 제외된 등록요건도 제3자의 정보제공이 있으면 등록 전에 심사될 수 있고 등록 후에는 무효사유나 이의신청이유가 된다"]]}],"59":[{"t":"table","title":"디자인권의 발생과 존속","head":["구분","내용"],"rows":[["발생","디자인권은 등록결정 이후 등록료를 납부(또는 면제)하는 것과 동시에 발생한다"],["효력의 범위","디자인권의 효력은 등록디자인뿐 아니라 이와 유사한 디자인에까지 미친다 · 디자인은 기술적 사상과 달리 모방이 쉽고 권리범위가 협소하기 때문에 효력을 유사한 디자인에까지 미치게 한다"],["존속기간","설정등록일부터 발생하여 디자인등록출원 후 20년이 되는 날까지이다 · 특허권의 연장이나 상표권의 갱신과 달리 연장 또는 갱신되지 않는다 · 관련디자인권의 존속기간 만료일은 그 기본디자인권의 존속기간 만료일로 한다"],["속지주의","디자인권은 속지주의 원칙에 따라 우리나라 영토 안에서만 효력이 있으며, 해외에서 보호받으려면 각국에서 별도로 등록절차를 밟아야 한다"],["독점의 제한","디자인권자는 전용실시권을 설정했거나 공유인 경우 지분 양도·실시권 허락에 동의가 필요한 경우처럼 독점적 행사에 제한을 받을 수 있다"],["수익·처분 행위","디자인권자는 등록디자인의 실시 외에 실시권 허여, 질권 설정, 권리 양도, 권리 포기 같은 수익·처분 행위도 독점한다"]]}],"60":[{"t":"table","title":"디자인권 침해의 성립","head":["구분","내용"],"rows":[["직접침해","제3자가 정당한 권원 없이 업으로서 등록디자인 또는 이와 유사한 디자인을 실시하는 경우에 성립한다"],["간접침해","등록디자인 물품의 생산에만 사용하는 물품을 업으로서 생산·양도·대여·수출·수입하거나 양도·대여를 청약하는 행위는 간접침해로 본다"],["침해를 주장할 수 없는 경우","전용 또는 통상실시권이 있는 실시권자에 대해서는 디자인권자가 침해를 주장할 수 없다 · 등록료 추가납부나 재심에 의해 회복된 디자인권의 효력제한기간 내에 제3자가 한 실시에 대해서는 침해를 주장할 수 없다"],["성립 요건","디자인권 침해가 되려면 유효한 디자인권이 있고, 제3자에게 정당한 실시 권원이 없으며, 업으로서 실시했고, 실시디자인이 등록디자인 또는 유사 디자인이어야 한다"],["침해의 특성","디자인권은 점유가 불가능한 무체재산권이어서 동시에 여러 곳에서 실시될 수 있어 침해가 쉬운 반면 침해 발견·입증과 손해액 증명은 어렵다"]]}],"61":[{"t":"table","title":"침해에 대한 민사 구제","head":["구제","내용"],"rows":[["경고장","경고장을 보내면 상대의 실시행위를 고의적 실시로 전환시켜 향후 분쟁에서 유리한 지위를 얻을 수 있어 침해자에 대한 조치 중 가장 먼저 해야 한다"],["권리범위확인심판","디자인권자는 권리범위확인심판으로 제3자의 실시 디자인이 자기 등록디자인의 권리범위에 속하는지를 확인받을 수 있다 · 심결은 민사·형사 소송에서 법적 구속력은 없지만 침해를 입증하는 중요한 증거자료가 된다"],["금지·예방 청구","디자인권자는 침해한 자뿐 아니라 침해할 우려가 있는 자에게도 침해의 금지 또는 예방을 청구할 수 있다 · 비밀디자인 청구를 한 디자인의 디자인권자는 특허청장이 발급한 증명서를 서면으로 제시해 경고한 뒤에야 침해금지 및 예방청구를 할 수 있다"],["손해배상","디자인권자는 고의 또는 과실로 권리를 침해한 자에게 민법 제750조에 따라 손해배상을 청구할 수 있다 · 디자인보호법은 손해액의 추정규정과 침해자의 과실 추정규정을 두어 입증 곤란을 덜어 주나 비밀디자인으로 설정등록된 디자인권의 침해에는 과실 추정이 적용되지 않는다"],["신용회복","고의 또는 과실로 디자인권을 침해해 디자인권자의 업무상 신용을 실추시킨 자에게 법원은 손해배상에 갈음하거나 손해배상과 함께 신용회복에 필요한 조치를 명할 수 있다"],["부당이득 반환","디자인권자는 정당한 권원 없이 권리를 실시하여 이득을 얻고 자기에게 손해를 끼친 자에게 그 손해를 한도로 이득의 반환을 청구할 수 있다"]]}],"62":[{"t":"table","title":"침해죄와 형사 구제","head":["구분","내용"],"rows":[["침해죄","고의로 디자인권을 침해한 자는 7년 이하의 징역 또는 1억 원 이하의 벌금에 처하는 침해죄로 고소할 수 있다"],["반의사불벌죄","디자인 침해죄는 반의사불벌죄여서 권리자의 고소가 없어도 수사할 수 있으나 피해자가 처벌을 원하지 않으면 그 의사를 존중한다"],["양벌규정","법인의 대표자나 종업원이 업무에 관하여 침해죄를 범하면 행위자를 벌하는 외에 그 법인에게도 벌금형을 과한다"],["몰수","침해행위를 조성한 물건은 몰수하거나 피해자의 청구에 의해 피해자에게 교부할 것을 선고해야 하며, 교부받으면 그 가액을 초과하는 손해의 액에 한하여 배상을 청구할 수 있다"]]}],"63":[{"t":"table","title":"파리협약 우선권","head":["구분","내용"],"rows":[["디자인 우선권 출원","대한민국에 먼저 출원을 완료한 뒤 그로부터 생기는 우선권을 근거로 해외 각국에 출원하는 방식이다"],["효과","해외 출원에 우선권주장을 수반하면 그 출원일은 파리협약 제4조에 따라 우리나라 출원일로 간주된다 · 제1국과 제2국 출원일 사이의 다른 출원이나 제3자의 실시로 인해 불리하게 취급되지 않으며 제3자의 권리발생도 저지된다"],["존속기간","우선권주장은 출원일을 소급시키는 것이 아니므로 우선기간을 인정하더라도 존속기간이 단축되지 않는다"],["우선권 주장 기간","파리조약에 의한 디자인 우선권은 제1국 출원일부터 6월 이내에 주장해야 한다 · 제1국에서 발생한 우선권은 제1국을 제외한 둘 이상의 다른 국가에 대하여 모두 주장할 수 있다"],["동일성","우선권이 인정되려면 제1국 출원디자인과 제2국 출원디자인이 실질적으로 동일해야 하고 형식까지 똑같을 필요는 없다 · 두 출원 디자인의 동일성이 인정되지 않으면 우선권의 효력이 생기지 않고 제2국 출원일은 제1국 출원일로 간주되지 않는다"]]},{"t":"table","title":"우선권주장의 절차","head":["구분","내용"],"rows":[["서류 제출","해외 출원을 기초로 국내에서 우선권을 주장하려면 제1국 정부가 인정한 출원연월일이 적힌 서류와 도면의 등본을 디자인등록출원일부터 3월 이내에 특허청장에게 제출해야 한다"],["정당한 사유","정당한 사유로 3월 이내에 우선권 서류를 제출하지 못했다면 그 기간의 만료일부터 2개월 이내에 제출할 수 있다"],["출원서","우선권주장을 하려면 국내 출원서에 그 취지, 최초로 출원한 국가명, 출원의 연월일을 적어야 한다"]]}],"64":[{"t":"table","title":"헤이그 출원","head":["구분","내용"],"rows":[["헤이그 국제출원","하나의 출원서류를 WIPO 국제사무국에 직접 제출하거나 특허청을 통해 제출하여 다수 국가에 출원한 것과 같은 효과를 얻는 제도이다"],["언어와 통화","영어·프랑스어·스페인어 중 하나의 언어로 출원서를 작성하고 스위스 프랑 한 가지 통화로 수수료를 낸다"],["시행","우리나라는 2014년 7월 1일부터 헤이그 국제출원 시스템을 본격적으로 시행했다"],["국가별 차이","국가마다 보호하는 디자인의 정의가 달라서, 예컨대 부동산·인테리어 디자인은 미국·유럽·일본에서만 디자인권으로 보호될 수 있다 · 출원 전에 디자인이 공지된 경우의 법적 취급도 국가마다 상당히 다르므로 해외 출원 전에 조사가 필요하다"]]}],"65":[{"t":"tree","title":"상표의 기능","root":"상표를 상품에 표시하면 자기 상품과 타인의 상품을 구별할 수 있게 된다","branches":[["자타상품 식별 기능","상표를 상품에 표시하면 자기 상품과 타인의 상품을 구별할 수 있게 되는 기능"],["출처표시 기능","같은 상표가 붙은 상품은 동일한 출처에서 나왔음을 수요자에게 알리는 기능"],["품질보증 기능","같은 상표가 붙은 상품은 동일한 품질일 것이라고 수요자가 기대할 수 있게 하는 기능"],["광고선전 기능","상표는 말 없는 판매원이라 불리며, 상품에 대한 심리적 연상 작용을 이용해 판매를 촉진한다"],["재산적 기능","상표를 오래 반복해 사용하여 주지·저명상표가 되면 영업상 고객흡입력이 생겨 상표 자체가 독립적인 재산권으로 인정받는다"]]},{"t":"vs","title":"본원적 기능과 파생적 기능","cols":[{"name":"본원적 기능","items":["식별·출처표시·품질보증 기능"]},{"name":"파생적 기능","items":["광고선전 기능과 재산적 기능"]}]},{"t":"table","title":"상표와 표장","head":["구분","내용"],"rows":[["상표","상표법상 상표는 자기 상품과 타인의 상품을 식별하기 위해 사용하는 표장을 말한다"],["표장","기호·문자·도형·소리·냄새·입체적 형상·홀로그램·동작·색채 등 그 구성이나 표현방식과 상관없이 출처를 나타내는 모든 표시를 포함한다"],["상표의 사용","상품·포장에 표시하는 행위, 표시한 상품을 양도·전시·수출·수입하는 행위, 광고·정가표·거래서류 등에 표시하여 알리는 행위로 나뉜다"],["상표적 사용","상표권 침해의 전제가 되는 상표적 사용이 되려면 출처표시 기능을 하는 사용이어야 하므로 단순한 설명적 문구나 순수한 디자인적 요소로만 쓴 경우는 해당하지 않는다"]]}],"66":[{"t":"table","title":"특수표장","head":["표장","내용"],"rows":[["단체표장","상품을 생산·판매하거나 서비스를 제공하는 자가 공동으로 설립한 법인이 직접 쓰거나 소속 단체원에게 쓰게 하려는 표장이다 · 권리주체가 법인이어야 하므로 자연인은 단체표장권자가 될 수 없다"],["지리적 표시 단체표장","상품의 산지나 현저한 지리적 명칭에 해당하는 표장이라도 특정 상품의 지리적 표시에 해당하면 지리적 표시 단체표장으로 등록하여 독점배타적으로 보호받을 수 있다"],["증명표장","어떤 상품이 정해진 품질·원산지·생산방법 등의 특성을 충족함을 증명하기 위해 쓰는 표장이다 · 권리주체는 법인뿐 아니라 개인도 될 수 있으나, 증명표장권자가 자기 상품에 증명표장을 사용하는 것은 허용되지 않는다"],["업무표장","영리를 목적으로 하지 않는 업무를 하는 자가 그 업무를 나타내기 위해 사용하는 표장이다 · 우리 상표법 특유의 제도로, 국제상표등록출원에는 업무표장 규정이 적용되지 않는다 · 출원인은 업무가 비영리임을 입증하기 위해 출원서에 업무의 경영사실을 입증하는 서면을 첨부해야 한다"]]},{"t":"vs","title":"상표와 지리적 표시","cols":[{"name":"상표","items":["특정 사업주체를 식별시켜 주는 표장이다"]},{"name":"지리적 표시","items":["제품을 생산하는 사업주체들이 위치한 특정 지역을 확인시켜 주는 표장이어서 독점적 소유자가 없다","우리나라는 2004년 개정 상표법에 따라 2005년 7월 1일부터 지리적 표시를 단체표장이나 증명표장으로 보호하고 있다","단순한 지명이 아니라 상품의 특정 품질·명성이 그 지역의 기후·토양·지형 등 지리적 환경에서 본질적으로 비롯될 때 그 생산지를 나타내는 표시이다"]}]}],"67":[{"t":"vs","title":"상표와 상호","cols":[{"name":"상표","items":["상인이 취급하는 상품의 출처를 나타내는 표장이다 · '갤럭시 S'는 상표이다","등록 상표는 전국적 범위에서 배타적·독점적 권리를 갖는다","상표 등록 절차는 특허청을 통해 이루어지고, 등록된 상표권은 전국적 범위에서 동일·유사 상표의 무단 사용에 대해 손해배상 청구 등을 할 수 있는 독점적 권리이다"]},{"name":"상호","items":["상인이 영업상 자기 자신을 표시하는 명칭이다 · '삼성전자주식회사'는 상호이다","상인이 어떤 명칭을 상호로 사용하면 권리가 자동으로 생기는 사용주의이고, 등기를 해야만 상호권이 발생하는 것은 아니다","법원 등기를 하면 제한된 행정구역 안에서 동일 업종에 한해 상법으로 보호된다","동일 상호가 지역을 달리해 쓰이거나 유사한 상호가 같은 지역에서 쓰일 수 있어 타인의 모방을 차단하기 쉽지 않으므로, 모방 가능성이 높은 명칭은 상표로 등록해 두는 것이 바람직하다"]}]},{"t":"table","title":"도메인이름과 상표","head":["구분","내용"],"rows":[["도메인이름","컴퓨터의 IP 주소를 이용자가 알기 쉽게 문자와 숫자로 표현한 것이다"],["등록 권리","국내에 상표를 등록했다고 해서 그 상표에 해당하는 도메인이름을 등록할 권리가 당연히 생기는 것은 아니며, 반대로 도메인이름을 등록했다고 해서 그 상표를 등록할 권리가 생기는 것도 아니다"],["부정경쟁행위","널리 알려진 상표와 동일·유사한 도메인이름을 타인이 등록하거나 그 사이트에서 지정상품과 동종의 상품을 광고·판매하면 부정경쟁행위나 상표권 침해행위가 될 수 있다"],["사이버스쿼팅","타인의 상표를 부정한 목적으로 도메인이름으로 등록해 정당한 상표권자에게 비싼 값에 되팔려는 행위이다"]]}],"68":[{"t":"table","title":"식별력","head":["구분","내용"],"rows":[["식별력","거래자나 일반 수요자가 해당 상품이나 서비스를 보고 누구의 것인지 알 수 있게 하는 것을 말한다 · 식별력의 유무는 일반적으로 지정상품과 관련하여 판단하므로 같은 단어라도 지정상품에 따라 식별력이 달라질 수 있다"],["식별력 없는 상표","상표법 제33조 제1항은 식별력 없는 상표를 보통명칭, 관용표장, 기술적 표장, 현저한 지리적 명칭, 흔한 성 또는 명칭, 간단하고 흔한 표장, 기타 식별력 없는 표장의 7가지로 나열한다"],["식별력이 있는 상표","상품의 특성을 암시하는 정도의 상표는 식별력이 있고, 임의선택 상표와 조어상표는 식별력이 강해 조어상표는 효력범위가 넓어 강한 보호가 가능하다"]]},{"t":"table","title":"보통명칭과 관용표장","head":["구분","내용"],"rows":[["보통명칭","특정 상품의 명칭을 나타내는 표장으로, 상품 자체를 일반적으로 표시하는 데 불과하여 특정인이 독점할 수 없다"],["식별력 상실","등록상표도 소비자와 동종업자가 자유롭게 사용한 결과 상품의 보통명칭이 되어 식별력을 잃을 수 있어 상표 관리에 만전을 기해야 한다"],["잘못 인식된 예","신제품이나 특허품의 상표가 그 상품의 보통명칭으로 잘못 인식되어 쓰이는 경우의 예로 스테이플러의 '호치키스'와 투명 접착테이프의 '스카치테이프'가 있다"],["관리 소홀의 예","상표권자의 관리 소홀을 틈타 경쟁업자들이 타인의 상표를 자유롭게 사용하게 된 경우의 예로 해열진통제의 '아스피린'이 있다"],["관용표장","원래는 특정인의 상표였으나 동종업자들 사이에서 특정 종류 상품의 명칭으로 일반적으로 사용된 결과 식별력을 상실한 표장이다 · 직물에 대한 TEX·LON, 통신업에 대한 cyber·web·net, 요식업에 대한 가든·장·성·원은 관용표장의 예이다"]]}],"69":[{"t":"table","title":"기술적 표장","head":["구분","내용"],"rows":[["기술적 표장","상품의 품질·효능·용도 등의 성질을 직접적으로 기술하는 데 불과한 표장을 기술적 표장 또는 성질표시표장이라 하며, 누구나 자유롭게 써야 하므로 특정인에게 독점시킬 수 없다"],["상대적 판단","어떤 표장이 기술적 표장인지는 상품과의 관계에서 상대적으로 정해지므로 'Kickers'는 축구화에는 용도표시이지만 초콜릿에는 상표등록이 가능할 수 있다"],["판례","상표가 상품의 특성을 암시 또는 강조하는 것으로 보일 뿐 일반 수요자가 그로부터 상품의 특성을 직감할 수 없다면 기술적 표장이 아니라고 본다"],["예","'airfryer'를 가정용 전기식 튀김기에 쓰는 것은 성질표시 표장에 해당하지만, '알바천국'을 직업소개업에 쓰는 것은 성질을 직접 표시하는 것으로 인식되지 않아 기술적 표장이 아니라고 판단되었다"]]},{"t":"table","title":"그 밖의 식별력 없는 표장","head":["구분","내용"],"rows":[["현저한 지리적 명칭","수요자에게 현저하게 인식된 지리적 명칭으로, 식별력이 없고 특정인에게 독점시키는 것이 공익상 부당하여 상표등록을 받을 수 없다 · '종로학원'의 '종로'는 서울특별시 종로구의 명칭이자 거리의 이름을 나타내는 현저한 지리적 명칭이라고 판단되었다"],["흔한 성 또는 명칭","흔히 있는 성이나 명칭을 보통으로 사용하는 방법으로 표시한 표장만으로 된 상표는 등록될 수 없다 · 외국인의 성은 그 나라에서 흔하더라도 국내에서 흔히 볼 수 있는 것이 아니라면 흔히 있는 성에 해당하지 않는다"],["간단하고 흔한 표장","문자상표 중 1자의 한글이나 2자 이내의 알파벳으로 구성된 표장은 원칙적으로 간단하고 흔한 표장에 해당한다 · LG·GS·SK처럼 특정인의 출처표시로 직감되는 경우에는 간단하고 흔한 표장에 해당하지 않으며, 도안화나 색채 결합으로 새로운 식별력이 생기면 등록받을 수 있다"],["제7호","제33조 제1항 제7호는 제1~6호에 해당하지 않아도 그 취지상 거절해야 할 상표를 거절하도록 한 보충적 규정이며, 일반적으로 쓰이는 구호·표어·인사말은 등록받기 어렵다"],["거절 사유","제33조 제1항 각 호의 식별력 없는 상표는 등록 전에는 거절·정보제공·이의신청 사유가 된다"]]}],"70":[{"t":"table","title":"공익적 부등록사유","head":["구분","내용"],"rows":[["부등록사유","식별력이 있더라도 등록하여 독점시키면 공익 또는 타인의 이익을 침해하는 상표는 부등록사유에 해당하여 등록받을 수 없다"],["국기·훈장·공공마크","대한민국 국기·국장, 파리협약 동맹국 등의 훈장·포장, 국제적십자·국제올림픽위원회 등의 공공마크와 동일·유사한 상표는 등록받을 수 없다"],["거짓 표시·비방","국가·인종·민족·공공단체·종교 또는 저명한 고인과의 관계를 거짓으로 표시하거나 이들을 비방·모욕할 염려가 있는 상표는 등록받을 수 없다"],["저명한 표장","국가·공공단체 또는 비영리 공익법인의 저명한 표장(YMCA, 보이스카우트, 적십자 등)과 동일·유사한 상표는 등록받을 수 없다"],["선량한 풍속","일반인의 통상적인 도덕관념인 선량한 풍속에 어긋나 공공의 질서를 해칠 우려가 있는 상표는 등록받을 수 없다"],["박람회","정부 또는 외국정부가 개최하거나 그 승인을 얻어 개최하는 박람회의 상패·상장·포장과 동일·유사한 표장이 있는 상표는 등록받을 수 없다"],["타인의 성명 등","저명한 타인의 성명·명칭·상호·초상 또는 이들의 약칭을 포함하는 상표는 등록받을 수 없지만 그 타인의 승낙을 받으면 등록받을 수 있다"]]}],"71":[{"t":"table","title":"선출원상표와 공존동의","head":["구분","내용"],"rows":[["선출원상표","타인의 선등록 또는 선출원 상표와 동일·유사한 상표로서 그 지정상품과 동일·유사한 상품에 사용하는 상표는 원칙적으로 등록받을 수 없다"],["상표공존동의제도","선등록(출원)상표 권리자가 표장과 지정상품이 동일·유사한 후출원상표의 등록에 동의하면 제34조 제1항 제7호 등의 거절이유가 해소되어 등록이 가능하게 하는 제도이다"],["시행","상표공존동의제도는 2023년 개정법에서 도입되어 2024년 5월 1일부터 시행되었다"],["취소","공존하게 된 상표 중 어느 한쪽이라도 추후 부정한 목적으로 사용되어 수요자의 오인·혼동을 일으키면 등록을 취소할 수 있다"],["동의서","상표공존동의서는 출원서, 의견서 또는 보정서에 첨부하여 제출할 수 있다"],["효과","상표공존동의제로 중소기업·소상공인이 선상표권자의 동의를 얻어 상표를 등록하고 계속 사용할 수 있게 되며 추후 상표 분쟁을 미연에 막는 효과가 기대된다"]]}],"72":[{"t":"table","title":"주지·저명상표 등 부등록","head":["구분","내용"],"rows":[["주지상표","타인의 상품을 표시하는 것으로 수요자에게 널리 인식된 주지상표와 동일·유사한 상표로서 그 타인의 상품과 동일·유사한 상품에 사용하는 상표는 등록받을 수 없다 · 출원상표의 지정상품과 동종업계에서 특정인의 상표라고 널리 인식된 상표를 말한다"],["저명상표","이종상품이나 이종영업 분야에서까지 특정인의 상표로 현저하게 인식된 상표이며, 수요자 혼동이나 식별력·명성 손상(희석화) 우려가 있으면 영업적 관련성이 없어도 등록받을 수 없다"],["품질 오인","상품의 품질을 오인하게 하거나 수요자를 기만할 염려가 있는 상표는 등록받을 수 없으며, 지정상품을 '청주'로 하면서 '보드카'라는 표장으로 출원하는 경우가 그 예이다"],["부정한 목적","국내 또는 외국에서 특정인의 상품을 표시하는 것으로 인식된 상표와 동일·유사한 상표를 부당한 이익을 얻으려는 등 부정한 목적으로 사용하는 상표는 등록받을 수 없다 · 국내 또는 외국에서 특정 지역의 상품을 표시하는 것으로 인식된 지리적 표시와 동일·유사한 상표를 부정한 목적으로 사용하는 상표는 등록받을 수 없다"],["제척기간·기준 시점","주지상표에 관한 규정(제34조 제1항 제9호)은 등록 후 설정등록일로부터 5년이 지나면 무효를 주장할 수 없는 제척기간이 적용된다 · 제34조 제1항 제13호의 부정한 목적 규정은 인용상표의 주지 여부를 국내 또는 외국을 기준으로 판단하며 부정한 목적이 있어야 한다 · 제9호 주지 여부는 상표등록 여부를 결정할 때를 기준으로 하고, 제13호는 상표등록출원을 한 때를 기준으로 한다"],["기능성 상표","상품 또는 포장의 기능을 확보하는 데 불가결한 입체적 형상·색채·색채의 조합·소리·냄새만으로 된 상표는 등록받을 수 없다 · 컵의 오목한 형상, 양식당의 포크·나이프, 캔의 오목한 바닥은 각각 기능 수행, 이용 과정, 품질·가격 경쟁에서 필수적이라고 볼 수 있는 기능성 형상의 예이다"],["포도주·증류주","WTO 회원국 내 포도주·증류주의 산지에 관한 지리적 표시로 구성되거나 이를 포함하는 상표로서 포도주·증류주에 사용하려는 상표는 등록받을 수 없다"]]}],"73":[{"t":"table","title":"상표의 동일·유사","head":["구분","내용"],"rows":[["동일·유사 요건","상표가 동일·유사하다고 하려면 표장과 상품이 모두 동일·유사해야 하며, 표장이 같아도 상품이 비유사하거나 상품이 같아도 표장이 비유사하면 상표의 동일·유사가 아니다"],["혼동의 가능성","상표법은 실제로 혼동을 일으킨 사실이 있는지가 아니라 혼동의 가능성만 있으면 사용을 금지할 수 있는 권리가 있다고 본다"],["상표의 동일","구성요소가 문자 그대로 같은 물리적 동일뿐 아니라 거래사회 통념상 같다고 볼 수 있는 실질적 동일(동일성)까지 포함된다"],["상품의 유사","두 상품이 동일한 정도는 아니지만 거래사회에 오인·혼동을 일으킬 정도로 비슷한 것을 말한다"]]},{"t":"table","title":"상품분류와 유사군코드","head":["구분","내용"],"rows":[["니스분류","상표법상 상품분류는 니스(NICE)국제상품분류를 기반으로 하여 상품 및 서비스업을 총 45개 류로 나눈다 · 제1류부터 제34류까지는 상품이고 제35류부터 제45류까지는 서비스업이다"],["유사군코드","상품 분류를 기호화한 것으로 상품은 G, 서비스업은 S로 시작하며 상품류가 다르더라도 유사군코드가 같으면 원칙적으로 유사한 상품으로 본다 · 상품류가 같아도 유사군코드가 다르면 서로 비유사한 것으로 보고 심사한다"],["예: 애완동물용품","새장(21류), 담요(24류), 급식매트(27류), 장난감(28류), 모래종이(31류)처럼 상품류가 달라도 유사군코드 G1817로 같아서 유사한 상품으로 본다"],["예: 신발류와 모자","같은 25류에 속하는 신발류(G2501)와 모자(G450501)는 유사군코드가 달라 서로 비유사한 상품이므로 모자에 먼저 등록된 상표가 있어도 신발류에 같은 상표를 등록받을 수 있다"],["심사와 심판","특허청 심사 단계에서는 심사의 신속성과 통일성을 위해 유사군코드를 참고하지만, 심판·소송 단계에서는 유사군코드에 구애받지 않고 거래의 실정을 따져 개별적으로 판단한다"],["판례","지정상품의 유사 여부를 동일 업체에서 제조·판매되는 상품으로 오인될 우려가 있는지를 기준으로 하되, 품질·형상·용도, 생산·판매부문, 수요자 범위 등 거래의 실정을 종합해 판단한다"]]}],"74":[{"t":"flow","title":"상표 출원 절차","steps":["상표등록출원은 출원인이 보호받으려는 상표와 상품을 적은 출원서를 특허청장에게 제출해 상표권의 부여를 요구하는 절차이다","거절이유가 없으면 출원공고를 하여 제3자에게 이의신청의 기회를 주고, 거절이유가 있으면 의견제출통지를 하여 의견서 제출의 기회를 준다","누구든지 출원공고일로부터 2개월 이내에 이의신청을 제기하여 그 출원이 등록받을 수 없음을 주장할 수 있다","이의신청이 없거나 이유가 없다고 판단되면 등록결정을 하고, 출원인이 등록료를 납부하면 상표등록이 되어 상표권이 발생한다"]},{"t":"def","term":"상표권의 발생","text":"상표권은 상표등록을 함으로써 발생한다","ex":["출원인은 의견서 제출, 보정, 분할, 변경, 우선권주장 등의 절차를 통해 보호를 받을 수 있다"]}],"75":[{"t":"table","title":"상표검색","head":["구분","내용"],"rows":[["필요성","출원하려는 상표가 등록받을 수 있는지, 또 등록 전에 사용해도 타인의 상표권을 침해하지 않는지를 가늠하기 위해 출원에 앞서 해 볼 필요가 있다"],["목적","출원·사용하려는 상표와 동일·유사한 상표가 선출원 또는 선등록되어 있는지를 조사해 등록가능성과 사용가능성을 확인하는 것이다"],["DB","유료 DB를 이용하기도 하지만 무료 DB를 제공하는 특허정보넷 키프리스를 이용하는 경우가 많다"],["검색 방법","사용할 상품을 정하고 류구분을 확정한 뒤 구성요소를 고려해 검색어를 정해 검색하며, 결과에서 권리자·존속기간·권리 소멸 여부를 확인하고 유사 여부를 대비해 등록 가능성을 판단한다"],["도형상표","도형상표를 검색할 때는 문자 검색 대신 비엔나분류에 의한 도형코드를 이용한다"],["전문가","상표검색은 전문 지식과 실무 경험이 뒷받침되어야 정확하므로 중요한 상표는 변리사 등 전문가의 도움을 받아 철저히 검색해야 한다"]]}],"76":[{"t":"table","title":"상표 출원서","head":["구분","내용"],"rows":[["출원서 기재","상표등록출원서에는 출원인의 성명과 주소, 상표, 지정상품 및 그 류구분, 우선권주장에 관한 사항(우선권주장을 하는 경우에 한함)을 적어 특허청장에게 제출한다"],["출원일","상표등록출원서가 제출되면 출원일이 인정되나 중대한 하자가 있으면 보완명령이 내려지고, 보완한 절차보완서를 제출한 날이 출원일로 인정된다 · 지정상품의 기재가 없는 경우, 국어로 기재되지 않은 경우, 출원인 특정이 불가능한 경우 등은 중대한 하자로 보완명령이 내려진다"],["1상표 1출원","출원은 상품류 구분에 따라 1류 이상의 상품을 지정해 1상표마다 1출원해야 하며, 1개 상표에 다수 류의 상품을 지정해 출원하는 것은 가능하다 · 1상표 1출원 원칙을 위반한 출원은 거절이유가 되지만, 일단 등록이 되었다면 이는 절차상 편의를 위한 것이므로 상표등록 무효사유는 되지 않는다"]]},{"t":"table","title":"상표 우선심사","head":["구분","내용"],"rows":[["신청","상표 우선심사는 출원인이나 이해관계인이 신청할 수 있고, 출원과 동시 또는 출원 후 아직 심사되지 않은 출원이라면 가능하다"],["대상","출원인이 아닌 자가 정당한 사유 없이 동일·유사한 상표를 유사 상품에 사용하고 있다고 인정되고 출원인이 사용금지를 경고하거나 가처분신청을 한 경우는 우선심사 대상이다 · 출원인이 출원상표를 지정상품 전부에 사용하고 있거나 사용 준비를 하고 있음이 명백한 경우처럼 긴급한 처리가 필요하다고 인정되는 출원도 우선심사 대상이다"],["제출 서류","우선심사는 우선심사신청서에 우선심사신청설명서를 첨부하여 신청해야 하며 상표사용 사실이나 준비 중인 사실을 입증하는 자료를 제출한다"]]}],"77":[{"t":"table","title":"상표 심사","head":["구분","내용"],"rows":[["의견제출통지","심사관이 거절이유가 있다고 판단하면 출원인에게 의견제출통지서를 보내 거절이유를 설명하며, 지정상품별로 거절이유와 근거를 구체적으로 밝혀야 한다"],["출원인의 대응","출원인은 심사관의 지적이 부당하면 의견서만 제출하고, 타당하다면 보정서나 분할출원서로 하자를 치유하면서 의견서를 함께 제출한다"],["거절결정","심사관은 의견제출통지 후에도 거절이유가 해소되지 않았다고 판단하면 거절결정을 한다"],["출원공고결정","심사관이 거절이유를 찾지 못하거나 거절이유가 해소되었다고 보면 출원공고결정을 하고, 특허청장이 이를 상표공보에 게재한다 · 출원공고는 등록 전에 출원 내용을 알려 제3자에게 이의신청 기회를 주고 심사의 공정성을 높이려는 제도이다 · 출원공고 후에도 심사관은 거절이유를 발견하면 직권으로 거절이유를 통지할 수 있다"]]},{"t":"table","title":"부분거절과 재심사","head":["구분","내용"],"rows":[["부분거절제도","도입으로 거절이유가 없는 일부 지정상품만이라도 등록받을 수 있게 되었으며, 2023년 2월 4일부터 시행되었다 · 지정상품 중 일부에만 거절이유가 있으면 그 상품만 거절하고 나머지 상품은 등록할 수 있다"],["부분거절결정","심사관은 거절이유가 해소되지 않은 지정상품에 대해서만 거절결정을 하고, 부분거절결정이 확정된 후에 나머지 지정상품에 대해 출원공고결정을 한다"],["분할","거절이유가 없는 상품을 조기에 등록받으려면 그 상품을 별도의 출원으로 분할해야 한다"],["재심사청구","출원인은 거절결정 등본을 송달받은 날부터 3개월 이내에 재심사를 청구할 수 있다 · 지정상품 보정처럼 거절이유를 간단히 해소할 수 있을 때 심판 없이 심사관에게 다시 심사받게 하는 불복수단이다"]]}],"78":[{"t":"table","title":"상표 등록과 보정","head":["구분","내용"],"rows":[["등록료","상표등록료는 이해관계인도 납부할 수 있고, 2회로 나누어 납부하는 것도 가능하다 · 등록료가 납부되면 특허청장이 상표권의 설정등록을 하고 상표권자에게 상표등록증을 교부한다"],["보정","출원인은 최초 출원의 요지를 변경하지 않는 범위에서 등록결정(거절결정) 통지서가 송달되기 전까지 출원상표와 지정상품을 보정할 수 있다 · 지정상품의 감축, 오기 정정, 불명료한 내용의 명확화는 요지를 변경하지 않는 보정에 해당한다"]]},{"t":"table","title":"분할과 변경","head":["구분","내용"],"rows":[["분할출원","2 이상의 상품을 지정상품으로 출원한 경우 그 출원을 2 이상의 출원으로 분할할 수 있다 · 적법하게 분할된 출원은 원출원을 한 때에 출원한 것으로 보아 출원일이 소급된다 · 출원을 분할하면서 지정상품을 추가하거나 확대하는 것은 허용되지 않는다"],["등록 후 분할","상표등록 후에도 지정상품이 2 이상이면 상표권자는 상표권을 지정상품별로 분할할 수 있다"],["출원의 변경","출원 내용은 그대로 두고 상표·단체표장·증명표장 같은 권리 구분만 바꾸는 것이다 · 지리적 표시 단체표장과 증명표장은 변경 대상에서 제외된다"]]}],"79":[{"t":"table","title":"손실보상청구권","head":["구분","내용"],"rows":[["발생","출원공고 후 출원상표와 같거나 유사한 상표를 지정상품과 같거나 유사한 상품에 사용하는 자에게 서면으로 경고하면 손실보상청구권이 생긴다"],["행사","손실보상청구권은 상표권의 설정등록 후에 행사할 수 있다"],["소멸","상표등록출원이 포기·취하·무효되거나 거절결정이 확정되면 손실보상청구권은 처음부터 없었던 것으로 본다 · 등록일부터 3년, 제3자의 사용일부터 10년이 지나면 시효로 소멸한다"]]},{"t":"table","title":"우선권주장","head":["구분","내용"],"rows":[["조약우선권주장 기간","특허·실용신안은 12개월, 디자인·상표는 6개월 이내에 해야 한다"],["효과","우선권주장이 적법하면 제2국 출원일을 제1국 출원일로 소급한 것과 같은 효과가 인정된다"],["서류 제출","우선권을 주장하는 출원인은 출원일부터 3개월 이내에 우선권주장증명서류를 특허청장에게 제출해야 한다"],["출원서","우선권주장 출원서에는 우선권을 주장한다는 취지와 최초로 출원한 국명 및 출원연월일을 적어야 한다"]]}],"80":[{"t":"vs","title":"정보제공과 이의신청","cols":[{"name":"정보제공","items":["누구든지 거절이유가 있다는 정보를 증거와 함께 특허청장에게 제공하는 제도로, 기간 제한이 거의 없고 수수료도 없다","정보제공자에게는 이의신청인과 달리 충분한 절차보장권이 인정되지 않는다"]},{"name":"이의신청","items":["출원공고가 있으면 누구든지 공고일부터 2개월 이내에 거절이유가 있음을 이유로 상표등록 이의신청을 할 수 있다","이의신청인은 이의신청기간이 지난 뒤 30일 이내에 이의신청서의 이유와 증거를 보정할 수 있다","3인의 심사관 합의체가 담당한다","이의결정 자체는 별도로 다툴 수 없고, 출원인은 거절결정불복심판으로, 이의신청인은 등록 후 무효심판으로 부당함을 다툴 수 있다"]}]}],"81":[{"t":"table","title":"상표권의 존속기간과 불사용취소","head":["구분","내용"],"rows":[["존속기간","상표권의 존속기간은 설정등록이 있는 날부터 10년이며, 갱신등록으로 10년씩 갱신할 수 있다 · 상표권은 설정등록에 의하여 발생한다"],["불사용취소심판","등록상표를 최근 3년간 사용한 사실이 없으면 취소심판의 대상이 된다 · 상표권자는 지정상품 중 하나 이상에 대해 등록상표와 동일한 범위의 상표를 사용했음을 입증하면 취소를 면할 수 있다"],["제도의 취지","상표를 선점만 하고 쓰지 않으면서 타인의 사용도 막는 등록주의의 폐단을 바로잡기 위한 제도이다"],["활용","선등록상표 때문에 의견제출통지를 받았을 때 그 선등록상표가 쓰이지 않고 있다면 불사용취소심판으로 거절이유를 해소할 수 있다"]]}],"82":[{"t":"table","title":"상표권 양도와 사용권","head":["구분","내용"],"rows":[["양도","상표권은 영업과 분리하여 매매나 증여 등으로 자유롭게 양도할 수 있다 · 지정상품을 분할하여 이전할 때에는 이전 대상 상품과 유사한 상품도 함께 이전해야 한다"],["전용사용권","전용사용권자는 설정된 범위 안에서 지정상품에 등록상표를 독점적으로 사용할 권리를 가지며, 타인의 침해에 대해 금지·예방을 청구할 수 있다 · 상표권자의 동의를 얻어 전용사용권을 이전하거나 통상사용권을 설정할 수 있다 · 설정과 이전 등은 등록해야만 제3자에게 대항할 수 있다 · 상표권자와 달리 등록상표를 사용하는 상품에 자기의 성명 또는 명칭을 표시해야 한다"],["통상사용권","설정 범위 안에서 비독점적으로 사용하는 권리로, 상표권자도 같은 상표를 사용할 수 있고 다른 사람에게도 사용을 허락할 수 있다 · 통상사용권자는 등록상표를 사용할 권리만 있으므로 권리침해에 대한 금지청구권이 없다 · 상표권자 또는 전용사용권자가 설정할 수 있다"]]}],"83":[{"t":"table","title":"상표권의 효력","head":["구분","내용"],"rows":[["효력","상표권의 효력은 본인이 상표를 사용하는 사용권과 남의 사용을 막는 배타권으로 이루어진다 · 배타권은 실시권과 달리 상표 및 지정상품의 유사범위까지 미친다 · 속지주의 원칙상 대한민국 영토 안에서만 효력이 있다"],["보호범위","상표권의 보호범위는 출원서에 적은 상표와 기재사항, 그리고 지정상품에 의하여 정해진다 · 소리상표나 냄새상표는 상표견본이 없으므로 출원서에 기재한 시각적 표현에 따라 보호범위가 정해진다"],["침해 성립","침해가 성립하려면 유효한 등록상표가 있어야 하고, 침해자의 사용이 상표적 사용이어야 하며, 사용권 등 정당한 권원이 없어야 한다 · 침해를 위해 등록상표와 유사한 상표를 교부·판매·위조·소지하는 예비적 행위도 상표권 침해로 본다"]]},{"t":"table","title":"상표권의 효력 제한","head":["구분","내용"],"rows":[["성명·상호 등","상표권의 효력은 자기의 성명·명칭·상호 등을 상거래 관행에 따라 사용하는 상표에는 미치지 않는다 · 상표권 등록 후 부정경쟁 목적으로 자기의 성명이나 상호 등을 사용하는 경우에는 효력 제한 규정이 적용되지 않는다"],["보통명칭","등록상표가 나중에 식별력을 잃어 보통명칭이 된 경우 상표권자는 타인의 사용을 금지할 수 없다"],["사용에 의한 식별력","처음엔 식별력이 없었더라도 사용에 의해 식별력을 취득해 등록된 상표는 타인의 사용 금지를 청구할 수 있다"],["효력이 미치지 않는다는 뜻","효력이 미치지 않는다는 것은 타인의 사용을 금지하는 효력이 제한된다는 뜻이며 상표권자 자신의 사용권이 제한된다는 뜻은 아니다"]]}],"84":[{"t":"table","title":"침해 대응","head":["구분","내용"],"rows":[["권리범위확인심판","상표권 침해 여부를 확실히 알기 위해 특허청에 권리범위확인심판을 청구할 수 있다"],["경고장","침해 사실과 함께 로열티나 침해중지 같은 요구사항을 알리는 문서로, 받은 순간부터 고의로 추정되어 침해자의 책임이 커진다 · 등록상표임을 표시한 타인의 상표권을 침해한 경우 경고장과 상관없이 고의로 추정된다"],["허위표시","등록하지 않은 상표를 등록상표인 것처럼 표시하는 것은 허위표시의 죄에 해당한다"],["산업재산권 분쟁조정","신청비용이 무료이고 비공개로 진행되며, 양 당사자가 조정안을 수락하면 민법상 화해계약의 효력이 생긴다"]]}],"85":[{"t":"table","title":"상표권 민형사 구제","head":["구분","내용"],"rows":[["구제의 구분","상표권 침해에 대한 구제는 경고장 발송이나 분쟁조정 신청 같은 협상에 의한 해결과, 형사고발·민사소송 같은 법적 조치에 의한 해결로 나뉜다"],["침해금지 가처분","소송 결과가 나올 때까지 침해자가 침해물을 처분해버리는 것을 막으려고 본안 소송과 함께 신청하는 경우가 많다"],["민사소송","민사소송에서는 침해금지, 손해배상, 신용회복을 청구할 수 있다 · 침해금지 청구는 침해 중지를, 손해배상·부당이득반환 청구는 금전적 배상을, 신용회복조치 청구는 신용회복조치를 결과로 얻는다"],["형사","상표권 침해가 침해죄로 인정되면 벌금 또는 징역형과 함께 침해물이 몰수될 수 있다 · 상표 침해는 다른 산업재산권과 달리 제3자도 고발할 수 있고, 특허청 상표권 특별사법경찰이 직접 단속하기도 한다"]]}],"86":[{"t":"table","title":"속지주의와 개별출원","head":["구분","내용"],"rows":[["속지주의","상표 보호에서 조약과 대부분의 국가는 속지주의를 따르므로, 자국에 등록된 상표라도 외국에서 권리를 얻으려면 그 나라에 상표등록출원을 해야 한다"],["해외출원의 두 가지","개별국가나 지역공동체기구에 출원하는 방식과 국제등록 시스템을 이용하는 방식의 두 가지로 나뉜다"],["개별출원","보호받으려는 국가나 지역기구에 해당국 대리인을 통해 직접 출원하는 방식으로, 국가별로 심사와 등록이 따로 진행되어 시간과 비용이 많이 든다 · 개별출원을 할 때는 파리협약에 따른 우선권을 주장하여 출원하는 경우가 많다"]]}],"87":[{"t":"tree","title":"마드리드 시스템","root":"마드리드 시스템은 WIPO 국제사무국에 국제출원을 하면서 보호받을 국가를 지정하면 지정국별로 심사하여 상표권 부여 여부를 결정하는 국제출원·등록 제도이다","branches":[["기초출원·기초등록","마드리드 국제출원을 하려면 본국 특허청에 계속 중인 상표출원이나 이미 등록된 상표가 있어야 하며, 이를 기초출원 또는 기초등록이라 한다"],["본국관청","우리나라 출원인에게 본국관청은 한국 특허청이며, 출원인은 본국관청에 국제출원서를 제출해야 한다 · 국제출원서의 기재사항이 기초출원과 합치하는지 심사한 뒤 WIPO로 보낸다"],["국제등록","WIPO가 방식심사 후 국제등록부에 등재하는 것이 국제등록이다"],["지정국관청","출원인이 보호받기를 원해 지정한 국가의 관청으로, 각국의 상표법령에 따라 심사하여 보호 여부를 결정한다"]]}],"88":[{"t":"table","title":"마드리드 출원의 효과","head":["구분","내용"],"rows":[["출원 효과","영어로 작성한 하나의 국제출원서를 본국관청에 내면 지정한 여러 국가에 같은 날짜로 출원한 것과 같은 효과가 있다 · 여러 지정국에 내야 할 출원 수수료를 출원인이 WIPO에 일괄하여 납부하면 된다"],["변경 사항","명의 변경, 주소 변경, 갱신, 양도 등은 WIPO 국제등록부만 한 번 변경하면 모든 지정국에 자동으로 반영된다"],["대리인","거절이유 없이 등록되면 현지대리인 선임이 필요 없어 비용을 줄일 수 있다 · 지정국에서 거절이유를 통지받아 의견서나 보정서를 내려면 해당 국가의 변리사를 대리인으로 선임해야 한다"],["거절통지 기간","지정국 관청은 원칙적으로 국제사무국의 지정통지를 받은 날부터 1년(1년 6개월까지 연장 가능) 안에 거절통지를 하지 않으면 그 상표는 등록된 것과 같은 보호를 받는다"],["사후지정","국제등록 후 국제등록의 지정상품 범위 안에서 지정국이나 일부 지정상품을 추가로 확대하는 제도이다"],["선택","다수국에서 상표등록을 꾀할 때 각국 통상의 출원 절차를 따를지 마드리드 시스템을 따를지는 출원인의 선택 사항이다"]]},{"t":"table","title":"국제등록의 존속","head":["구분","내용"],"rows":[["국제등록일","본국관청이 국제출원서를 수리한 날로부터 2개월 이내에 국제사무국이 이를 수령하면 본국관청의 수리일이 국제등록일이 된다"],["유효기간·갱신","국제등록은 국제등록일로부터 10년간 유효하며, 지정국마다 갱신신청을 할 필요 없이 국제사무국에 수수료를 내면 10년씩 갱신된다"],["종속성","국제등록 후 5년간은 본국의 기초출원 또는 기초등록에 종속되어, 기초가 거절·무효 등으로 소멸하면 국제등록과 지정국의 권리도 함께 소멸할 수 있다"],["개별국 출원이 유리한 경우","지정국 수가 많지 않거나 보호받으려는 국가가 마드리드 체약국이 아닌 경우에는 개별국 출원이 오히려 유리할 수 있다"]]}],"89":[{"t":"table","title":"부정경쟁방지법","head":["구분","내용"],"rows":[["법의 취지","부정경쟁방지법은 상표등록이나 디자인등록을 받지 않았더라도 상품이나 서비스의 출처를 나타내는 표지를 보호하여 등록주의 법률을 보완한다"],["연혁","우리나라는 독일·일본 법제를 본떠 1961년 부정경쟁방지법을 제정했고, 1991년에 영업비밀 침해행위를 보호대상으로 추가했다"],["정식 명칭","부정경쟁방지법의 정식 명칭은 「부정경쟁방지 및 영업비밀보호에 관한 법률」이다"],["부정경쟁행위","부정경쟁방지법 제2조 제1호는 가목부터 파목까지 13가지 유형의 부정경쟁행위를 규정하고 있다"]]},{"t":"vs","title":"혼동초래행위와 저명상표 희석행위","cols":[{"name":"혼동초래행위","items":["국내에 널리 인식된 타인의 상품·영업표지와 동일하거나 유사한 표지를 사용하거나 그 표지를 쓴 상품을 유통하여 수요자에게 혼동을 일으키는 행위이다"]},{"name":"저명상표 희석행위","items":["국내에 널리 인식된 타인의 표지를 정당한 사유 없이 비상업적으로 사용하거나 사용한 상품을 판매·반포하여 식별력이나 명성을 손상하는 행위이다","'국내에 널리 인식된'은 거래자·수요자 사이의 주지 정도를 넘어 일반 공중의 대부분이 알 정도의 저명 정도를 뜻한다는 것이 판례의 입장이다"]}]}],"90":[{"t":"table","title":"오인유발행위","head":["구분","내용"],"rows":[["오인유발행위","상품이나 광고에 거짓의 원산지·출처를 표시하거나 타인의 상품을 사칭하거나 · 품질·내용·제조방법·용도·수량 등을 오인하게 하는 행위이다"],["목적","일차적 피해자는 일반소비자이며, 이 행위의 금지는 경쟁자 보호보다 소비자 보호에 목적이 있다"],["혼동초래행위와의 차이","오인유발행위는 혼동초래행위와 달리 · 그 표지나 타인의 상품이 주지성을 획득했을 것을 요건으로 하지 않는다"]]},{"t":"table","title":"대리인 무단 상표사용과 사이버스쿼팅","head":["구분","내용"],"rows":[["대리인 무단 사용","국제성을 가진 상표의 대리인·대표자이거나 그였던 자가 · 정당한 사유 없이 무단으로 등록된 상표를 사용하는 행위이다 · 보호대상 상표는 파리협약 당사국, 세계무역기구 회원국 또는 상표법조약 체약국에 등록된 상표이다"],["사이버스쿼팅","정당한 권원이 없는 자가 부정한 목적으로 국내에 널리 인식된 타인의 표지와 · 같거나 유사한 도메인이름을 등록·보유·이전 또는 사용하는 행위이다"],["웹사이트 미개설","도메인이름을 등록하여 보유하기만 하고 웹사이트를 개설하지 않았더라도 · 사이버스쿼팅에 해당할 수 있다는 판결이 있다"]]}],"91":[{"t":"table","title":"형태모방행위","head":["구분","내용"],"rows":[["형태모방행위","타인이 개발·제작한 상품형태를 모방하여 자기의 상품으로 시장에 제공하는 행위이다"],["보호","형태모방행위(자목)로 보호받는 상품형태는 혼동초래행위(가목)와 달리 식별력·출처표시기능이나 국내 주지성이 없어도 보호받을 수 있다"],["3년 후","상품의 형태가 갖추어진 날부터 3년이 지나 식별기능·출처표시기능을 갖추고 주지성을 얻으면 혼동초래행위(가목)의 보호대상이 되어 보호받을 수 있다"]]},{"t":"table","title":"아이디어·데이터 부정사용행위","head":["구분","내용"],"rows":[["아이디어 부정사용행위","사업제안·입찰·공모 등 거래교섭 과정에서 경제적 가치가 있는 타인의 아이디어 정보를 제공목적에 위반하여 자기나 제3자의 영업상 이익을 위해 부정하게 사용하거나 제공하는 행위이다 · 아이디어 탈취행위 금지 조항은 2018년 개정으로 신설되었다"],["제외","아이디어를 제공받은 자가 제공받을 당시 이미 그 아이디어를 알고 있었거나 동종 업계에 널리 알려진 아이디어라면 부정사용행위에서 제외된다"],["데이터 부정사용행위","접근권한이 없는 자가 절취·기망·부정접속 등 부정한 수단으로 데이터를 취득하거나 그 데이터를 사용·공개하는 행위 등을 말한다 · 데이터 보유자와의 계약 등으로 접근권한이 있는 자가 부정한 이익을 얻거나 보유자에게 손해를 입힐 목적으로 데이터를 사용·공개하거나 제3자에게 제공하는 것도 부정사용행위이다 · 데이터 보호를 위한 기술적 보호조치를 정당한 권한 없이 회피·제거·변경하는 것을 주된 목적으로 하는 기술·서비스·장치를 제공·수입·제조·양도하는 행위도 포함된다"],["추가","데이터 부정사용행위는 4차산업혁명과 인공지능 시대에 데이터의 중요성이 커진 점을 반영하여 2021년 개정으로 부정경쟁행위에 추가되었다"]]}],"92":[{"t":"table","title":"초상·성과 도용과 일반조항","head":["구분","내용"],"rows":[["유명인의 초상·성명 등 부정사용행위","국내에 널리 인식되고 경제적 가치를 가지는 타인의 성명·초상·음성·서명 등을 공정한 상거래 관행이나 경쟁질서에 반하여 무단으로 사용해 타인의 경제적 이익을 침해하는 행위이다"],["타인의 성과 등 부정사용행위","타인의 상당한 투자나 노력으로 만들어진 성과를 공정한 상거래 관행이나 경쟁질서에 반하게 자기 영업을 위해 무단으로 사용하여 경제적 이익을 침해하는 행위이다"],["사례","외국 회사의 유명 핸드백과 유사한 형태의 가방을 무단으로 판매한 행위와 골프장 모습을 거의 그대로 재현한 스크린골프 영상 제작은 성과 등 부정사용행위로 인정된 사례가 있다"],["일반조항","2013년 개정으로 새로운 유형의 무형 성과 보호를 위해 기존 유형에 포함되지 않던 부정경쟁행위를 규율하는 보충적 일반조항이 신설되었다"]]}],"93":[{"t":"tree","title":"부정경쟁행위 구제수단","root":"부정경쟁행위 구제수단","branches":[["민사적 구제","금지청구권, 손해배상청구권, 신용회복청구권이 인정된다"],["행정적 구제","부정경쟁방지법은 위반행위자에 대한 행정조치로 · 특허청장의 부정경쟁행위 조사와 시정권고를 규정하고 있다"],["형사적 제재","징역과 벌금형이 규정되어 있다"]]}],"94":[{"t":"table","title":"상표법과 부정경쟁방지법","head":["구분","상표법","부정경쟁방지법"],"rows":[["보호 방식","상표등록으로 독점배타권을 부여하여 등록권리자를 보호","등록 여부를 묻지 않고 주지 표지의 모용을 금지하여 부정한 경쟁을 억제하고 수요자를 보호"],["보호의 조건","등록","주지성의 획득"],["금지 대상","상표권·전용사용권의 침해행위","개별적인 부정경쟁행위"],["침해 판단 기준","원칙적으로 상표 구성과 상품의 동일·유사","출처의 혼동가능성"],["구제","민사적·형사적 구제","민사적·형사적 구제에 더해 행정적 구제"],["등록받지 못하는 표지","상표법상 등록받지 못하는 표지","거래자나 수요자에게 상품·영업 표시로 널리 인식되면 보호한다"]]}],"95":[{"t":"flow","title":"저작권 제도의 연혁","steps":["저작권은 지식재산 중 예술·문학·음악·게임처럼 인간의 정신적 사상의 창작으로 정신문화 발전에 기여하는 것에 대한 권리이다","1450년경 구텐베르크의 활판인쇄술 발달과 함께 시작되었으며, 초창기에는 저작자보다 출판권자를 보호하는 제도의 성격이 강했다","1710년 영국의 앤 여왕법이 최초의 저작권 성문법이다","우리나라 최초의 저작권법은 1957년에 공포되었고, 무방식주의 채택과 저작권 존속기간을 생존기간 및 사후 30년으로 정한 것이 주요 내용이다"]},{"t":"table","title":"저작물의 요건","head":["구분","내용"],"rows":[["정의","저작권법은 저작물을 인간의 사상 또는 감정을 표현한 창작물이라고 정의한다 · 2006년 개정법은 저작물의 정의를 문학·학술·예술 범위의 창작물에서 인간의 사상 또는 감정을 표현한 창작물로 바꾸어 데이터베이스나 컴퓨터프로그램 같은 것도 포함하게 했다"],["요건","저작물로 인정되려면 인간의 사상 또는 감정에 관한 것, 표현, 창작적인 것의 세 가지 요건을 갖추어야 한다"],["사상 또는 감정","저작자의 정신 활동으로 볼 수 있으면 충분하고, 고상한 사상이나 높은 수준의 감정을 요구하지 않는다 · 자연 현상, 역사적 사실 같은 객관적 사실, 컴퓨터 등에 의해 자동 생성된 그림, 간단한 서식이나 계약서 등은 사상·감정의 표현으로 보기 어렵다"],["표현","저작권법의 보호를 받으려면 인간의 사상과 감정이 언어·문자·음·색채 등의 형식을 이용해 외부적으로 표현되어야 한다 · 일기처럼 공표되지 않았거나 원고 없이 하는 즉흥 강연·연주처럼 유형물에 고정되지 않은 것도 저작물로 보호된다"],["표현 형식","저작권은 사상·감정을 문자·음·색 등으로 구체적으로 나타낸 표현 형식을 보호하며, 아이디어나 이론 같은 내용 자체는 창작성이 있어도 보호대상이 아니다"]]}],"96":[{"t":"table","title":"저작물의 종류","head":["종류","내용"],"rows":[["예시","저작권법 제4조 제1항은 어문·음악·연극·미술·건축·사진·영상·도형·컴퓨터프로그램저작물을 저작물의 예시로 들고 있으며, 이는 대표적인 예시에 불과하다"],["어문저작물","소설·시·논문·강연·연설·각본 등 말과 글로 표현된 저작물이며, 단순한 표어·슬로건·캐치프레이즈는 저작물에 해당하지 않는다"],["음악저작물","사상 또는 감정이 규칙적으로 연속되어 나오는 음(선율)으로 표현된 저작물이며, 음의 표현 방식이 악기인지 육성인지는 묻지 않는다 · 가사가 수반된 곡은 음악저작물과 어문저작물의 결합저작물이다"],["연극저작물","연극·무용·무언극처럼 몸짓·움직임·정지·형 등 동작으로 표현되는 저작물이며, 각본은 어문저작물이고 연극이나 무용 자체의 실연은 저작인접권의 보호대상이다"],["응용미술저작물","물품에 동일한 형상으로 복제될 수 있는 것으로, 산업적으로 이용되더라도 물품과 구분되어 독자성이 인정되면 미술저작물로 보호된다"],["건축저작물","건축물과 건축을 위한 모형·설계도서 등으로 토지 위의 공작물에 의해 표현된 저작물이며, 건축물의 설계도는 도형저작물이 아닌 건축저작물에 포함된다"],["사진저작물","단순히 기계적 방법으로 피사체를 재현시킨 증명용 사진 등은 사진저작물성이 인정되지 않는다"],["영상저작물","영화·비디오 게임 화면처럼 음의 수반 여부와 관계없이 연속적인 영상이 수록된 창작물이며, 영화의 한 장면과 같이 정지된 화상은 사진저작물에 해당한다"],["도형저작물","지도·도표·설계도·약도·모형 등 도형의 형상·모형으로 표현된 저작물이다 · 일반적인 설계도는 그에 따라 물건을 제작하는 것이 복제권 침해가 되지 않으며, 건축설계도(건축저작물)만 복제권이 인정된다"],["컴퓨터프로그램저작물","특정한 결과를 얻기 위해 컴퓨터 등 정보처리능력을 가진 장치 내에서 직접 또는 간접으로 사용되는 일련의 지시·명령으로 표현된 저작물이다"]]}],"97":[{"t":"table","title":"2차적저작물","head":["구분","내용"],"rows":[["2차적저작물","원저작물을 번역·편곡·변형·각색·영상제작 등의 방법으로 작성한 창작물이다"],["보호 요건","편곡이나 변형이 2차적저작물로 보호받으려면 원저작물에 새로운 저작물이 될 정도의 수정·증감을 가하여 새로운 창작성이 부가되어야 한다"],["허락","2차적저작물을 작성하려는 자는 원저작물의 저작자로부터 허락을 받아야 한다 · 2차적저작물을 이용하려면 2차적저작물의 저작권자뿐 아니라 원저작권자의 허락도 함께 받아야 한다"]]},{"t":"table","title":"편집저작물과 데이터베이스","head":["구분","내용"],"rows":[["편집저작물","소재의 저작물성을 묻지 않고 수록할 소재를 독창적으로 선택·배열·구성하여 만든 편집물이다"],["편집물","저작물이나 부호·문자·음·영상 등 소재의 집합물이 편집물이고, 그중 소재의 선택·배열·구성에 창작성이 있는 것이 편집저작물이다 · 단순한 인명부나 알파벳순의 전화번호부처럼 소재의 선택·배열에 창작성이 없는 편집물은 편집저작물에 해당하지 않는다"],["보호","편집저작물은 소재와 별개로 독자적인 저작물로 보호되며, 편집저작물에 대한 권리는 구성 부분인 소재의 저작권에 영향을 미치지 않는다"],["데이터베이스","소재를 체계적으로 배열·구성하여 개별적으로 접근하거나 검색할 수 있게 한 편집물이며, 소재의 선택·배열에 창작성이 없어도 데이터베이스제작자는 소정의 권리를 가진다"]]}],"98":[{"t":"table","title":"저작자","head":["구분","내용"],"rows":[["저작자","저작물을 창작한 자이며, 자연인뿐 아니라 법인 등의 단체도 포함하는 것으로 해석할 수 있다"],["저작자가 될 수 없는 사람","창작에 동인이나 힌트만 제공한 사람, 조언자·수족으로 참여한 자, 그림의 주문자나 건축주 같은 작성 의뢰인은 저작자가 될 수 없다"],["저작권의 귀속","저작권은 창작한 때 자동으로 발생해 저작자에게 귀속되지만, 저작재산권은 이전이 가능하므로 나중에는 저작자와 저작권자가 달라질 수 있다"],["저작자 추정","저작물의 원본이나 복제물에 저작자로서 실명 또는 널리 알려진 이명이 일반적인 방법으로 표시된 자는 그 저작물의 저작자로 추정된다 · 저작물을 공연하거나 공중송신할 때 저작자로서 실명 또는 널리 알려진 이명이 표시된 자도 저작자로 추정된다 · 권리침해 시 입증을 용이하게 하고 저작물의 이용과 유통을 활성화하기 위해 둔 것이다"]]},{"t":"table","title":"외국인 저작물의 보호","head":["구분","내용"],"rows":[["보호 대상","외국인의 저작물은 대한민국이 가입·체결한 조약에 따라 보호되고, 대한민국 내에 상시 거주하는 외국인의 저작물과 맨 처음 국내에서 공표된 외국인 저작물도 보호된다"],["30일 이내","외국에서 공표된 날부터 30일 이내에 국내에서 공표된 외국인 저작물은 맨 처음 국내에서 공표된 것으로 보호된다"],["상호주의","외국에서 대한민국 국민의 저작물을 보호하지 않으면 그 외국인의 저작물에 대한 보호를 상응하게 제한할 수 있고, 외국에서 보호기간이 만료된 저작물에는 국내 보호기간도 인정하지 않는다"]]}],"99":[{"t":"table","title":"업무상저작물","head":["구분","내용"],"rows":[["업무상저작물","법인 등의 기획하에 법인 등의 업무에 종사하는 자가 업무상 작성하는 저작물이다"],["저작자","법인 등의 명의로 공표되는 업무상저작물의 저작자는 계약이나 근무규칙에 다른 정함이 없으면 법인 등이 된다 · 컴퓨터프로그램저작물은 업무상저작물로서 법인 등이 저작자가 되기 위해 공표될 것을 요하지 않는다"],["존속기간","업무상저작물의 저작재산권은 공표한 때부터 70년간 존속하며, 창작한 때부터 50년 이내에 공표되지 않으면 창작한 때부터 70년간 존속한다"]]},{"t":"table","title":"공동저작물","head":["구분","내용"],"rows":[["공동저작물","2명 이상이 공동으로 창작한 저작물로서 각자의 이바지한 부분을 분리하여 이용할 수 없는 것이다"],["권리 행사","저작재산권과 저작인격권은 저작자 전원의 합의가 있어야 행사할 수 있고, 다른 저작재산권자의 동의 없이는 자기 지분을 양도하거나 질권의 목적으로 할 수 없다"],["이익 배분","공동저작물의 이용에 따른 이익은 특약이 없으면 창작에 이바지한 정도에 따라 배분하고, 이바지한 정도가 명확하지 않으면 균등한 것으로 추정한다"],["존속기간","공동저작물의 저작재산권은 맨 마지막으로 사망한 저작자가 사망한 후 70년간 존속한다"]]}],"100":[{"t":"vs","title":"저작인격권과 저작재산권","cols":[{"name":"저작인격권","items":["저작자의 인격적 이익을 보호한다","성질상 타인에게 양도할 수 없는 일신전속적 권리이다","저작권법은 제11조부터 제13조까지로 규정한다","저작자 일신에 전속하므로 양도하거나 이전할 수 없고, 그 행사의 대리·위임은 권리의 본질을 해하지 않는 한도에서만 가능하다"]},{"name":"저작재산권","items":["저작물의 경제적 이익을 보호한다","양도나 상속이 가능하다","저작권법은 제16조부터 제22조까지로 규정한다"]}]},{"t":"table","title":"무방식주의와 저작인격권의 종류","head":["구분","내용"],"rows":[["무방식주의","저작권은 저작물을 창작한 때부터 발생하며 어떠한 절차나 형식의 이행도 필요로 하지 않는다 · 저작권에 관한 기본 조약인 베른협약이 무방식주의를 취하고 있어 일본·독일·프랑스 등 대다수 국가가 무방식주의를 따른다"],["저작인격권의 종류","우리 저작권법은 저작인격권으로 공표권, 성명표시권, 동일성유지권의 세 가지를 인정한다"],["공표권","저작자가 저작물을 공표할지 말지를 결정하는 권리이다 · 미공표 저작물의 저작재산권을 양도하거나 이용허락하면 그 상대방에게 공표를 동의한 것으로 추정한다 · 공표되지 않은 미술·건축·사진저작물의 원본을 양도하면 원본의 전시방식에 의한 공표에 동의한 것으로 추정한다 · 공표하지 않은 저작물을 도서관 등에 기증한 경우 별도의 의사표시가 없으면 공표에 동의한 것으로 추정한다"],["성명표시권","저작물의 원본이나 복제물 또는 공표 매체에 자기의 실명이나 이명을 표시할 권리이다"]]}],"101":[{"t":"table","title":"저작재산권의 종류","head":["권리","내용"],"rows":[["저작재산권","저작물을 이용하여 경제적 이익을 얻을 수 있는 권리로, 여러 개의 권리로 구성되고 각 권리는 독립적으로 행사하거나 양도·이용허락할 수 있다"],["복제","인쇄·사진촬영·복사·녹음·녹화 등의 방법으로 일시적 또는 영구적으로 유형물에 고정하거나 다시 제작하는 것이며, 건축의 경우 설계도서에 따라 시공하는 것도 포함한다 · 2011년 개정 저작권법은 디지털 환경에서 저작자의 권리를 보호하기 위해 일시적 저장을 복제의 범위에 명시했다"],["공연","저작물 등을 상연·연주·가창·구연·낭독·상영·재생 등의 방법으로 공중에게 공개하는 것으로, 동일인의 점유에 속하는 연결된 장소 안에서의 송신도 포함하나 전송은 제외한다 · 공중에게 공개한다는 것은 불특정 다수인이 모인 장소에서 공개하거나, 같은 시간·장소에 있지 않더라도 불특정 또는 다수인에게 전자장치 등으로 전파·통신하여 공개하는 것을 뜻한다"],["공중송신","저작물 등을 공중이 수신하거나 접근하게 할 목적으로 무선 또는 유선통신의 방법에 의하여 송신하거나 이용에 제공하는 것으로, 방송·전송·디지털음성송신을 포함한다 · 방송은 공중이 동시에 수신하게 할 목적의 송신이고, 전송은 공중의 구성원이 개별적으로 선택한 시간과 장소에서 접근할 수 있게 저작물을 이용에 제공하는 것이다"],["전시권","미술저작물·건축저작물·사진저작물에 한하여 인정되므로 그 밖의 저작물은 전시의 방법으로는 저작재산권이 침해되지 않는다"],["배포","저작물의 원본 또는 복제물을 공중에게 대가를 받거나 받지 않고 양도 또는 대여하는 것이다 · 저작권자의 허락을 받아 판매 등으로 거래에 제공된 원본이나 복제물에는 더 이상 배포권이 인정되지 않으므로, 산 책을 되파는 것은 배포권 침해가 아니다 · 최초판매의 원칙에도 불구하고 저작자는 상업적 목적으로 공표된 음반이나 프로그램을 영리를 목적으로 대여할 권리를 가진다"],["2차적저작물작성권","저작자는 자기 저작물을 원저작물로 하는 2차적저작물을 작성하여 이용할 권리를 가지며, 동의를 얻어 만든 2차적저작물의 저작자는 원저작자의 권리를 해하지 않는 범위에서 그 2차적저작물에 대한 저작권을 갖는다"]]}],"102":[{"t":"table","title":"저작재산권 존속기간","head":["구분","내용"],"rows":[["원칙","저작재산권은 특별한 규정이 없으면 저작자가 생존하는 동안과 사망한 후 70년간 존속한다"],["저작인격권","저작인격권은 저작자의 생존기간 동안 존속하며, 사후의 인격적 이익 보호에 관해서는 별도 규정을 두고 있다"],["공표한 때부터 70년","무명·이명저작물, 업무상저작물, 영상저작물, 프로그램저작물의 저작재산권은 공표된 때부터 70년간 존속한다"],["실명이 밝혀진 경우","무명·이명저작물이라도 공표 후 70년 이내에 저작자의 실명 또는 널리 알려진 이명이 밝혀지거나 실명등록이 있으면 저작자 사후 70년의 보호기간이 적용된다"],["공표되지 않은 경우","업무상저작물과 영상저작물이 창작한 때부터 50년 이내에 공표되지 않으면 창작한 때부터 70년간 존속한다"],["기산","저작재산권의 보호기간은 저작자가 사망하거나 저작물을 창작 또는 공표한 다음 해부터 기산한다"]]}],"103":[{"t":"table","title":"공공 목적의 제한","head":["구분","내용"],"rows":[["제한 사유","저작재산권은 저작물의 공정한 이용을 위해 공익상 필요, 다른 권리와의 조정, 사회관행 등의 사유가 있는 경우 제한되며, 이 규정은 대부분 저작인접권의 제한에도 준용된다"],["재판·수사·내부자료","재판 또는 수사를 위해 필요하거나 입법·행정 목적의 내부자료로 필요한 경우에는 그 한도 안에서 저작물을 복제할 수 있다"],["정치적 연설","공개적으로 행한 정치적 연설과 법정·국회·지방의회에서의 공개 진술은 어떤 방법으로도 이용할 수 있으나, 같은 저작자의 연설이나 진술을 편집하여 이용하는 경우는 제외된다"],["공공저작물","국가나 지방자치단체가 업무상 작성하여 공표한 저작물이나 저작재산권 전부를 계약으로 보유한 저작물은 원칙적으로 허락 없이 이용할 수 있다 · 국가안전보장 관련 정보, 개인의 사생활·사업상 비밀, 다른 법률로 공개가 제한된 정보를 포함하는 공공저작물은 허락 없이 이용할 수 없다"]]},{"t":"table","title":"교육·보도·인용의 제한","head":["구분","내용"],"rows":[["교과용도서","고등학교 및 이에 준하는 학교 이하의 교육 목적을 위해 필요한 교과용도서에는 공표된 저작물을 게재할 수 있다"],["수업 목적","법이 정한 학교·교육기관이 수업 목적으로 이용할 때는 공표된 저작물의 일부분을 복제·배포·공연·전시·공중송신할 수 있으며, 부득이한 경우에는 전부도 가능하다"],["보상금","학교교육 목적으로 저작물을 이용하는 자는 고시된 기준의 보상금을 저작재산권자에게 지급해야 하지만, 고등학교 및 이에 준하는 학교 이하에서 복제 등을 하는 경우에는 보상금을 지급하지 않는다"],["시사보도","방송·신문 등으로 시사보도를 하는 과정에서 보이거나 들리는 저작물은 보도를 위한 정당한 범위 안에서 복제·배포·공연 또는 공중송신할 수 있다"],["시사적 기사","신문이나 뉴스통신에 실린 정치·경제·사회·문화·종교에 관한 시사적 기사나 논설은 이용을 금지하는 표시가 없으면 다른 언론기관이 복제·배포·방송할 수 있다"],["인용","공표된 저작물은 보도·비평·교육·연구 등을 위해 정당한 범위 안에서 공정한 관행에 합치되게 인용할 수 있다 · 인용이 정당한 범위에 있다고 하려면 전체 중 인용물이 차지하는 비중이 현저히 적어야 한다"]]}],"104":[{"t":"table","title":"사적복제·도서관","head":["구분","내용"],"rows":[["영리를 목적으로 하지 않는 공연","영리를 목적으로 하지 않고 청중이나 관중으로부터 대가를 받지 않는 경우에는 실연자에게 일반적인 보수를 지급하지 않는 한 공표된 저작물을 공연하거나 방송할 수 있다"],["사적이용을 위한 복제","공표된 저작물을 영리 목적 없이 개인적으로 이용하거나 가정 및 이에 준하는 한정된 범위 안에서 이용하는 경우 그 이용자는 이를 복제할 수 있다 · 공중의 사용에 제공하기 위해 설치된 복사기기·스캐너 등 복제기기에 의한 복제에는 사적이용을 위한 복제 규정이 적용되지 않는다"],["도서관등의 복제","조사·연구 목적 이용자의 요구에 따라 도서등의 일부분 복제물을 1인 1부에 한해 제공하거나, 자체보존이 필요한 경우 등에 보관 중인 도서등을 복제할 수 있다 · 이용자 요구에 따른 일부 복제와 다른 도서관등의 요구에 따른 보존용 복제는 디지털 형태로 할 수 없고, 디지털 복제는 자체보존에 필요한 경우에만 가능하다"],["열람","도서관등이 컴퓨터로 열람하게 할 때 동시에 열람할 수 있는 이용자의 수는 그 도서관등이 보관하거나 이용허락을 받은 도서등의 부수를 초과할 수 없다 · 판매용으로 발행된 도서등은 발행일부터 5년이 지나지 않으면 도서관등이 다른 도서관등으로 전송하여 열람하게 할 수 없다"]]},{"t":"table","title":"시험·장애인","head":["구분","내용"],"rows":[["시험문제","학교의 입학시험이나 학식·기능에 관한 시험 또는 검정을 위해 필요한 경우 정당한 범위에서 공표된 저작물을 복제·배포·공중송신할 수 있으나, 영리 목적인 경우는 제외된다"],["시각·청각장애인 등","누구든지 공표된 저작물을 시각장애인 등을 위해 점자로 변환하여 복제·배포할 수 있고, 청각장애인 등을 위해 한국수어로 변환할 수 있다"],["장애인 복리증진 시설","장애인 복리증진을 목적으로 하는 대통령령 지정 시설은 영리 목적 없이 이들의 이용에 제공하기 위해 저작물을 대체자료로 변환하여 복제·배포·공연 또는 공중송신할 수 있다"]]}],"105":[{"t":"table","title":"방송·미술·컴퓨터 이용의 제한","head":["구분","내용"],"rows":[["방송사업자의 일시적 녹음·녹화","저작물을 방송할 권한이 있는 방송사업자는 자기 방송을 위해 자체 수단으로 저작물을 일시적으로 녹음·녹화할 수 있으며, 그 녹음물·녹화물은 녹음·녹화일부터 1년을 초과하여 보존할 수 없다 · 기록 자료로서 대통령령으로 정하는 장소에 보존되는 경우에는 1년을 넘겨 보존할 수 있다"],["미술저작물등의 전시","미술저작물등 원본의 소유자나 그의 동의를 얻은 자는 원본으로 전시할 수 있으나, 가로·공원·건축물 외벽 등 개방된 장소에 항시 전시하는 경우에는 이 규정이 적용되지 않는다"],["개방된 장소의 미술저작물","개방된 장소에 항시 전시된 미술저작물 등은 어떠한 방법으로든 복제하여 이용할 수 있으나, 건축물을 건축물로 복제하거나 조각·회화를 조각·회화로 복제하거나 판매 목적으로 복제하는 경우는 제외된다"],["목록 형태의 책자","미술저작물 등을 전시하거나 원본을 판매하려는 자는 해설이나 소개를 목적으로 하는 목록 형태의 책자에 이를 복제·배포할 수 있으나, 위탁에 의한 초상화는 위탁자의 동의가 없으면 이용할 수 없다"],["컴퓨터에서의 일시적 복제","컴퓨터에서 저작물을 이용할 때 원활하고 효율적인 정보처리를 위해 필요한 범위 안에서 그 컴퓨터에 일시적으로 복제할 수 있으나, 저작물의 이용 자체가 저작권을 침해하는 경우에는 그렇지 않다"],["부수적 복제","사진촬영·녹음·녹화 과정에서 보이거나 들리는 저작물이 주된 대상에 부수적으로 포함된 경우 이를 복제·배포·공연·전시·공중송신할 수 있으나, 저작재산권자의 이익을 부당하게 해치는 경우는 제외된다"]]},{"t":"table","title":"문화시설·공정이용","head":["구분","내용"],"rows":[["문화시설","상당한 조사를 하여도 저작재산권자나 그 거소를 알 수 없는 경우 보관 자료를 수집·정리·보존하여 공중에게 제공하기 위한 비영리 목적으로 저작물을 이용할 수 있다 · 저작재산권자는 문화시설의 이용에 대해 저작물의 이용 중단을 요구할 수 있고, 요구를 받은 문화시설은 지체 없이 이용을 중단해야 한다"],["공정이용","저작물의 일반적 이용 방법과 충돌하지 않고 저작자의 정당한 이익을 부당하게 해치지 않는 경우에는 저작물을 이용할 수 있다 · 이용의 목적 및 성격, 저작물의 종류 및 용도, 이용된 부분이 차지하는 비중과 중요성, 이용이 저작물의 현재·잠재적 시장이나 가치에 미치는 영향을 고려해 판단한다"],["번역·편곡·개작","저작권법은 저작재산권 제한사유에 따라 번역만 허용하는 경우와 번역뿐 아니라 편곡·개작까지 허용하는 경우를 나누어 규정한다"]]}],"106":[{"t":"table","title":"저작재산권 양도와 기증","head":["구분","내용"],"rows":[["양도","저작재산권은 전부 또는 일부를 양도할 수 있어, 복제권·공중송신권·공연권을 각각 다른 사람에게 분리하여 양도하거나 시간·장소를 한정해 양도할 수도 있다"],["2차적저작물작성권","저작재산권 전부를 양도하면서 특약이 없으면 2차적저작물을 작성하여 이용할 권리는 포함되지 않은 것으로 추정한다 · 컴퓨터프로그램은 특약이 없으면 2차적저작물작성권도 함께 양도된 것으로 추정한다"],["기증","저작재산권자등은 자신의 권리를 문화체육관광부장관에게 기증할 수 있으며, 장관은 기증된 권리를 공정하게 관리할 단체를 지정할 수 있다 · 기증받아 지정된 단체는 영리를 목적으로 또는 해당 저작재산권자등의 의사에 반하여 저작물등을 이용할 수 없다"]]}],"107":[{"t":"table","title":"이용허락과 법정허락","head":["구분","내용"],"rows":[["저작물을 이용할 수 있는 경우","저작권자가 아닌 자가 저작물을 이용할 수 있는 경우는 계약에 의한 경우, 법률에 의한 법정허락의 경우, 정부기관 등의 허락을 받는 강제허락의 경우로 나눌 수 있다"],["이용허락","이용허락을 받은 자는 허락받은 이용 방법 및 조건의 범위 안에서 저작물을 이용할 수 있고, 그 권리는 저작재산권자의 동의 없이 제3자에게 양도할 수 없다"],["법정허락","법정허락 사유가 있으면 누구든지 문화체육관광부장관의 승인을 얻고 장관이 정한 기준의 보상금을 지급하거나 공탁한 후 저작물을 이용할 수 있다"],["법정허락 사유","상당한 노력을 기울였어도 공표된 저작물의 저작재산권자나 그 거소를 알 수 없어 이용허락을 받을 수 없는 경우 · 공표된 저작물을 공익을 위해 방송하려는 방송사업자가 저작재산권자와 협의하였으나 협의가 성립되지 않는 경우 · 상업용 음반이 우리나라에서 처음 판매된 후 3년이 지난 경우 그 음반에 녹음된 저작물로 다른 음반을 제작하려는 자가 협의하였으나 성립되지 않는 경우"],["준용","저작물의 법정허락에 관한 규정은 실연·음반 및 방송의 이용과 관련하여 준용된다 · 법정허락된 저작물이 다시 법정허락의 대상이 되는 때에는 상당한 노력의 절차를 생략할 수 있다"],["공탁","법정허락은 이용자의 보상금 공탁을 전제로 하며, 저작재산권자의 주소가 국내에 있으면 그 주소지의 관할 공탁소에 공탁한다"]]}],"108":[{"t":"table","title":"배타적발행권","head":["구분","내용"],"rows":[["설정","저작물을 발행·복제·전송할 권리를 가진 자는 그 저작물을 발행등에 이용하려는 자에게 배타적 권리인 배타적발행권을 설정할 수 있다 · 저작재산권자는 발행등의 방법 및 조건이 중첩되지 않는 범위 안에서 새로운 배타적발행권을 설정할 수 있다"],["도입","배타적발행권은 한미 FTA 이행을 위해 2011년 개정으로 신설되었다"],["출판권과의 관계","사실상 배타적발행권과 출판권은 같은 내용으로, 종이책을 출판하려면 출판권을, 전자책을 내려면 배타적발행권을 획득해야 한다"],["질권","저작재산권자는 그 저작물의 복제권·배포권·전송권을 목적으로 하는 질권이 설정되어 있으면 질권자의 허락이 있어야 배타적발행권을 설정할 수 있다"],["배타적발행권자의 의무","특약이 없으면 복제에 필요한 원고 또는 이에 상응하는 물건을 받은 날부터 9개월 이내에 발행등의 방법으로 저작물을 이용해야 한다 · 특약이 없으면 관행에 따라 저작물을 계속 발행등의 방법으로 이용해야 하고, 각 복제물에 저작재산권자의 표지를 해야 한다 · 저작물을 발행등의 방법으로 다시 이용하려는 때에 특약이 없으면 그때마다 미리 저작자에게 그 사실을 알려야 한다"],["양도·질권","배타적발행권자는 저작재산권자의 동의 없이 배타적발행권을 양도하거나 질권의 목적으로 할 수 없다"],["저작자의 수정","배타적발행권자가 저작물을 다시 발행등의 방법으로 이용하는 경우 저작자는 정당한 범위 안에서 그 저작물의 내용을 수정하거나 증감할 수 있다"],["존속기간","설정행위에 특약이 없으면 맨 처음 발행등을 한 날부터 3년간 존속하며, 저작물의 영상화를 위해 설정하는 경우에는 5년이다"],["저작자 사망 시","저작재산권자는 배타적발행권 존속기간 중 저작자가 사망하면 저작자를 위해 그 저작물을 전집 그 밖의 편집물에 수록하거나 일부를 분리하여 따로 발행등의 방법으로 이용할 수 있다"]]}],"109":[{"t":"table","title":"출판권과 질권","head":["구분","내용"],"rows":[["출판권 설정","저작물을 복제·배포할 권리를 가진 복제권자는 그 저작물을 인쇄 등의 방법으로 문서 또는 도화로 발행하려는 자에게 출판권을 설정할 수 있다"],["출판권자","출판권을 설정받은 출판권자는 설정행위에서 정한 바에 따라 그 저작물을 원작 그대로 출판할 권리를 가진다 · 배타적발행권에 관한 대부분의 규정은 출판권에 준용된다"],["질권","저작재산권을 목적으로 한 질권은 저작권 양도나 이용의 대가로 권리자가 받을 금전에도 미치되, 지급·인도 전에 압류해야 한다 · 질권의 목적이 된 저작재산권은 설정행위에 특약이 없으면 저작재산권자가 행사한다"]]},{"t":"table","title":"공동저작물의 저작재산권","head":["구분","내용"],"rows":[["행사","공동저작물의 저작재산권은 저작재산권자 전원의 합의가 있어야 행사할 수 있다"],["지분 양도","공동저작물의 저작재산권자는 다른 저작재산권자의 동의가 없으면 자기 지분을 양도할 수 없다"],["합의 방해","공동저작물의 저작재산권자는 신의에 반하여 합의의 성립을 방해하거나 동의를 거부할 수 없다"],["이용 이익","공동저작물의 이용 이익은 특약이 없으면 창작에 이바지한 정도에 따라 배분하며, 정도가 불명확하면 균등한 것으로 추정한다"],["지분 포기·상속인 없는 사망","공동저작물의 저작재산권자가 지분을 포기하거나 상속인 없이 사망하면 그 지분은 다른 저작재산권자에게 지분 비율에 따라 배분된다"]]}],"110":[{"t":"table","title":"저작권 등록","head":["구분","내용"],"rows":[["등록의 성격","저작권은 무방식주의이므로 등록은 권리 발생 요건이 아니며, 저작재산권 이전 등에서도 대항요건일 뿐이다"],["신청","저작권 등록은 촉탁 또는 신청으로 하며, 신청할 때는 등록신청서를 문화체육관광부장관에게 제출한다 · 현재 저작권 등록 업무는 저작권법에 따라 한국저작권위원회에 위탁되어 운영되고 있다"],["등록 사항","저작권자는 저작자의 실명·이명, 저작물의 제호·종류·창작연월일, 공표 여부 등을 등록할 수 있다"],["등록의 효과","저작자로 실명이 등록된 자는 그 등록저작물의 저작자로 추정된다 · 저작물을 창작한 때부터 1년이 지난 후 창작연월일을 등록한 경우에는 등록된 연월일에 창작된 것으로 추정하지 않는다"],["대항","저작재산권의 양도나 처분제한은 등록하지 않으면 제3자에게 대항할 수 없다 · 저작권 양도인의 배임행위에 적극 가담한 이중양수인은 선의의 제3자가 아니므로 원양수인이 이전등록 말소를 청구할 수 있다"],["침해","등록된 저작권을 침해한 자는 그 침해행위에 과실이 있는 것으로 추정된다 · 법정손해배상을 청구하려면 침해행위가 일어나기 전에 해당 저작물등이 등록되어 있어야 한다"]]}],"111":[{"t":"table","title":"저작권 인증","head":["구분","내용"],"rows":[["인증제도","저작권 인증제도는 2006년 저작권법 개정으로 도입되어 저작물등의 거래 안전과 신뢰 보호를 꾀한다"],["인증기관","문화체육관광부장관이 저작권 인증기관을 지정할 수 있으며, 한국저작권위원회 등이 이를 수행하고 있다"]]},{"t":"vs","title":"저작권위탁관리업","cols":[{"name":"저작권신탁관리업","items":["권리자로부터 권리를 신탁받아 이를 지속적으로 관리하는 업을 말한다","문화체육관광부장관의 허가를 받아야 한다","저작물등의 권리자로 구성된 단체이고 영리를 목적으로 하지 않아야 한다"]},{"name":"저작권대리중개업","items":["권리자를 위해 그 권리의 이용에 관한 대리 또는 중개행위를 하는 업을 말한다","문화체육관광부장관에게 신고하면 된다"]}]},{"t":"table","title":"신탁관리업자","head":["구분","내용"],"rows":[["위탁관리업","저작권위탁관리업은 저작권신탁관리업과 저작권대리중개업으로 나뉜다"],["사용료","저작권신탁관리업자가 이용자로부터 받는 사용료의 요율·금액은 문화체육관광부장관의 승인을 받아 정한다"],["목록 공개","저작권신탁관리업자는 관리 저작물등의 목록과 이용계약 체결에 필요한 정보를 분기별로 주된 사무소에 비치하고 홈페이지로 공개해야 한다"],["통합 징수","문화체육관광부장관은 이용자 편의를 위해 필요한 경우 신탁관리업자 및 보상금수령단체에 사용료·보상금의 통합 징수를 요구할 수 있다"],["징계 요구","신탁관리업자의 대표자·임원이 직무와 관련해 벌금형 이상이 확정되거나 회계부정으로 권리자에게 손해를 끼치면, 장관은 그 징계를 요구할 수 있다"]]}],"112":[{"t":"table","title":"저작인접권","head":["구분","내용"],"rows":[["저작인접권","실연자·음반제작자·방송사업자는 직접적 창작자는 아니지만 저작물의 전달자로서 저작권에 유사한 저작인접권을 인정받는다"],["국제조약","저작인접권에 관한 국제조약에는 음반보호조약(제네바조약), 인접권조약(로마조약), WTO/TRIPs 등이 있다"],["실연자","저작물을 연기·무용·연주·가창 등으로 표현하는 자 외에 실연을 지휘·연출·감독하는 자도 포함된다"],["인격적 권리","실연자에게는 인격적 권리와 재산적 권리가 모두 인정되나, 음반제작자와 방송사업자에게는 인격적 권리가 인정되지 않는다 · 실연자는 성명표시권과 동일성유지권에 유사한 권리를 가지며 이는 실연자 일신에 전속한다 · 실연의 성질이나 이용의 목적·형태에 비추어 부득이하다고 인정되는 경우에는 실연자의 동일성유지권이 제한된다"]]},{"t":"table","title":"실연자·음반제작자의 권리","head":["구분","내용"],"rows":[["실연자의 재산적 권리","실연자는 복제권, 배포권, 대여권, 공연권, 방송권 및 전송권을 가진다"],["공동 실연자","2명 이상이 공동으로 합창·합주·연극 등을 실연한 경우 실연자의 권리는 공동 실연자가 선출한 대표자가 행사한다 · 대표자 선출이 없으면 지휘자 또는 연출자 등이 실연자의 권리를 행사한다 · 독창 또는 독주가 함께 실연된 경우에는 독창자 또는 독주자의 동의를 얻어야 한다"],["보상금","상업용 음반 사용 방송에 대한 보상금 지급 의무는 실연자가 외국인인 경우 상호주의에 따라 부담한다"],["음반제작자","음반제작자는 그의 음반에 대하여 복제권, 배포권, 대여권 및 전송권을 가진다"]]}],"113":[{"t":"table","title":"데이터베이스제작자 보호","head":["구분","내용"],"rows":[["데이터베이스","소재를 체계적으로 배열·구성한 편집물로서 개별적으로 소재에 접근하거나 검색할 수 있게 한 것이다"],["별도 보호","현행 저작권법은 창작성이 없는 데이터베이스라도 투자를 보호하기 위해 데이터베이스제작자를 별도로 보호한다"],["보호 대상","대한민국 국민의 데이터베이스와 조약에 따라 보호되는 외국인의 데이터베이스는 저작권법의 보호를 받는다 · 외국에서 대한민국 국민의 데이터베이스를 보호하지 않으면 그 외국인의 데이터베이스에 대한 보호를 제한할 수 있다"],["적용 대상이 아닌 것","데이터베이스의 제작·갱신·운영에 이용되는 컴퓨터프로그램은 데이터베이스제작자 보호 규정의 적용 대상이 아니다"]]},{"t":"table","title":"데이터베이스제작자의 권리","head":["구분","내용"],"rows":[["권리","데이터베이스제작자는 데이터베이스의 전부 또는 상당한 부분을 복제·배포·방송 또는 전송할 권리를 가진다"],["상당한 부분","개별 소재의 복제라도 반복적·체계적으로 해서 데이터베이스의 일반적 이용과 충돌하거나 제작자의 이익을 해치면 상당한 부분의 복제로 본다"],["예외","비영리적인 교육·학술·연구 목적이나 시사보도 목적이라면 누구든지 데이터베이스의 전부 또는 상당한 부분을 복제·배포·방송·전송할 수 있다"],["존속기간","데이터베이스제작자의 권리는 제작을 완료한 때부터 발생하고 그 다음 해부터 기산하여 5년간 존속한다 · 데이터베이스 갱신을 위해 상당한 투자가 이루어진 경우 그 부분의 권리는 갱신한 때부터 발생하여 그 다음 해부터 5년간 존속한다"]]}],"114":[{"t":"table","title":"온라인서비스제공자의 책임 제한","head":["유형","내용"],"rows":[["책임 제한의 취지","저작권법은 온라인서비스제공자가 의무를 이행한 경우 간접적 침해에 대한 책임을 면제해 온라인 상거래와 저작권 보호의 균형을 꾀한다"],["유형","온라인서비스제공자의 책임 제한 유형은 도관, 캐싱, 호스팅, 정보검색서비스 네 가지로 구분된다"],["호스팅","복제·전송자의 요청에 따라 저작물등을 온라인서비스제공자의 컴퓨터에 저장하는 행위를 말한다"],["캐싱","후속 이용자들이 효율적으로 접근하도록 송신된 저작물등을 자동적·중개적·일시적으로 저장하는 행위이다"],["정보검색서비스","정보검색도구를 통해 이용자에게 정보통신망상 저작물등의 위치를 알게 하거나 연결하는 행위이다"]]},{"t":"table","title":"중단 요구와 정보 제공","head":["구분","내용"],"rows":[["모니터링 의무","온라인서비스제공자는 자기 서비스 안에서 침해행위가 일어나는지 모니터링하거나 적극적으로 조사할 의무를 지지 않는다"],["중단 요구","권리가 침해된다고 주장하는 자는 그 사실을 소명하여 온라인서비스제공자에게 해당 저작물등의 복제·전송 중단을 요구할 수 있다"],["면책","온라인서비스제공자가 중단·재개 요구를 받을 자를 지정해 공지하고 복제·전송을 중단하거나 재개한 경우 책임이 면제된다 · 침해 사실을 안 때에는 그때부터 중단 요구를 받기 전까지 발생한 책임은 면제되지 않는다"],["정보 제공 명령","권리주장자는 소송 제기를 위해 온라인서비스제공자에게 복제·전송자의 정보 제공을 청구했다가 거절되면 문화체육관광부장관에게 제공 명령을 청구할 수 있다 · 장관의 명령을 받은 온라인서비스제공자는 명령을 받은 날부터 7일 이내에 복제·전송자의 정보를 장관에게 제출해야 한다 · 장관은 정보 제공 명령에 앞서 저작권보호심의위원회의 심의를 거친다"]]}],"115":[{"t":"table","title":"기술적 보호조치","head":["구분","내용"],"rows":[["기술적 보호조치","저작물등에 대한 접근 또는 권리 침해를 효과적으로 방지하거나 억제하기 위해 권리자 등이 적용하는 기술적 조치이다"],["무력화 금지","누구든지 정당한 권한 없이 고의 또는 과실로 기술적 보호조치를 제거·변경·우회하는 방법으로 무력화해서는 안 된다"],["예외","정당한 권한을 가지고 프로그램을 사용하는 자가 다른 프로그램과의 호환을 위해 프로그램코드 역분석을 하는 경우에는 무력화 금지가 적용되지 않는다"],["장치·제품","기술적 보호조치의 무력화를 주된 목적으로 하는 장치·제품·부품을 제조·수입·배포·판매·대여하는 행위도 금지된다"]]},{"t":"table","title":"권리관리정보","head":["구분","내용"],"rows":[["권리관리정보","저작물등을 식별하는 정보, 권리자를 식별하는 정보, 이용 방법·조건에 관한 정보 중 어느 하나에 해당하는 정보이다"],["금지 행위","권리관리정보를 고의로 제거·변경하거나 거짓으로 부가하는 행위, 제거된 사실을 알면서 해당 저작물을 배포·공연·공중송신하는 행위는 금지된다"],["그 밖의 금지 행위","암호화된 방송 신호의 무력화, 라벨 위조, 영상저작물 녹화, 방송 전 신호의 송신 등도 저작권법이 금지하는 행위이다"]]}],"116":[{"t":"table","title":"영상저작물 특례","head":["구분","내용"],"rows":[["영상저작물","연속적인 영상이 수록된 창작물로서 기계 또는 전자장치로 재생하여 볼 수 있거나 보고 들을 수 있는 것이며 음의 수반 여부는 묻지 않는다"],["영상화 허락","저작재산권자가 영상화를 허락하면 특약이 없는 한 각색, 공개상영, 방송, 전송, 복제·배포 등의 권리까지 허락한 것으로 추정한다 · 영상화를 허락한 날부터 5년이 지나면 특약이 없는 한 그 저작물을 다른 영상저작물로 영상화하도록 허락할 수 있다"],["영상제작자에게 협력한 자","영상제작자에게 협력하기로 약정한 자가 영상저작물에 저작권을 취득한 경우 특약이 없으면 이용에 필요한 권리는 영상제작자에게 양도된 것으로 추정한다 · 영상저작물 제작에 이용된 소설·각본·미술저작물·음악저작물 등의 저작재산권은 영상제작자에게 양도된 것으로 추정하는 규정의 영향을 받지 않는다"],["실연자","영상제작에 협력하기로 약정한 실연자의 복제권·배포권·방송권·전송권은 특약이 없으면 영상제작자가 양도받은 것으로 추정한다"],["양도받은 권리","영상제작자가 양도받은 권리는 영상저작물을 복제·배포·공개상영·방송·전송 등으로 이용할 권리이며, 이를 양도하거나 질권의 목적으로 할 수 있다"]]}],"117":[{"t":"table","title":"컴퓨터프로그램 특례","head":["구분","내용"],"rows":[["컴퓨터프로그램저작물","특정 결과를 얻기 위해 컴퓨터 등 정보처리능력을 가진 장치에서 직접 또는 간접으로 사용되는 일련의 지시·명령으로 표현된 창작물이다"],["보호 규정이 적용되지 않는 것","프로그램 언어, 규약, 해법에 대해서는 컴퓨터프로그램 보호 규정이 적용되지 않는다 · 규약은 특정한 프로그램에서 프로그램 언어의 용법에 관한 특별한 약속을 말한다"],["법정 사유의 복제","재판·수사를 위한 복제나 가정 같은 한정된 장소에서의 비영리 개인 목적 복제 등 법정 사유에는 필요한 범위에서 공표된 프로그램을 복제·배포할 수 있다 · 프로그램의 종류·용도, 복제 부분의 비중, 복제 부수 등에 비추어 저작재산권자의 이익을 부당하게 해치면 법정 사유의 복제도 허용되지 않는다"],["일시적 복제","컴퓨터의 유지·보수를 위해 이용하는 과정에서 정당하게 취득한 프로그램을 일시적으로 복제할 수 있다"],["역분석","정당한 이용자는 호환에 필요한 정보를 쉽게 얻을 수 없고 획득이 불가피하면 호환에 필요한 부분에 한해 허락 없이 프로그램코드역분석을 할 수 있다"],["백업 복제","프로그램 복제물을 정당하게 소지·이용하는 자는 멸실·훼손·변질에 대비하여 필요한 범위에서 그 복제물을 복제할 수 있다"]]}],"118":[{"t":"table","title":"침해 정지·예방청구","head":["구분","내용"],"rows":[["구제방법","저작권 침해에 대한 법률상 구제방법은 크게 민사상 구제와 형사상 구제로 나눌 수 있다"],["정지·예방 청구","저작권 등을 가진 자는 침해자에게 침해의 정지를 청구할 수 있고, 침해할 우려가 있는 자에게는 침해의 예방 또는 손해배상의 담보를 청구할 수 있다 · 권리자는 침해정지·예방을 청구하면서 침해행위로 만들어진 물건의 폐기나 그 밖의 필요한 조치를 청구할 수 있다"],["침해로 보는 행위","침해물건임을 알고 배포할 목적으로 소지하는 행위는 저작권 침해로 본다 · 프로그램 저작권을 침해하여 만들어진 복제물을 그 사실을 알면서 취득한 자가 업무상 이용하는 행위는 침해로 본다"]]}],"119":[{"t":"table","title":"손해배상","head":["구분","내용"],"rows":[["요건","저작권 침해로 손해배상을 청구하려면 침해자의 고의 또는 과실, 위법성, 손해 발생, 침해행위와 손해 사이의 인과관계가 있어야 한다"],["침해자의 이익","침해자가 침해행위로 이익을 얻은 때에는 그 이익의 액을 저작재산권자등이 받은 손해의 액으로 추정한다"],["통상 받을 수 있는 금액","저작재산권자등은 그 권리의 행사로 일반적으로 받을 수 있는 금액에 상응하는 액을 손해액으로 하여 배상을 청구할 수 있고, 실제 손해가 이를 초과하면 초과액도 청구할 수 있다"],["법정손해배상","침해된 각 저작물등마다 1천만 원 이하이며, 영리 목적으로 고의 침해한 경우에는 5천만 원 이하의 범위에서 청구할 수 있다 · 사실심의 변론이 종결되기 전까지 실제 손해액을 갈음하여 청구할 수 있다"],["상당한 손해액","법원은 손해 발생 사실은 인정되나 손해액을 산정하기 어려우면 변론의 취지와 증거조사 결과를 참작해 상당한 손해액을 인정할 수 있다"],["인격권 침해","저작자 또는 실연자는 저작인격권 또는 실연자의 인격권을 침해한 자에게 손해배상에 갈음하거나 손해배상과 함께 명예회복에 필요한 조치를 청구할 수 있다"]]},{"t":"table","title":"소송절차의 명령","head":["구분","내용"],"rows":[["정보제공명령","법원은 침해소송에서 당사자의 신청에 따라 침해행위나 불법복제물의 생산·유통에 관련된 자를 특정할 수 있는 정보를 다른 당사자에게 제공하도록 명할 수 있다"],["거부","영업비밀 또는 사생활을 보호하기 위한 경우 등 정당한 사유가 있으면 정보 제공을 거부할 수 있다 · 정당한 이유 없이 정보제공명령에 따르지 않으면 법원은 정보에 관한 상대방의 주장을 진실한 것으로 인정할 수 있다"],["비밀유지명령","법원은 영업비밀이 소송수행 외의 목적으로 사용·공개되면 당사자의 영업에 지장을 줄 우려가 있는 경우 당사자의 신청에 따라 비밀유지명령을 내릴 수 있다"]]}],"120":[{"t":"table","title":"침해죄와 벌칙","head":["처벌","내용"],"rows":[["5년 이하의 징역 또는 5천만 원 이하의 벌금","저작재산권을 복제·공연·공중송신·전시·배포·대여·2차적저작물 작성의 방법으로 침해한 자는 처벌할 수 있고 병과도 가능하다 · 법원의 비밀유지명령을 정당한 이유 없이 위반한 자도 처벌할 수 있다"],["3년 이하의 징역 또는 3천만 원 이하의 벌금","저작인격권 침해로 저작자의 명예를 훼손한 자와 저작권 등록을 거짓으로 한 자는 처벌할 수 있다 · 업으로 또는 영리를 목적으로 기술적 보호조치를 무력화하거나 권리관리정보 의무를 위반한 자도 처벌할 수 있다"],["1년 이하의 징역 또는 1천만 원 이하의 벌금","저작자 아닌 자를 저작자로 실명·이명을 표시해 저작물을 공표한 자는 처벌한다 · 허가를 받지 않고 저작권신탁관리업을 한 자도 처벌한다 · 자신에게 정당한 권리가 없음을 알면서 고의로 복제·전송의 중단 또는 재개 요구를 하여 온라인서비스제공자의 업무를 방해한 자도 처벌한다"],["500만 원 이하의 벌금","출처명시의무를 위반하여 출처를 명시하지 않은 자는 처벌한다 · 신고를 하지 않고 저작권대리중개업을 하거나 영업의 폐쇄명령을 받고도 계속 영업한 자도 처벌한다"],["미수범","영상저작물 녹화금지 위반은 미수범도 처벌한다"],["그 밖의 규정","저작권법에는 권리침해죄 외에도 몰수, 친고죄, 양벌규정, 과태료에 관한 규정이 있다"]]}],"121":[{"t":"table","title":"특허정보 조사의 목적","head":["구분","내용"],"rows":[["특허정보 조사","특허명세서의 권리정보와 기술정보를 바탕으로 신기술 개발, 권리획득 가능성 검토, 특허분쟁 대응 등을 위해 수행된다 · 특정 기술이나 아이디어에 대한 기존 특허정보를 찾고 수집하는 과정이다"],["주요 방법","서지사항 조사, 특정기술 조사, 특허성 조사, 유효성 조사, 침해 여부 조사 등이 활용된다"],["경쟁사·침해 확인","특허정보 조사를 통해 경쟁사의 보유 특허 분야나 특정 제품이 기존 특허를 침해하는지 여부도 확인할 수 있다"],["신기술 개발","기초자료 입수 목적에는 개발 흐름 파악, 연구개발 테마 선정, 중복연구·중복투자 방지, 문제 해결 아이디어 입수가 있다 · 선행기술 조사를 하면 중복연구와 중복투자를 막을 수 있다"],["특허출원 전","특허정보 조사를 하면 특허취득 가능성과 기술적 범위를 판단하고 무용한 특허출원을 지양할 수 있다"],["특허분쟁 대처","증거자료 입수 목적에는 자사 실시기술에 대한 공지기술 확보, 회피설계 가능 여부 파악, 특허권 소멸 여부 확인 등이 있다"]]}],"122":[{"t":"table","title":"서지·주제·특허성 조사","head":["조사","내용"],"rows":[["서지사항 조사","출원번호·공개번호·등록번호 등의 번호나 출원인·발명자 등의 인명정보를 이용해 특허공보의 서지사항을 중심으로 조사하는 것이다"],["번호를 이용한 조사","번호를 이용한 서지사항 조사는 심사청구 여부, 법적 상태, 패밀리특허를 확인할 때 쓰인다"],["인명정보를 이용한 조사","출원인이나 발명자의 인명정보를 이용한 조사는 경쟁사 또는 특정 발명자의 특허기술이나 개발동향을 파악할 때 수행한다"],["특정기술 조사","특정 기술 분야에 대한 개괄적 조사로 주제 조사라고도 하며, 기술개발 동향 파악과 새로운 연구개발 테마 발굴 등에 쓰인다"],["특허성 조사","특허출원 전에 신규성·진보성 등 특허요건을 갖추었는지 판단하기 위해 선행자료를 조사하는 것이다 · 특허성 조사로 출원 여부를 결정하거나 청구범위를 변경하면 등록 시 최대한 넓고 견고한 권리를 확보할 수 있다"]]}],"123":[{"t":"table","title":"유효성·침해·권리 조사","head":["조사","내용"],"rows":[["유효성(무효자료) 조사","특허권자의 권리주장에 대해 해당 특허를 무효화시킬 수 있는 선행자료를 조사하는 것이다 · 심사관이 인용하지 못한 새로운 선행자료를 찾으면 타인의 특허를 무효화하거나 매입하려는 특허가 유효한지 파악할 수 있다"],["침해 여부 조사","본인의 제품과 타인의 청구범위에 기재된 구성요소를 비교하여 특허침해 여부를 판단하며, 침해 시 회피설계 전략을 구사할 수 있다"],["계속 조사","한 가지 주제에 대해 일정 기간 주기적으로 조사하는 것으로 감시 조사라고도 한다 · 출원된 특허는 비공개기간이 있어 이후 공개되거나 등록될 수 있으므로 연구개발이나 제품 판매 중에도 계속 조사할 필요가 있다"],["권리 조사","등록특허의 진정한 권리자, 연차료 미납 등에 따른 권리소멸 여부, 양수·양도 관계, 만료특허 존재 여부를 조사할 때 수행한다"]]}],"124":[{"t":"table","title":"특허 DB 개요","head":["구분","내용"],"rows":[["특허검색 데이터베이스","무료·유료 서비스로 전 세계 특허정보를 제공하며 국가별 특허문헌 검색과 분석에 활용된다 · 국내에서는 KIPRIS를 통해 한국을 포함한 다양한 국가의 특허를 검색할 수 있다"],["무료 제공","특허제도는 발명을 공개함으로써 새로운 발명 창출의 동기를 유발하므로 각국 특허청은 특허정보를 무료로 제공한다"],["선택","특허검색 데이터베이스는 조사의 목적·범위, 시간과 비용, 기술 분야 등을 고려해 선택해야 한다"]]},{"t":"vs","title":"무료 DB와 유료 DB","cols":[{"name":"무료 특허 DB","items":["한국 KIPRIS, 미국 USPTO, 일본 J-PlatPat, 유럽 Espacenet, 중국 CNIPA, PCT 출원 PatentScope 등이 있다","WIPO가 제공하는 PatentScope는 PCT 국제출원 정보를 검색하는 무료 데이터베이스이다"]},{"name":"유료 특허 DB","items":["Derwent Innovation, 키워트, 윕스온, 위즈도메인은 기업이 제공하는 유료 특허 데이터베이스이다"]}]}],"125":[{"t":"table","title":"해외 특허 DB","head":["DB","내용"],"rows":[["미국 특허청","등록·공개특허 검색과 특허 양도, 파일 래퍼 조회가 가능하며 Patent Advanced Search로 키워드와 연산자를 이용해 검색한다"],["일본 J-PlatPat","일본에 출원된 특허·실용신안·디자인·상표·심판사항을 검색할 수 있고 특허 원문은 PDF 파일로 제공된다"],["Espacenet","유럽특허청이 제공하는 데이터베이스로 유럽 특허뿐 아니라 유럽 국가 이외의 특허도 검색할 수 있다 · CPC(협력특허분류) 조회와 CPC·키워드를 조합한 특허 검색이 가능하다"],["중국 CNIPA","중국 특허·실용신안·디자인 외에 주요 11개국과 기타 6개국의 특허도 검색할 수 있으나 로그인이 필요하다"],["PatentScope","세계지식재산기구(WIPO)가 제공하는 데이터베이스로 국제특허출원(PCT)을 비롯한 전 세계 특허문헌을 검색할 수 있다"]]}],"126":[{"t":"table","title":"키프리스","head":["구분","내용"],"rows":[["키프리스","한국특허정보원(KIPI)이 운영하는 특허정보검색 서비스로, 항목별 검색으로 초보자도 쉽게 이용할 수 있다"],["제공 정보","국내 특허·실용신안·디자인·상표·심판 정보와 미국·유럽·일본 등 27개국의 해외특허를 제공한다 · 27개국 해외특허를 검색할 수 있으며 미국·유럽·PCT·일본·중국 특허는 전문과 함께 한국어 번역 서비스를 지원한다"],["부가기능","마이폴더, 유사 검색식 보기, 온라인 다운로드, 검색식 저장 등의 부가기능을 제공한다"],["주요 서비스","한국 특허·실용신안·디자인·상표, 한국 심판 및 KPA(한국특허 영문 검색), 해외 특허·상표·디자인, 인터넷 기술공지, 아이디어공모전 등이 있다"]]},{"t":"table","title":"스마트 검색","head":["구분","내용"],"rows":[["행정상태","한국 특허·실용신안 스마트 검색에서는 특허 또는 실용신안을 선택하고 등록·공개·소멸 등 행정상태별로 검색할 수 있다"],["자유검색","특허 문서 전체를 대상으로 하는 전문 검색이므로 이것만 쓰면 불필요한 특허(노이즈)가 많이 검색될 수 있다"],["내용검색","발명의 명칭, 요약, 청구범위, 명세서, 일괄 항목으로 검색하며 명칭·요약·청구범위 중심으로 검색하면 효율적이다"],["분류·번호","IPC·CPC 코드로 특허분류 검색을, 출원번호·공개번호·등록번호로 번호정보 검색을 할 수 있다"],["기간·우선권","출원일자·공개일자·등록일자로 기간을 한정하거나 우선권주장 국가·번호·일자로 검색할 수 있다"],["존속기간 연장","특허권 존속기간은 원칙적으로 출원일부터 20년이나, 의약품·농약 발명처럼 허가 등으로 특허권을 행사하지 못한 경우 연장될 수 있고 이런 특허를 검색할 수 있다"],["국가연구개발사업","국가연구개발사업으로 출원된 특허는 연구부처, 주관기관, 연구사업 및 연구과제명으로 검색할 수 있다"]]}],"127":[{"t":"table","title":"키워드 선정","head":["구분","내용"],"rows":[["핵심 요소","키워드와 특허분류는 검색 효율성을 높이는 핵심 요소로, 키워드는 동의어·관련 기술로 확장하고 특허분류는 IPC·CPC 체계로 특허를 체계적으로 정리한다"],["키워드","특허정보 조사에서 특허기술을 가장 잘 나타내는 핵심적 기술용어 또는 어구이다"],["부적합한 키워드","적합하지 않은 키워드로 조사하면 찾으려는 문헌을 놓치거나 관련 없는 노이즈가 많이 포함되어 검토 시간이 늘어난다"],["선정 방법","특허명세서가 이미 있으면 청구범위와 발명의 상세한 설명을 참고해 키워드를 선정하고, 논문 등 비특허문헌만 있으면 기술적 요지나 발명의 목적을 중심으로 파악한다"],["표기 차이","동일한 기술도 약어(HEV), 형태적·묘사적 표현, 청구범위를 넓히려는 애매한 표현 등으로 다르게 표기될 수 있어 여러 표현을 함께 고려해야 한다 · 특정 출원인이 자신만의 키워드를 쓰거나 신기술로 새로 생긴 결합 키워드가 있을 수 있으므로 의미상의 차이도 유의해야 한다 · 외래어의 다양한 표기, 한국에서 잘 쓰이지 않는 한문 표현, 하이픈 문자 사용 등 표기상의 차이도 키워드 선정 시 유의해야 한다"],["선정과 확장","키워드는 명사를 중심으로 선정하고, 기술의 내용을 잘 나타내지 못하는 '사용', '기술' 같은 단어는 포함시키지 않는 것이 좋다 · 추출한 키워드는 동의어·유의어·외국어·외래어 및 관련 기술 키워드로 확장하며, 예컨대 변속기는 트랜스미션·파워트레인·CVT·DCT 등으로 넓힌다"]]}],"128":[{"t":"table","title":"특허분류","head":["구분","내용"],"rows":[["특허분류","발명의 기술적 특징에 따라 기술 분야를 분류한 것으로 선행기술 조사를 용이하게 하고 심사관의 담당분야를 정하는 기준이 된다"],["효율적인 경우","특허분류는 키워드만으로 검색하기 어렵거나 구조·배치 같은 기하학적 특징이 있는 특허를 조사하는 데 효율적이다"],["개정","특허분류는 기술의 진화에 따라 수시 또는 주기적으로 개정되므로 조사 시 개정 정보와 데이터베이스의 재분류 반영 여부를 확인해야 한다"],["복수 부여","특허문헌의 내용에 서로 다른 기술분류 카테고리가 있으면 하나 이상의 특허분류 코드가 부여될 수 있다"]]},{"t":"table","title":"IPC와 각국 분류","head":["구분","내용"],"rows":[["IPC","가장 대표적인 특허분류이나 개소가 7만여 개로 비교적 적어 각국은 자국 산업에 맞춘 독자적 분류체계를 사용하기도 한다 · 섹션, 클래스, 서브클래스, 메인그룹, 서브그룹의 계층 구조를 가진다"],["IPC의 연혁","국제적으로 통일된 분류체계에 대한 요구에 따라 스트라스부르크 협정으로 1968년 공포되고 1971년부터 사용되었다"],["일본","1996년 IPC를 더 세분화한 FI를 도입했고 1999년 FI의 일부를 다각적 관점으로 분류한 F-term을 도입했다"],["미국과 유럽","미국은 UPC, 유럽은 ECLA를 사용했으나 2013년 1월부터 USPTO와 EPO가 협력해 개발한 CPC를 사용한다"],["IPC의 섹션","알파벳 A부터 H까지 8개로 구분되며, A는 생활필수품, B는 처리조작·운수, C는 화학·야금이다 · D는 섬유·지류, E는 고정구조물, F는 기계공학·조명·가열·무기·폭파, G는 물리학, H는 전기를 나타낸다"],["예시","A63F 13/24에서 A는 섹션, 63은 클래스, F는 서브클래스, 13/00은 메인그룹, 13/24는 서브그룹에 해당한다"]]}],"129":[{"t":"table","title":"CPC 분류","head":["구분","내용"],"rows":[["CPC","IPC(7만여 개소)보다 세분화되어 26만여 개소를 가지며, 미국 특허청과 유럽 특허청의 주도로 2012년에 개발되었다 · 우리나라는 2015년 이후 신규출원에 CPC를 IPC와 함께 부여하고 있다"],["특징","IPC와 마찬가지로 5단계 계층 구조이나 부가정보로 부여하는 인덱싱 코드와 Y·Z 섹션이 추가된 점이 가장 큰 특징이다"],["Y 섹션","새로운 기술 발전의 일반적 구분표로, Y02는 기후 변화 완화·적응 기술, Y04는 정보·통신기술이다"],["Z 섹션","4차 산업혁명 관련 분류로, Z01은 ICT 기반 기술, Z03은 융합 서비스 분야, Z05는 산업 전발 기술이다"],["조회","CPC는 공식 홈페이지에서 조회할 수 있고 한국특허기술진흥원에서는 한국어로 CPC 조회를 제공한다"]]}],"130":[{"t":"table","title":"검색 연산자","head":["연산자","내용"],"rows":[["특허검색 연산자","검색어 간 상호관계를 지정하는 기호로, 수집한 키워드와 연산자를 조합해 효율적인 검색식을 작성한다"],["AND 연산","키프리스에서 '*'로 나타내며 두 개 이상의 키워드를 모두 포함한 특허를 검색하고, 띄어쓰기도 자동으로 '*'로 인식된다"],["OR 연산","키프리스에서 '+'로 나타내며 두 개 이상의 키워드 중 적어도 하나를 포함한 특허를 검색한다"],["NOT 연산","키프리스에서 '!*'로 나타내며 연산자 뒤의 키워드를 포함하지 않는 특허를 검색한다 · 찾으려는 특허가 누락될 가능성이 있으므로 사용에 유의해야 한다"],["NEAR 연산","키프리스에서 '^'로 나타내며 두 키워드가 인접한 특허문서를 검색하고, '^2', '^3'으로 키워드 간 거리를 넓힐 수 있다 · '컴퓨터 * 바이러스' 대신 근접연산자를 쓰면 바이오 분야 등 관련 없는 노이즈를 크게 줄일 수 있다"],["괄호","괄호로 묶인 연산자는 우선적으로 검색되므로 '엔진 * (자동차 + 차량)'은 자동차 또는 차량의 OR 연산을 먼저 수행한다"],["구문 검색","쌍따옴표를 이용해 여러 단어로 된 키워드를 하나의 단어처럼 정확히 일치하는 내용으로 검색한다"],["절단 검색","키프리스는 자동으로 절단 검색을 지원하므로 '변속'으로 검색하면 변속기·변속장치·변속방법 등도 함께 검색된다"]]}],"131":[{"t":"table","title":"조사 계획과 범위","head":["구분","내용"],"rows":[["조사 목적","특허정보 조사에서 가장 중요한 점은 조사 목적의 이해이며, 서지사항 조사인지 특정기술 조사인지 선행기술·무효자료 조사인지 명확히 해야 한다"],["기술 내용","기술 내용은 조사 대상 기술의 종래기술, 발명의 상세한 설명, 특허 청구범위를 통해 파악한다"],["조사범위","조사범위 결정에서는 조사할 국가, 조사 기간, 사용할 데이터베이스를 정한다"],["선행자료","특허출원 후 선행기술조사나 무효자료조사에서 선행자료는 공개일이 특허출원일과 동일하거나 빨라야 한다 · 국내 또는 조약 우선권주장, 분할출원, 변경출원의 경우 선행자료 조사기간은 원출원의 출원일을 기준으로 한다"]]}],"132":[{"t":"table","title":"검색식 작성","head":["구분","내용"],"rows":[["계층적 관계","기술의 계층적 관계를 고려해 검색식을 작성하며, 자동차>하이브리드>변속기라면 각 계층의 키워드를 OR로 묶고 계층 사이를 AND로 연결한다"],["검색 항목","기술 분야에 따라 발명의 명칭·요약·청구범위 중심으로 검색하거나 전문 검색으로 항목을 지정하고, 필요하면 키워드와 특허분류코드를 함께 쓴다"],["초록","발명의 내용을 파악하기 쉽도록 요약한 것으로 발명의 기술 분야, 구성, 목적 및 효과 등이 기재된다"],["청구범위","특허가 주장하는 발명의 권리범위로서 법적 효력을 갖는 부분이다"],["전문 검색","명칭·초록·청구범위로 한정한 검색에서 원하는 특허를 못 찾거나 상세한 설명까지 검색하려 할 때 전문 검색을 하며, 노이즈가 많으므로 인접 연산자와 구문 검색을 활용할 수 있다"]]},{"t":"flow","title":"키프리스 검색식 예시","steps":["키워드 검색","출원 기간 조건을 덧붙임","특허분류(IPC) 조건을 덧붙여 검색 건수를 줄여 나감","하이브리드 자동차 변속기 검색 예시에서는 IPC 코드를 B60(차량 일반)으로 한정하여 검색 범위를 좁힘"]},{"t":"table","title":"검색 필드","head":["구분","내용"],"rows":[["항목 한정","검색 항목을 발명의 명칭, 초록, 청구범위로 한정하면 키워드가 본문 곳곳에 흩어진 문헌이 제외되어 건수가 크게 줄어든다"],["CL, TL, AB 필드","검색식에서 각각 청구범위, 발명의 명칭, 초록에서 키워드를 찾도록 지정하는 데 쓰였다"]]}],"133":[{"t":"table","title":"특허정보 분석의 의의","head":["구분","내용"],"rows":[["특허정보 분석","수집한 특허 데이터를 바탕으로 기술 동향, 경쟁사 전략, 시장 흐름을 파악해 의사결정에 도움을 주는 활동이다"],["특허정보의 양","전 세계에서 해마다 약 100만 건 이상의 새로운 특허정보가 생겨나며 이는 전체 과학기술 정보의 약 40% 이상을 차지한다"],["취지","특허정보를 체계적으로 분석하는 일은 기술 공개를 통해 산업발전을 꾀한다는 특허제도의 본래 취지에 부합한다"],["활용","기업이나 연구기관은 특허정보 분석으로 미개척 분야나 잠재력 있는 분야를 발굴하고 연구개발 방향을 효율적으로 정할 수 있다"]]}],"134":[{"t":"vs","title":"특허정보 조사와 분석","cols":[{"name":"특허정보 조사","items":["기존 특허정보를 탐색하는 것이다","관련 특허 목록이나 문서 자체가 제공된다"]},{"name":"특허정보 분석","items":["수집된 정보를 해석해 결과를 도출하는 것이다","결과가 그래프·통계·보고서 형태로 나온다"]}]}],"135":[{"t":"table","title":"분석 목적과 기술정보 분석","head":["구분","내용"],"rows":[["기본 목적","특허정보 분석의 기본 목적은 자사뿐 아니라 경쟁사·타인의 특허까지 분석해 중복투자를 막고 분쟁 대비 능력을 높이는 것이다"],["분석 내용","방해가 되는 특허의 존재와 보유자, 기술 공백 여부, 출원인별 기술개발 주력 분야를 알 수 있도록 이루어져야 한다"],["기술정보 분석","특허기술 동향과 경쟁사 개발 동향을 파악하고 공백기술이나 유망기술 분야를 찾아 연구개발 테마를 정하는 데 쓰인다"],["기술개발 동향","기술개발 동향을 파악하는 분석 유형으로는 기술분포맵과 템페스트맵이 제시된다"],["핵심기술","핵심기술 파악을 위한 분석 유형으로는 기술발전도와 요지맵이 있다"],["틈새기술","틈새기술 파악에는 해결과제와 해결수단을 교차시키는 매트릭스맵을 활용해 연구테마 선정과 특허포트폴리오 강화에 쓴다"],["유망기술·파급효과","유망기술 파악에는 특허분류·키워드 상관을 보는 기술상관맵을, 기술파급효과 파악에는 인용관계를 보는 인용상관맵을 쓴다"],["포트폴리오 비교","자사와 타사의 특허 포트폴리오를 비교 분석하면 자사 특허망의 약점을 보완하고 타사 특허를 회피하거나 활용하는 전략을 세울 수 있다"]]}],"136":[{"t":"table","title":"권리정보 분석","head":["구분","내용"],"rows":[["권리정보 분석","특허권의 존속기간, 진정한 권리자, 실시권 설정 유무, 권리 범위와 회피 가능성을 파악하는 데 쓰인다"],["권리범위","특허권으로 설정되는 기술의 범위는 청구범위에 기재된 사항으로 한정되므로 권리범위는 청구범위를 분석해 파악한다"],["분석 유형","패밀리특허맵, 청구항별 요지맵, 권리존속기간 맵, 청구항 트리맵 등이 있다"],["활용","침해 여부 판단, 회피설계, 특허망 구축, 특허취득 가능성 파악, 특허가치 평가, 크로스 라이선싱 등에 활용된다"]]}],"137":[{"t":"table","title":"경영정보 분석","head":["구분","내용"],"rows":[["경영정보 분석","경영계획 수립에 활용되며 경쟁 기업의 기술정보와 연구개발 현황을 찾는 데 쓰인다"],["경쟁사 출원 건수","경쟁사의 출원 건수 비율을 분석하면 · 경쟁사의 기술보유 현황과 어떤 제품을 주력으로 개발하는지 알 수 있다"],["미래 경쟁업체","시장에 새로 진입할 가능성이 있는 업체는 자사에 위협요인이 될 수 있으므로 · 미래 경쟁업체에 대한 조사도 필요하다"],["뉴엔트리맵","기업별 사업 참여와 탈퇴 시기의 추이를 파악하며 기업협력이나 인수합병 판단에 활용한다"],["발명자 분포","주요 출원인별 발명자 수와 군집을 살펴 핵심 발명자 확보와 특허관리 방향 설정에 활용할 수 있다"]]}],"138":[{"t":"table","title":"R&D 단계별 특허정보 분석","head":["단계","내용"],"rows":[["연구기획단계","연구과제 선택의 객관적 타당성을 확인하고 한정된 기간 내 효과적인 연구가 가능한 미개척 분야를 발굴하는 자료가 된다 · 연구동향 파악과 연구주제 선정을 위한 파급분야 및 공백기술 발견에 쓰인다"],["연구개발단계","특허 명세서에 기재된 기존 기술의 문제점과 최신 기술 내용을 주기적으로 확인해 구체적인 수행방안을 세우고 문제 해결 아이디어를 얻는다 · 선행기술 조사를 통한 중복연구·중복투자 방지, 회피특허 출원, 자사 특허망 형성 등에 쓰인다"],["기술사업화단계","기술이전을 위해 기술시장 현황을 분석하고 기술이전 기업을 선정하는 참고자료로 활용된다 · 분쟁이 예상되는 특허의 무효자료 조사와 패밀리 특허의 국가별 권리범위 분석을 통해 분쟁에 대응한다"]]}],"139":[{"t":"flow","title":"특허정보 분석 절차","steps":["목적·대상 선정","기술분류체계 수립","검색식 작성","유효특허 추출과 기술분류","정량분석","핵심특허 선별과 정성분석"]},{"t":"table","title":"분석 계획과 대상 선정","head":["구분","내용"],"rows":[["분석 목적","분석의 첫 단계는 연구 동향 파악, 공백기술 도출, 침해 방지, 분쟁 대응 등 분석 목적을 명확히 정하는 것이다"],["분석 대상 분야","분석 대상 기술의 범위, 대상 국가, 대상 기간을 결정하고 이를 바탕으로 분석 대상 건수를 예측한다 · 분석 대상 건수가 많으면 거시적 통계 위주의 정량분석이 되어 특허성 조사나 침해분석 같은 심층분석은 적용하기 어려운 경우가 많다"],["기술분류표","분석 대상 기술을 요소기술과 세부기술로 세분화하면 분석 범위가 명확해지고 요소기술별·세부기술별 분석과 비교가 쉬워진다 · 분석 대상 기술의 근간을 이루는 주요 요소기술을 파악하고 이를 기준으로 세부기술 분야로 다시 나누는 방식이 일반적이다"],["요소기술의 구분","요소기술은 물품이면 구성 요소별로, 일련의 공정으로 이루어진 제조방법이면 제조 공정 단계별로 구분할 수 있다"]]}],"140":[{"t":"table","title":"검색·유효특허","head":["구분","내용"],"rows":[["검색식","특허 검색식은 주요 키워드와 검색 연산자를 결합해 만들고, 필요하면 IPC 등 분류를 함께 써서 노이즈를 줄이면서 누락도 최소화한다"],["유효특허 추출","검색식으로 모집단을 뽑으면 기술과 관련 없는 노이즈 데이터가 필연적으로 섞여 있으므로 이를 걸러내 유효특허를 추출한다 · 유효특허를 추출한 뒤에 기술분류표에 따라 각 유효특허를 기술 분야별로 분류한다"],["대표명화","출원인명이 여러 형태로 기재되어 있으면 하나의 대표 출원인명으로 통일하는 대표명화로 분석의 왜곡을 막는다"],["정량분석","출원 건수, 출원인 수, 특허분류 같은 서지적 데이터를 수량적으로 표시하는 통계분석이며 보통 연도·기술·상관관계에 의한 매트릭스맵으로 만든다 · 정량분석 결과는 분석필드 사이의 관계를 쉽게 보이도록 2차원보다 3차원으로 표현하며, 2~3개 그래프를 복합적으로 쓰기도 한다"]]},{"t":"table","title":"정량분석 그래프","head":["그래프","내용"],"rows":[["선 그래프","가장 단순하고 작성하기 쉬우며 시간에 따른 변화를 보는 데 적합하지만 한 시점의 비교에는 적합하지 않다"],["막대 그래프","한 시점에서의 양적 비교에 적합하지만 연속적인 변화를 보기에는 부적합하다"],["원 그래프","전체와 각 구성요소의 대비를 보기 쉽고 한곳에 모여 있어 공간 효율이 좋다"],["면적 그래프·버블 그래프","면적 그래프는 크기가 현격히 다른 것을 비교할 때 쓰고, 버블 그래프는 버블 크기로 세 번째 변수를 추가 표현한다"]]}],"141":[{"t":"table","title":"핵심특허 정성분석","head":["구분","내용"],"rows":[["핵심특허 선별","핵심특허는 특허당 인용·피인용 수, 패밀리 특허 규모, 특허영향 지수, 기술력 지수, 기술순환 지수, 과학연계 지수 등 정성적 지표로 선별할 수 있다 · 새로운 기술이나 기술적으로 독창적인 것처럼 기술에 따라 핵심특허 선별 기준을 다르게 둘 수도 있다"],["정성분석","핵심특허를 내용적으로 파악·분석하는 것으로 대상 기술의 특성이나 경쟁 기업의 출원인 특성을 고려해야 한다"],["기술발전도(전개도)","선별한 핵심특허를 연도별·기술별로 나열해 기술의 흐름을 시계열로 보여주는 것이다 · 기술의 흐름을 알 수 있도록 핵심특허의 출원번호, 등록번호, 출원인, 관련 도면을 표기한다 · 시계열적 발전도, 기술 분야별 발전도, 주요 출원인별 발전도, 인용관계를 이용한 발전도 등이 있다"]]},{"t":"table","title":"핵심특허 심층분석","head":["구분","내용"],"rows":[["분석 항목","핵심특허 심층분석에서는 서지사항, 발명의 목적, 구성 및 효과, 주요 기술 내용, 청구항 구성요소와 대표 도면을 분석한다"],["청구항 분석","심층분석에서는 청구항을 전제부, 구성요소, 종결부로 나누어 각 구성요소가 무엇이고 어떤 도면부호와 연결되는지 정리한다"],["참조사항","심층분석 표의 참조사항에는 패밀리 출원 국가, 인용(backward)과 피인용(forward) 정보, 청구항 수가 들어간다"],["검토 의견","심층분석의 검토 의견에는 해당 특허의 기술적 의의와 함께 권리범위, 선도기술 가능성, 매입·실시권 확보 같은 활용 방안에 대한 평가를 적는다"]]}],"142":[{"t":"table","title":"매트릭스 분석","head":["구분","내용"],"rows":[["포트폴리오 구축","특허정보 분석을 통한 포트폴리오 구축은 매트릭스 분석, 공백기술 도출, 핵심특허 도출로 이루어진다"],["매트릭스 분석","특허를 둘 이상의 항목으로 세분화해 해당하는 칸에 배치함으로써 유의미한 결과를 끌어내는 분석방법이다 · 자사 포트폴리오에서 보완할 분야와 자사·경쟁사 기술의 강점과 약점을 알 수 있다"],["해결과제/해결수단 매트릭스","특허의 요지와 청구범위 내용에서 어떤 문제를 어떤 수단으로 해결했는지 분석해 작성한다 · 매트릭스 설계에서 가장 중요한 단계는 해결하려는 과제를 명확히 하는 것이며, 해결과제를 정한 뒤에 해결수단을 그에 맞게 설정한다"]]},{"t":"table","title":"매트릭스의 종류","head":["매트릭스","내용"],"rows":[["발명자-기술 매트릭스","해당 기술 분야를 주도하는 발명자를 찾고 발명자들 사이의 상관관계를 분석하는 데 쓴다"],["출원인-기술 매트릭스","해당 기술 분야에서 특허를 많이 보유한 출원인과 세부 기술별로 출원활동이 활발한 출원인을 파악하게 해 준다"],["연도-기술 매트릭스","시간 흐름에 따른 기술 분야의 출원 흐름과 기술 중심이 어떤 방향으로 진화하는지를 분석하는 데 쓴다"],["연도-출원인 매트릭스","주요 출원인의 연도별 기술개발 추이를 파악해 경쟁자의 출원 및 개발 방향을 미리 예측하는 데 쓴다"],["국가-기술 매트릭스","기업이 진입하려는 주요 국가별 특허출원 현황과 세부 기술분류별 연구 수준을 파악하는 근거로 쓴다"]]}],"143":[{"t":"table","title":"공백기술","head":["구분","내용"],"rows":[["공백기술 도출","특정 기술 분야에서 아직 개발되지 않았거나 특허로 보호되지 않은 영역을 찾아 연구개발의 새 기회를 식별하는 과정이다"],["공백기술","유효특허를 기술분류체계에 따라 분류했을 때 특허 데이터가 발생하지 않는 세부 요소기술이 있으면 그 기술을 공백기술로 볼 수 있다"],["제외","매트릭스에서 특허가 없는 칸이라도 기술구현이 어렵거나 기술이 서로 모순되는 부분은 공백기술에서 제외한다"]]},{"t":"vs","title":"포트폴리오 보완","cols":[{"name":"경쟁사의 포트폴리오가 취약한 경우","items":["관련 기술의 길목특허와 개량특허를 출원해 경쟁사의 핵심특허를 포위함으로써 견제할 수 있다"]},{"name":"자사 핵심특허의 포트폴리오가 취약한 경우","items":["관련 기술의 출원을 늘려 특허망의 취약점을 보완하며, 핵심특허가 만료되어도 길목·개량특허가 경쟁사의 접근을 어렵게 한다"]}]}]};
